-- Every module below is a file from the repository, concatenated unchanged
-- inside its own do-block so its locals cannot collide with the next one. The
-- only values that escape are the ones stored in `Modules`, which FatCatInit
-- reads. If you are debugging a module, edit the file under src/project/ and
-- rebuild; editing this file is editing a build artifact.

local Modules = {}

-- ---------------------------------------------------------------------
-- FatCatSignal.lua
-- ---------------------------------------------------------------------
do
	local module = (function()
		-- Fat Cat Project | Core & Initialization/FatCatSignal.lua
		--
		-- Pub/Sub for the whole project. One object per event, three verbs.
		--
		--   local Signal = FatCat.require("FatCatSignal")
		--   local changed = Signal.new("config:changed")
		--   local link = changed:Connect(function(value) print(value) end)
		--   changed:Fire("accent")
		--   link:Disconnect()
		--
		-- Why not just a table of callbacks: a module that is torn down during
		-- Unload must not leave another module parked in Wait(), and a callback that
		-- throws must not swallow the callbacks registered after it. Both rules are
		-- enforced here, once, so no feature module has to think about them.
		--
		--   * Fire copies the dispatch list first, so Connect/Disconnect from inside
		--     a callback is safe and a link cut mid-fire stops receiving immediately;
		--   * every callback runs under pcall, and the error is handed to
		--     Signal.errorHandler when one is installed (FatCatConsole installs it);
		--   * Wait() resolves on the next Fire *or* on Destroy, so teardown cannot
		--     strand a coroutine.

		local Signal = {}
		Signal.__index = Signal

		---Installed by FatCatConsole so a broken callback is visible instead of silent.
		Signal.errorHandler = nil

		local function reportError(name, message)
			local handler = Signal.errorHandler
			if type(handler) == "function" then
				pcall(handler, name, message)
			end
		end

		---Create a signal. `name` only shows up in diagnostics and the console.
		function Signal.new(name)
			return setmetatable({
				name = name or "signal",
				_links = {},
				_waiters = {},
				_destroyed = false,
			}, Signal)
		end

		---Connect `callback`. Returns a link with :Disconnect().
		function Signal:Connect(callback)
			if type(callback) ~= "function" then
				error("Signal:Connect expects a function, got " .. type(callback), 2)
			end
			if self._destroyed then
				-- Connecting to a dead signal is a caller bug, not a crash: hand back
				-- an inert link so their code still runs to completion.
				return { Connected = false, Disconnect = function() end }
			end

			local link = { Connected = true, _signal = self, _callback = callback }
			table.insert(self._links, link)

			function link:Disconnect()
				if not self.Connected then
					return
				end
				self.Connected = false
				local links = self._signal._links
				for index = #links, 1, -1 do
					if links[index] == self then
						table.remove(links, index)
						return
					end
				end
			end

			return link
		end

		---Connect for a single fire, then disconnect itself.
		function Signal:Once(callback)
			local link
			link = self:Connect(function(...)
				link:Disconnect()
				callback(...)
			end)
			return link
		end

		---Fire every callback in connection order.
		function Signal:Fire(...)
			if self._destroyed then
				return
			end
			local snapshot = table.clone(self._links)
			for _, link in snapshot do
				if link.Connected then
					local ok, err = pcall(link._callback, ...)
					if not ok then
						reportError(self.name, tostring(err))
					end
				end
			end
			-- Waiters are one-shot: hand them the values and drop them.
			if #self._waiters > 0 then
				local waiters = self._waiters
				self._waiters = {}
				for _, waiter in waiters do
					if waiter.Connected then
						waiter.Connected = false
						local thread = waiter._thread :: thread?
						if thread and coroutine.status(thread) == "suspended" then
							task.spawn(thread, ...)
						end
					end
				end
			end
		end

		---Yields until the next Fire. Returns the fired values, or nothing at all if
		---the signal is destroyed while waiting.
		function Signal:Wait()
			if self._destroyed then
				return
			end
			local thread = coroutine.running()
			-- A waiter is its own record, not a Connect()ed callback: a callback would
			-- be invoked by Fire and would resume its own thread from *inside* the
			-- dispatch loop, which is how you get "cannot resume non-suspended
			-- coroutine" when two signals are involved. Fire collects the queue and
			-- hands the values to whichever coroutine asks for them next.
			local waiter = { _thread = thread, Connected = true }
			table.insert(self._waiters, waiter)
			return coroutine.yield()
		end

		---Stop accepting connections, drop every link, and release any Wait().
		function Signal:Destroy()
			if self._destroyed then
				return
			end
			self._destroyed = true
			for _, link in self._links do
				link.Connected = false
			end
			table.clear(self._links)
			for _, waiter in self._waiters do
				local thread = waiter._thread :: thread?
				if thread and coroutine.status(thread) == "suspended" then
					task.spawn(thread)
				end
			end
			table.clear(self._waiters)
		end

		---True when at least one live connection exists.
		function Signal:HasConnections()
			return #self._links > 0
		end

		---Live connection count. The harness uses it to prove Unload dropped them.
		function Signal:Count()
			return #self._links
		end

		return Signal
	end)()
	Modules['FatCatSignal'] = module
end
-- ---------------------------------------------------------------------
-- FatCatCore.lua
-- ---------------------------------------------------------------------
do
	local module = (function()
		-- Fat Cat Project | Core & Initialization/FatCatCore.lua
		--
		-- The single global the project hangs off: service registry, module cache,
		-- shared state, and one teardown that runs in reverse load order.
		--
		--   local Core = FatCat                     -- set by FatCatInit
		--   local Config = Core.require("FatCatConfig")
		--   Core:OnDestroy("my module", function() ... end)
		--
		-- Three rules this file exists to enforce:
		--
		--   1. Load once, in any order. `require` caches a module table, remembers a
		--      module that failed (so a second caller gets the first error instead of
		--      retrying into a different failure), and refuses a cycle with a readable
		--      message rather than blowing the stack.
		--
		--   2. Everything that allocates registers a teardown. A leftover Connection,
		--      a running RenderStepped, or a frame still parented to CoreGui is the
		--      difference between "unloaded" and "still running under the map".
		--
		--   3. State lives here, not in module locals. `Core.state.selectedScript` is
		--      shared by the inspector, the decompiler and the console; three copies
		--      of the same local would drift apart on the first rebuild.

		local Core = {}
		Core.VERSION = "2.1.0"
		Core.NAME = "Fat Cat"
		Core.TAG = "[Fat Cat]"

		-- Executor environment: getgenv() when the executor provides it, _G otherwise.
		-- FatCatInit may replace this before any module loads.
		Core.env = (typeof(getgenv) == "function" and getgenv()) or _G

		Core.modules = {}     -- path -> module table
		Core.loadErrors = {}  -- path -> message
		Core.loadOrder = {}   -- paths, in load order
		Core.teardowns = {}   -- { { name = string, run = function }, ... }
		Core.services = {}    -- name -> any (window, connections, threads)
		Core.state = {}       -- shared scratch: selectedScript, theme, executor, ...
		Core.destroyed = false

		-- ==========================================================================
		-- Logging
		-- ==========================================================================
		-- Console installs a real sink; before that, errors go to warn() so a module
		-- that fails during boot still leaves a trace in the executor log.

		Core.logSink = nil

		function Core:SetLogger(sink)
			self.logSink = sink
		end

		function Core:Log(level, message, ...)
			local sink = self.logSink
			if type(sink) == "function" then
				if pcall(sink, level, message, ...) then
					return
				end
			end
			if level == "error" or level == "warn" then
				pcall(warn, ("%s %s"):format(self.TAG, tostring(message)))
			end
		end

		-- ==========================================================================
		-- Services
		-- ==========================================================================
		-- Named singletons with a teardown attached: `Core:SetService("window", w)`
		-- then `Core:GetService("window")`. Registering the same name twice destroys
		-- the previous value first, which is what makes rebuilds safe.

		function Core:SetService(name, value, teardown)
			local previous = self.services[name]
			if previous ~= nil and teardown == nil then
				-- No teardown supplied: the caller owns both values, just replace it.
				self.services[name] = value
				return value
			end
			if previous ~= nil and teardown ~= nil and type(previous.Destroy) == "function" then
				pcall(function()
					previous:Destroy()
				end)
			end
			self.services[name] = value
			if type(teardown) == "function" then
				self:OnDestroy("service:" .. name, teardown)
			end
			return value
		end

		function Core:GetService(name)
			return self.services[name]
		end

		function Core:DropService(name)
			local value = self.services[name]
			self.services[name] = nil
			if value ~= nil and type(value.Destroy) == "function" then
				pcall(function()
					value:Destroy()
				end)
			end
			return value
		end

		-- ==========================================================================
		-- Modules
		-- ==========================================================================

		---Register the loader for a module path. FatCatInit does this for the tree.
		---@param path string       e.g. "FatCatConfig"
		---@param loader function   (core) -> module table
		function Core:Register(path, loader)
			self._loaders = self._loaders or {}
			self._loaders[path] = loader
		end

		---Return the module at `path`, loading it on first use.
		function Core:Require(path)
			if self.modules[path] ~= nil then
				return self.modules[path]
			end
			if self.destroyed then
				error(("%s cannot require '%s' after Unload"):format(self.TAG, path), 2)
			end
			if self.loadErrors[path] then
				error(("%s module '%s' failed earlier: %s"):format(self.TAG, path, self.loadErrors[path]), 2)
			end

			local loader = self._loaders and self._loaders[path]
			if type(loader) ~= "function" then
				error(("%s no module registered as '%s'"):format(self.TAG, path), 2)
			end

			self._loading = self._loading or {}
			if self._loading[path] then
				error(("%s circular require at '%s'"):format(self.TAG, path), 2)
			end
			self._loading[path] = true
			local ok, result = pcall(loader, self)
			self._loading[path] = nil

			if not ok then
				self.loadErrors[path] = tostring(result)
				error(("%s module '%s' failed to load: %s"):format(self.TAG, path, tostring(result)), 2)
			end
			if result == nil then
				result = true
			end

			self.modules[path] = result
			table.insert(self.loadOrder, path)
			self:Log("debug", "loaded " .. path)
			return result
		end

		---Never throws: returns the module, or nil plus the reason it failed.
		function Core:TryRequire(path)
			local ok, result = pcall(self.Require, self, path)
			if ok then
				return result
			end
			return nil, tostring(result)
		end

		Core.require = Core.Require

		---True when the module is already in the cache.
		function Core:IsLoaded(path)
			return self.modules[path] ~= nil
		end

		-- ==========================================================================
		-- Teardown
		-- ==========================================================================

		---Register teardown work. Runs newest-first, each under pcall, so one
		---failure cannot strand the modules registered before it.
		function Core:OnDestroy(name, run)
			if self.destroyed then
				pcall(run)
				return
			end
			table.insert(self.teardowns, { name = name or ("teardown #" .. (#self.teardowns + 1)), run = run })
		end

		function Core:IsDestroyed()
			return self.destroyed
		end

		---Tear the project down. Returns how many teardowns ran.
		function Core:Destroy()
			if self.destroyed then
				return 0
			end
			self.destroyed = true

			local ran, failed = 0, 0
			for index = #self.teardowns, 1, -1 do
				local entry = self.teardowns[index]
				local ok, err = pcall(entry.run)
				ran += 1
				if not ok then
					failed += 1
					self:Log("error", ("teardown '%s' failed: %s"):format(tostring(entry.name), tostring(err)))
				end
			end
			table.clear(self.teardowns)
			table.clear(self.services)
			table.clear(self.modules)
			table.clear(self.loadOrder)
			table.clear(self.state)

			-- Only release the global if it is still us: a reload may have replaced
			-- it while our teardown was running.
			if _G.FatCatProject == self then
				_G.FatCatProject = nil
			end
			if failed > 0 then
				self:Log("warn", ("Unload finished with %d failed teardown(s)"):format(failed))
			end
			return ran
		end

		---`Fat Cat 2.1.0 · 9 modules` for a status row.
		function Core:Describe()
			return ("%s %s · %d module(s)"):format(self.NAME, self.VERSION, #self.loadOrder)
		end

		return Core
	end)()
	Modules['FatCatCore'] = module
end
-- ---------------------------------------------------------------------
-- FatCatEnv.lua
-- ---------------------------------------------------------------------
do
	local module = (function()
		-- Fat Cat Project | Core & Initialization/FatCatEnv.lua
		--
		-- The executor boundary: one place that touches capabilities the base game
		-- does not have, so every module above it can stay plain Luau.
		--
		--   local Env = FatCat.require("FatCatEnv")
		--   Env.name                 -- "synapse", "Solara", or "unknown"
		--   Env.has("hookfunction")  -- boolean, checked once and cached
		--   Env.unload()             -- the whole product, in the right order
		--
		-- Nothing here pokes at metatables, hooks game methods, or edits the global
		-- environment. It *detects* what is available and *reports* it. The detection
		-- helpers exist because the analysis modules need to know whether a hook is
		-- possible before they offer a button that would otherwise do nothing.
		--
		-- Unload order matters and is the reason this module exists at all:
		--
		--   1. stop the render loop           (the harness owns it, via Core)
		--   2. drop the window                (the shell, via Hub:Destroy)
		--   3. run module teardowns           (reverse load order, via Core:Destroy)
		--   4. clear the project global       (last, so step 3 could still reach it)
		--
		-- Doing 4 before 3 is the classic unload bug: a module's teardown then reads
		-- a nil global and throws into the void.

		local Core, Env
		Env = {}

		---Capabilities this product actually uses. A capability that is not listed is
		---reported as false even if the executor has it, so a typo cannot silently
		---turn into "supported".
		Env.CAPABILITIES = {
			"writefile", "readfile", "isfile", "makefolder", "delfile", "appendfile",
			"getgenv", "getrenv", "getreg", "getgc", "getinstances", "getnilinstances",
			"getloadedmodules", "getscriptbytecode", "getscriptclosure", "getscripts",
			"hookfunction", "hookmetamethod", "replaceclosure", "newcclosure",
			"getrawmetatable", "setreadonly", "isreadonly", "getnamecallmethod",
			"setnamecallmethod", "checkcaller", "islclosure", "iscclosure",
			"getconnections", "firesignal", "fireclickdetector", "firetouchinterest",
			"queue_on_teleport", "setclipboard", "identifyexecutor", "request",
			"http_request", "syn", "fluxus", "is_sirhurt_closure", "getthreadidentity",
			"setthreadidentity",
		}

		-- Name -> executor label. First match wins; the order puts the specific
		-- identifiers before the generic ones so a Synapse fork that also defines
		-- `fluxus` is still reported as what it is.
		local IDENTIFIERS = {
			{ "synapse", "Synapse X" },
			{ "krnl", "Krnl" },
			{ "fluxus", "Fluxus" },
			{ "solara", "Solara" },
			{ "swift", "Swift" },
			{ "wave", "Wave" },
			{ "codex", "Codex" },
			{ "hydrogen", "Hydrogen" },
			{ "delta", "Delta" },
			{ "arcturus", "Arcturus" },
			{ "sirhurt", "SirHurt" },
			{ "electron", "Electron" },
			{ "scriptware", "ScriptWare" },
		}

		Env.name = "unknown"
		Env.caps = {}
		Env.detectedAt = os.clock()

		---True when the executor exposes `name` as a function.
		function Env.has(name)
			if Env.caps[name] == nil then
				Env.caps[name] = type(Core.env[name]) == "function"
			end
			return Env.caps[name]
		end

		---The live function, or nil. Prefer this over indexing Core.env directly:
		---the cache is invalidated when the environment is re-inspected.
		function Env.fn(name)
			if not Env.has(name) then
				return nil
			end
			return Core.env[name]
		end

		---First working file-API call, with a clear error when there is none.
		function Env.fs(name, ...)
			local impl = Env.fn(name)
			if not impl then
				return false, ("this executor has no %s()"):format(name)
			end
			local ok, result = pcall(impl, ...)
			if not ok then
				return false, tostring(result)
			end
			return true, result
		end

		---Identify the executor. Detection is cheap and runs once at boot; the name
		---is shown on the Home tab and stored in Core.state for telemetry-free logs.
		function Env.detect()
			Env.caps = {}
			for _, capability in Env.CAPABILITIES do
				Env.caps[capability] = type(Core.env[capability]) == "function"
			end

			local label = "unknown"
			local identify = Env.fn("identifyexecutor")
			if identify then
				local ok, name = pcall(identify)
				if ok and type(name) == "string" and name ~= "" then
					label = name
				end
			end

			if label == "unknown" then
				for _, pair in IDENTIFIERS do
					if type(Core.env[pair[1]]) ~= "nil" then
						label = pair[2]
						break
					end
				end
			end

			Env.name = label
			Core.state.executor = label
			Core.state.script = "standard"

			-- A handful of executors flag their own identity differently; keep both
			-- spellings so a user's bug report is useful.
			if Env.has("getthreadidentity") then
				local ok, identity = pcall(Core.env.getthreadidentity)
				if ok then
					Core.state.threadIdentity = identity
				end
			end
			return label
		end

		---Capabilities grouped for the Home tab. Returns rows of { label, ok }.
		function Env.summary()
			local groups = {
				{ label = "files", caps = { "writefile", "readfile", "isfile", "makefolder" } },
				{ label = "introspection", caps = { "getgc", "getinstances", "getrawmetatable", "getconnections" } },
				{ label = "hooking", caps = { "hookfunction", "hookmetamethod", "newcclosure" } },
				{ label = "scripts", caps = { "getscriptbytecode", "getscripts", "getloadedmodules" } },
				{ label = "http", caps = { "request", "http_request" } },
			}
			local rows = {}
			for _, group in groups do
				local present, total = 0, #group.caps
				for _, capability in group.caps do
					if Env.has(capability) then
						present += 1
					end
				end
				table.insert(rows, {
					label = ("%s %d/%d"):format(group.label, present, total),
					ok = present == total,
					partial = present > 0 and present < total,
				})
			end
			return rows
		end

		-- ==========================================================================
		-- Unload
		-- ==========================================================================

		---Tear the product down. Safe to call twice, and safe to call from inside a
		---button callback (the window it lives in is destroyed by this).
		function Env.unload()
			Core:Log("info", "unload requested")

			-- 1. Connections and render steps the project owns.
			local stopLoops = Core:GetService("stopLoops")
			if type(stopLoops) == "function" then
				pcall(stopLoops)
			end

			-- 2. The window. Hub:Destroy drops the GUI and every global connection it
			--    made; the project's own components die with their parent. The service
			--    lookup is the project's own registration; the global is what the shell
			--    publishes, and it survives Core:Destroy unless it is torn down here.
			local hub = Core:GetService("hub") or _G.FatCatHub
			if hub then
				local destroy = (hub :: any).Destroy
				if type(destroy) == "function" then
					pcall(destroy, hub)
				end
			end
			local Menu = Core.modules["FatCatMenu"]
			if Menu and type(Menu.unmount) == "function" then
				pcall(Menu.unmount)
			end

			-- 3. Module teardowns, reverse load order.
			local ran = Core:Destroy()

			-- 4. The loader's own unload hook, so the next run starts clean.
			local runtime = Core.env
			if runtime.FatCatProjectUnload == Env.unload then
				runtime.FatCatProjectUnload = nil
			end
			if (runtime :: any).FatCatHubUnload ~= nil and _G.FatCatHub == nil then
				(runtime :: any).FatCatHubUnload = nil
			end

			pcall(print, ("[Fat Cat] unloaded (%d teardown(s))"):format(ran))
			return ran
		end

		---Print a one-line environment report to the executor console. Called by
		---FatCatInit when FatCatVerbose is on.
		function Env.report()
			local caps = 0
			for _, capability in Env.CAPABILITIES do
				if Env.has(capability) then
					caps += 1
				end
			end
			print(("[Fat Cat] executor: %s · %d/%d capabilities · %d module(s)")
				:format(Env.name, caps, #Env.CAPABILITIES, #Core.loadOrder))
		end

		return function(core, _signal)
			Core = core
			return Env
		end
	end)()
	Modules['FatCatEnv'] = module
end
-- ---------------------------------------------------------------------
-- FatCatConfig.lua
-- ---------------------------------------------------------------------
do
	local module = (function()
		-- Fat Cat Project | Core & Initialization/FatCatConfig.lua
		--
		-- Presets on disk. One JSON file per preset, one index that remembers the
		-- order they were created in and which one is active.
		--
		--   FatCatProject/
		--   └── presets/
		--       ├── index.json      { order = {"raid","default"}, active = "raid" }
		--       ├── raid.json       { "aim.fov" = 90, "visual.esp" = true, ... }
		--       └── default.json
		--
		-- The executor filesystem is optional and inconsistent: `writefile` may not
		-- exist at all, `isfile` may lie, and `makefolder` on an existing folder may
		-- throw. Every call goes through a guard, so a missing function becomes a
		-- sentence the user can read on the Settings tab instead of an error deep in
		-- a button callback.

		local Core, Signal, Config
		Config = {}

		Config.FOLDER = "FatCatProject"
		Config.PRESET_DIR = "FatCatProject/presets"
		Config.INDEX = "FatCatProject/presets/index.json"

		-- Executor globals, not Roblox ones, so the analyzer must not assume they
		-- exist. Read lazily through Core.env: this module body runs when the bundle
		-- is *built*, long before FatCatInit constructs the module and hands it the
		-- core, so `local env = Core.env` here would capture nil and every file call
		-- would fail with "attempt to index nil". Nothing at this level may read Core.
		local function env()
			return Core.env
		end

		local function fn(name)
			local value = env()[name]
			if type(value) ~= "function" then
				return nil
			end
			return value
		end

		---Call an executor file function; returns ok, result.
		local function call(name, ...)
			local impl = fn(name)
			if not impl then
				return false, ("this executor has no %s()"):format(name)
			end
			local ok, result = pcall(impl, ...)
			if not ok then
				return false, tostring(result)
			end
			return true, result
		end

		---True when the executor can read and write files at all.
		function Config:Available()
			return fn("writefile") ~= nil and fn("readfile") ~= nil
		end

		---A sentence for the UI when saving is impossible.
		function Config:UnavailableReason()
			if fn("writefile") == nil and fn("readfile") == nil then
				return "this executor exposes neither writefile nor readfile"
			elseif fn("writefile") == nil then
				return "this executor cannot write files"
			end
			return "this executor cannot read files"
		end

		local function ensureFolder(path)
			local ok, reason = call("makefolder", path)
			if ok then
				return true
			end
			-- "folder already exists" is success for our purposes; anything else is
			-- only a problem if writing actually fails later.
			if tostring(reason):lower():find("exist", 1, true) then
				return true
			end
			return false, reason
		end

		-- ==========================================================================
		-- JSON
		-- ==========================================================================
		-- HttpService is the normal path. Some executors block it on the client, and
		-- a few expose the executor's own HttpService table; both are tried before
		-- giving up, because a preset that silently refuses to save is worse than a
		-- slower save.

		local function httpService()
			local ok, service = pcall(function()
				return game:GetService("HttpService")
			end)
			if ok then
				return service
			end
			return nil
		end

		local function encode(value)
			local http = httpService()
			if http then
				local ok, text = pcall(function()
					return http:JSONEncode(value)
				end)
				if ok and type(text) == "string" then
					return text
				end
			end
			local executor = env().HttpService
			if type(executor) == "table" and type(executor.JSONEncode) == "function" then
				local ok, text = pcall(executor.JSONEncode, value)
				if ok and type(text) == "string" then
					return text
				end
			end
			return nil, "JSON could not be encoded (HttpService is unavailable)"
		end

		local function decode(text)
			local http = httpService()
			if http then
				local ok, value = pcall(function()
					return http:JSONDecode(text)
				end)
				if ok then
					return value
				end
			end
			local executor = env().HttpService
			if type(executor) == "table" and type(executor.JSONDecode) == "function" then
				local ok, value = pcall(executor.JSONDecode, text)
				if ok then
					return value
				end
			end
			return nil, "the file is not valid JSON"
		end

		-- ==========================================================================
		-- Files
		-- ==========================================================================

		---Read one JSON file. Returns value, or nil plus a reason.
		function Config:ReadJSON(path)
			if not self:Available() then
				return nil, self:UnavailableReason()
			end

			local isFile = fn("isfile")
			if isFile then
				local ok, exists = pcall(isFile, path)
				if not ok then
					return nil, ("isfile('%s') failed: %s"):format(path, tostring(exists))
				end
				if not exists then
					return nil, "no file at " .. path
				end
			end

			local ok, text = call("readfile", path)
			if not ok then
				return nil, tostring(text)
			end
			if type(text) ~= "string" or text == "" then
				return nil, path .. " is empty"
			end
			return decode(text)
		end

		---Write one JSON file. Returns true, or false plus a reason.
		function Config:WriteJSON(path, value)
			if not self:Available() then
				return false, self:UnavailableReason()
			end
			ensureFolder(self.FOLDER)
			ensureFolder(self.PRESET_DIR)

			local text, encodeError = encode(value)
			if not text then
				return false, encodeError
			end
			local ok, writeError = call("writefile", path, text)
			if not ok then
				return false, tostring(writeError)
			end
			return true
		end

		-- ==========================================================================
		-- Index
		-- ==========================================================================

		local function blankIndex()
			return { order = {}, active = nil }
		end

		---The index, repaired in memory when the file is missing or malformed.
		function Config:Index()
			local data = self:ReadJSON(self.INDEX)
			if type(data) ~= "table" then
				return blankIndex()
			end
			local index = blankIndex()
			if type(data.order) == "table" then
				for _, name in data.order do
					if type(name) == "string" then
						table.insert(index.order, name)
					end
				end
			end
			if type(data.active) == "string" then
				index.active = data.active
			end
			return index
		end

		local function positionOf(list, needle)
			for index, value in list do
				if value == needle then
					return index
				end
			end
			return nil
		end

		---Preset names in index order, plus the active one.
		function Config:List()
			local index = self:Index()
			return table.clone(index.order), index.active
		end

		function Config:Active()
			return (self:Index()).active
		end

		-- ==========================================================================
		-- Presets
		-- ==========================================================================
		-- Names become file names, so anything that could leave the folder, start
		-- with a dot, or break a shell is refused up front instead of being silently
		-- rewritten into something the user did not type.

		local NAME_PATTERN = "^[%w][%w%-_ ]*$"
		local NAME_LIMIT = 40

		local function validName(name)
			if type(name) ~= "string" then
				return false, "the preset name must be text"
			end
			local trimmed = name:gsub("^%s+", ""):gsub("%s+$", "")
			if trimmed == "" then
				return false, "the preset name is empty"
			end
			if #trimmed > NAME_LIMIT then
				return false, ("the name is longer than %d characters"):format(NAME_LIMIT)
			end
			if not trimmed:match(NAME_PATTERN) then
				return false, "use letters, numbers, spaces, - and _ only"
			end
			-- Windows executors reject these outright; catching them here gives a
			-- better message than a writefile error.
			local reserved = { ["con"] = true, ["prn"] = true, ["aux"] = true, ["nul"] = true }
			if reserved[trimmed:lower()] then
				return false, ("'%s' is a reserved file name"):format(trimmed)
			end
			return true, trimmed
		end
		Config.validName = validName

		function Config:Path(name)
			return ("%s/%s.json"):format(self.PRESET_DIR, name)
		end

		---Save `values` as `name`. Returns true, or false plus a reason.
		function Config:SavePreset(name, values)
			local ok, cleanOrReason = validName(name)
			if not ok then
				return false, cleanOrReason
			end
			local clean = cleanOrReason

			if type(values) ~= "table" then
				return false, "there is nothing to save"
			end

			-- Only serialisable leaves: a flag whose value is a Color3 or a table with
			-- a metatable would make JSONEncode throw halfway through the file.
			local payload = {}
			local count = 0
			for flag, value in values do
				local kind = type(value)
				if kind == "string" or kind == "number" or kind == "boolean" then
					payload[flag] = value
					count += 1
				end
			end
			if count == 0 then
				return false, "no text, number or boolean values to save"
			end

			local written, writeError = self:WriteJSON(self:Path(clean), payload)
			if not written then
				return false, writeError
			end

			local index = self:Index()
			if not positionOf(index.order, clean) then
				table.insert(index.order, clean)
			end
			index.active = clean
			self:WriteJSON(self.INDEX, index)

			self:Changed("save", clean)
			return true, count
		end

		---Load a preset. Returns the values table, or nil plus a reason.
		function Config:LoadPreset(name)
			local ok, cleanOrReason = validName(name)
			if not ok then
				return nil, cleanOrReason
			end
			local clean = cleanOrReason

			local data, readError = self:ReadJSON(self:Path(clean))
			if type(data) ~= "table" then
				return nil, readError or "the preset is not a table"
			end

			local index = self:Index()
			if index.active ~= clean then
				index.active = clean
				self:WriteJSON(self.INDEX, index)
			end

			self:Changed("load", clean)
			return data
		end

		---Delete a preset and drop it from the index. True even when the file cannot
		---be removed: the index no longer lists it, which is what the user sees.
		function Config:DeletePreset(name)
			local ok, cleanOrReason = validName(name)
			if not ok then
				return false, cleanOrReason
			end
			local clean = cleanOrReason

			local index = self:Index()
			local at = positionOf(index.order, clean)
			if at then
				table.remove(index.order, at)
			end
			if index.active == clean then
				index.active = index.order[1]
			end
			self:WriteJSON(self.INDEX, index)

			local remove = fn("delfile") or fn("deletefile")
			if remove then
				pcall(remove, self:Path(clean))
			end

			self:Changed("delete", clean)
			return true
		end

		---Rename keeps the index position and the file contents.
		function Config:RenamePreset(name, newName)
			local ok, cleanOrReason = validName(name)
			if not ok then
				return false, cleanOrReason
			end
			local okNew, newCleanOrReason = validName(newName)
			if not okNew then
				return false, newCleanOrReason
			end
			local clean, newClean = cleanOrReason, newCleanOrReason

			if clean == newClean then
				return true
			end
			local values, readError = self:ReadJSON(self:Path(clean))
			if type(values) ~= "table" then
				return false, readError or "the preset could not be read"
			end

			local written, writeError = self:WriteJSON(self:Path(newClean), values)
			if not written then
				return false, writeError
			end

			local index = self:Index()
			local at = positionOf(index.order, clean)
			if at then
				index.order[at] = newClean
			else
				table.insert(index.order, newClean)
			end
			if index.active == clean then
				index.active = newClean
			end
			self:WriteJSON(self.INDEX, index)

			local remove = fn("delfile") or fn("deletefile")
			if remove then
				pcall(remove, self:Path(clean))
			end

			self:Changed("rename", newClean)
			return true
		end

		-- ==========================================================================
		-- Change notification
		-- ==========================================================================

		-- Created in the factory, not here: the module body runs before FatCatInit
		-- exists, so `Signal` is still nil at this point in the file.
		Config.changed = nil

		function Config:Changed(kind, name)
			self.changed:Fire(kind, name)
		end

		return function(core, signal)
			Core = core
			Signal = signal
			Config.changed = Signal.new("config:changed")
			return Config
		end
	end)()
	Modules['FatCatConfig'] = module
end
-- ---------------------------------------------------------------------
-- FatCatDesign.lua
-- ---------------------------------------------------------------------
do
	local module = (function()
		-- Fat Cat Project | UI & Styling Engine/FatCatDesign.lua
		--
		-- Palettes, type scale, spacing, and every animation curve in the project.
		-- Pure data plus the few helpers that turn a palette name into tables.
		--
		--   local Design = FatCat.require("FatCatDesign")
		--   Design.color("card")        -- Color3
		--   Design.apply("glacier")     -- swap palette, fire design:changed
		--   Design.contrast(Design.color("text"), Design.color("card"))
		--
		-- A component that hardcodes a Color3 is a bug: it stops following a theme
		-- switch, and the design audit cannot check a colour it cannot see. Everything
		-- visual reads from `Design.theme`.

		local Design, Signal
		Design = {}

		-- ==========================================================================
		-- Palettes
		-- ==========================================================================
		-- Same keys in every palette, so a switch is a swap and never a merge.
		-- `ember` reproduces the shell in src/FatCatHub.lua exactly; the other two
		-- exist because the ember accent disappears on lava maps and on bright skies,
		-- and because some users want zero hue at all.

		Design.palettes = {
			-- Exact copy of the shell's THEME in src/FatCatHub.lua. This is the
			-- default because the two halves of the product must open looking the
			-- same; a preset can move away from it, nothing should drift into it.
			classic = {
				backgroundTop = Color3.fromRGB(26, 26, 30),
				backgroundBottom = Color3.fromRGB(12, 12, 14),
				card = Color3.fromRGB(38, 38, 43),
				cardHover = Color3.fromRGB(47, 47, 53),
				element = Color3.fromRGB(19, 19, 22),
				elementHover = Color3.fromRGB(45, 45, 51),
				chip = Color3.fromRGB(28, 28, 32),
				section = Color3.fromRGB(17, 17, 20),
				outline = Color3.fromRGB(104, 104, 114),
				text = Color3.fromRGB(240, 240, 243),
				textOff = Color3.fromRGB(198, 198, 204),
				textDim = Color3.fromRGB(126, 126, 134),
				accent = Color3.fromRGB(236, 236, 240),
				accentAlt = Color3.fromRGB(138, 138, 148),
				positive = Color3.fromRGB(124, 222, 146),
				negative = Color3.fromRGB(232, 92, 96),
				onAccent = Color3.fromRGB(18, 18, 21),
			},
			ember = {
				backgroundTop = Color3.fromRGB(26, 26, 30),
				backgroundBottom = Color3.fromRGB(12, 12, 14),
				card = Color3.fromRGB(38, 38, 43),
				cardHover = Color3.fromRGB(47, 47, 53),
				element = Color3.fromRGB(19, 19, 22),
				elementHover = Color3.fromRGB(45, 45, 51),
				chip = Color3.fromRGB(28, 28, 32),
				section = Color3.fromRGB(17, 17, 20),
				outline = Color3.fromRGB(104, 104, 114),
				text = Color3.fromRGB(240, 240, 243),
				textOff = Color3.fromRGB(198, 198, 204),
				textDim = Color3.fromRGB(126, 126, 134),
				accent = Color3.fromRGB(255, 138, 61),
				accentAlt = Color3.fromRGB(255, 72, 96),
				positive = Color3.fromRGB(125, 222, 145),
				negative = Color3.fromRGB(232, 92, 98),
				onAccent = Color3.fromRGB(18, 18, 21),
			},
			glacier = {
				backgroundTop = Color3.fromRGB(22, 26, 34),
				backgroundBottom = Color3.fromRGB(10, 13, 18),
				card = Color3.fromRGB(34, 40, 50),
				cardHover = Color3.fromRGB(43, 51, 63),
				element = Color3.fromRGB(16, 20, 26),
				elementHover = Color3.fromRGB(40, 48, 60),
				chip = Color3.fromRGB(25, 30, 38),
				section = Color3.fromRGB(14, 18, 23),
				outline = Color3.fromRGB(98, 112, 132),
				text = Color3.fromRGB(237, 243, 250),
				textOff = Color3.fromRGB(193, 203, 216),
				textDim = Color3.fromRGB(126, 138, 154),
				accent = Color3.fromRGB(94, 194, 255),
				accentAlt = Color3.fromRGB(120, 132, 255),
				positive = Color3.fromRGB(125, 222, 145),
				negative = Color3.fromRGB(232, 92, 98),
				onAccent = Color3.fromRGB(12, 18, 24),
			},
		}

		Design.order = { "classic", "ember", "glacier" }
		Design.current = "classic"
		Design.theme = table.clone(Design.palettes.classic)

		-- ==========================================================================
		-- Type, spacing, radius
		-- ==========================================================================
		-- The same numbers the shell uses. A 13 px label must be 13 px on both sides
		-- of the product or the two screens stop reading as one app.

		Design.text = {
			title = 14,
			tab = 13,
			label = 13,
			value = 13,
			body = 12,
			section = 11,
			hint = 11,
			code = 11,
		}

		Design.radius = { window = 12, card = 8, chip = 5, field = 5, pill = 999 }

		-- A 4 px grid. Every margin in the project is a multiple of it; the audit
		-- reports the ones that are not.
		Design.space = { xs = 4, sm = 8, md = 12, lg = 16, xl = 24 }

		Design.fonts = {
			regular = Enum.Font.Gotham,
			medium = Enum.Font.GothamMedium,
			bold = Enum.Font.GothamBold,
			mono = Enum.Font.RobotoMono,
		}

		-- ==========================================================================
		-- Colour access
		-- ==========================================================================

		---Colour from the active palette. A missing key returns magenta: impossible
		---to miss in a screenshot, therefore impossible to ship by accident.
		function Design.color(key)
			return Design.theme[key] or Color3.fromRGB(255, 0, 255)
		end

		function Design.snapshot()
			return table.clone(Design.theme)
		end

		---Switch palette. Returns true, or false plus the list of valid names.
		function Design.apply(name)
			local palette = Design.palettes[name]
			if not palette then
				return false, ("unknown palette '%s' (have: %s)"):format(
					tostring(name), table.concat(Design.order, ", "))
			end
			Design.current = name
			Design.theme = table.clone(palette)
			if Design.changed then
				Design.changed:Fire(name)
			end
			return true
		end

		-- ==========================================================================
		-- Colour maths
		-- ==========================================================================

		---Even blend between the two accents, t in 0..1. Gradients and rails use it.
		function Design.accentMix(t)
			t = math.clamp(t or 0, 0, 1)
			local from, to = Design.theme.accent, Design.theme.accentAlt
			return Color3.new(
				from.R + (to.R - from.R) * t,
				from.G + (to.G - from.G) * t,
				from.B + (to.B - from.B) * t
			)
		end

		---Lighten (factor > 0) or darken (factor < 0), clamped at both ends.
		function Design.shade(color, factor)
			if factor >= 0 then
				return Color3.new(
					color.R + (1 - color.R) * factor,
					color.G + (1 - color.G) * factor,
					color.B + (1 - color.B) * factor
				)
			end
			return Color3.new(
				color.R * (1 + factor),
				color.G * (1 + factor),
				color.B * (1 + factor)
			)
		end

		---WCAG relative luminance, 0..1.
		local function luminance(color)
			local function channel(value)
				if value <= 0.03928 then
					return value / 12.92
				end
				return ((value + 0.055) / 1.055) ^ 2.4
			end
			return 0.2126 * channel(color.R)
				+ 0.7152 * channel(color.G)
				+ 0.0722 * channel(color.B)
		end
		Design.luminance = luminance

		---Contrast ratio between two colours, 1..21. The audit floor for HUD text is
		---3:1; the Console tab shows the live number for the current palette.
		function Design.contrast(a, b)
			local la, lb = luminance(a), luminance(b)
			local high, low = math.max(la, lb), math.min(la, lb)
			return (high + 0.05) / (low + 0.05)
		end

		---Worst contrast in the palette between a text colour and its surface.
		---Returns ratio, label. Used by the Home status row.
		function Design.auditContrast()
			local theme = Design.theme
			local checks = {
				{ "text on card", theme.text, theme.card },
				{ "label on element", theme.text, theme.element },
				{ "dim on background", theme.textDim, theme.backgroundTop },
				{ "accent on onAccent", theme.accent, theme.onAccent },
			}
			local worstRatio, worstLabel = math.huge, "none"
			for _, check in checks do
				local ratio = Design.contrast(check[2], check[3])
				if ratio < worstRatio then
					worstRatio, worstLabel = ratio, check[1]
				end
			end
			return worstRatio, worstLabel
		end

		-- ==========================================================================
		-- Motion
		-- ==========================================================================
		-- Names, not raw TweenInfos, so reduced motion can flatten all of them in one
		-- place and a component never has to import an easing style.

		local function freshAnim()
			return {
				instant = TweenInfo.new(0),
				fast = TweenInfo.new(0.12, Enum.EasingStyle.Quad, Enum.EasingDirection.Out),
				medium = TweenInfo.new(0.28, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
				open = TweenInfo.new(0.34, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
				pop = TweenInfo.new(0.24, Enum.EasingStyle.Back, Enum.EasingDirection.Out),
			}
		end

		Design.anim = freshAnim()
		Design.reducedMotion = false

		---TweenInfo by name. An unknown name returns `fast`, so a typo cannot
		---silently disable an animation.
		function Design.tween(name)
			return Design.anim[name] or Design.anim.fast
		end

		---Flatten every animation to zero duration (accessibility, and the harness).
		function Design.setReducedMotion(reduced)
			Design.reducedMotion = reduced and true or false
			if Design.reducedMotion then
				for name in Design.anim do
					Design.anim[name] = TweenInfo.new(0)
				end
			else
				Design.anim = freshAnim()
			end
		end

		-- ==========================================================================
		-- Surface helpers
		-- ==========================================================================

		---A UIGradient that fades a frame toward its edges, used on dividers and the
		---window backdrop so the background does not end in a hard line.
		function Design.fade(transparency, target)
			local gradient = Instance.new("UIGradient")
			gradient.Transparency = NumberSequence.new({
				NumberSequenceKeypoint.new(0, transparency or 1),
				NumberSequenceKeypoint.new(0.5, 0.15),
				NumberSequenceKeypoint.new(1, transparency or 1),
			})
			gradient.Parent = target
			return gradient
		end

		---Vertical accent gradient for a rail or a filled track.
		function Design.accentGradient(target, vertical)
			local gradient = Instance.new("UIGradient")
			gradient.Color = ColorSequence.new({
				ColorSequenceKeypoint.new(0, Design.color("accent")),
				ColorSequenceKeypoint.new(1, Design.color("accentAlt")),
			})
			gradient.Rotation = vertical and 90 or 0
			gradient.Parent = target
			return gradient
		end

		return function(_core, signal)
			Signal = signal
			Design.changed = Signal.new("design:changed")
			-- Colours changed: re-apply the palette to every component that asked.
			return Design
		end
	end)()
	Modules['FatCatDesign'] = module
end
-- ---------------------------------------------------------------------
-- FatCatMaterials.lua
-- ---------------------------------------------------------------------
do
	local module = (function()
		-- Fat Cat Project | UI & Styling Engine/FatCatMaterials.lua
		--
		-- The component library: every interactive thing in the project is built from
		-- these, and nothing else in the tree calls Instance.new for UI.
		--
		--   local M = FatCat.require("FatCatMaterials")
		--   M.Button(section, { Text = "Run", OnClick = run })
		--   M.Toggle(section, { Text = "ESP", Flag = "visual.esp", OnChange = ... })
		--   M.Slider(section, { Text = "FOV", Min = 40, Max = 140, Default = 70 })
		--
		-- Why not reuse the shell's Components? Because the shell's are closures over
		-- its own THEME local, captured when the module loaded: they cannot follow a
		-- palette switch and they cannot be unit tested without the whole window.
		-- These read Design.color on demand, take an explicit parent, and return a
		-- handle with :Set/:Get/:Destroy so a rebuild can drop them cleanly.
		--
		-- Every component:
		--   * sizes itself on the 4 px grid and never overlaps its neighbour;
		--   * takes { Flag }, and registers its setter with the owning section when
		--     one is passed, so presets can drive it;
		--   * returns { Instance, Set, Get, Destroy }.

		local Core, Design, Materials
		Materials = {}

		local function create(className, properties, parent)
			local instance = Instance.new(className)
			for key, value in properties or {} do
				(instance :: any)[key] = value
			end
			if parent then
				instance.Parent = parent
			end
			return instance
		end

		local function corner(instance, radius)
			create("UICorner", { CornerRadius = UDim.new(0, radius or Design.radius.card) }, instance)
		end

		local function stroke(instance, color, transparency)
			return create("UIStroke", {
				Color = color or Design.color("outline"),
				Transparency = transparency or 0.6,
				ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
			}, instance)
		end

		---Standard label: 13 px, left aligned, truncated rather than overflowing.
		local function label(parent, text, size, color, position, width)
			return create("TextLabel", {
				Text = tostring(text),
				TextSize = size or Design.text.label,
				Font = Design.fonts.regular,
				TextColor3 = color or Design.color("text"),
				TextXAlignment = Enum.TextXAlignment.Left,
				TextYAlignment = Enum.TextYAlignment.Center,
				TextTruncate = Enum.TextTruncate.AtEnd,
				BackgroundTransparency = 1,
				Size = width or UDim2.new(1, 0, 1, 0),
				Position = position or UDim2.new(),
			}, parent)
		end

		---Recolour a frame with a tween when the engine has that method. Falls back
		---to an instant set so the same code runs under a test stub.
		local function tintTo(instance, color, tweenInfo)
			local method = (instance :: any).TweenBackgroundColor3
			if type(method) == "function" then
				method(instance, tweenInfo or Design.tween("fast"), color)
			else
				instance.BackgroundColor3 = color
			end
		end

		---Every component returns this shape: { Instance, Set, Get, Destroy }.
		---
		---Call them with a colon: `handle:Set(70)`, `handle:Get()`. The methods below
		---are written as `Set = function(self, value)` rather than
		---`function handle:Set(value)` for the same result, but the `self` parameter
		---is explicit - omitting it is the bug that shifts every argument by one when
		---the caller uses `:`, and it is silent: the value arrives in `self`, the real
		---parameter is nil, and a numeric setter's guard swallows it.
		local function handle(instance, setter, getter)
			local self = {
				Instance = instance,
			}

			self.Set = function(_, value)
				if setter then
					setter(value)
				end
			end

			self.Get = function(_)
				if getter then
					return getter()
				end
				return nil
			end

			self.Destroy = function(_)
				if instance and instance.Parent then
					instance:Destroy()
				end
			end

			return self
		end

		-- ==========================================================================
		-- Section binding
		-- ==========================================================================
		-- A Section is { frame, setters, values }. Components register their setter
		-- there so a preset load can drive every control on a tab at once, without
		-- walking the instance tree looking for matches.

		---Create a section box with the design's own chrome.
		function Materials.Section(parent, title, height)
			local box = create("Frame", {
				Name = tostring(title),
				Size = UDim2.new(1, 0, 0, height or 0),
				AutomaticSize = Enum.AutomaticSize.Y,
				BackgroundColor3 = Design.color("section"),
				BackgroundTransparency = 0.25,
				BorderSizePixel = 0,
				LayoutOrder = #parent:GetChildren() + 1,
			}, parent)
			corner(box, Design.radius.card)
			create("UIPadding", {
				PaddingTop = UDim.new(0, 8),
				PaddingBottom = UDim.new(0, 8),
				PaddingLeft = UDim.new(0, 8),
				PaddingRight = UDim.new(0, 8),
			}, box)
			create("UIListLayout", {
				Padding = UDim.new(0, Design.space.xs + 2),
				SortOrder = Enum.SortOrder.LayoutOrder,
			}, box)

			local header = create("TextLabel", {
				Text = tostring(title):upper(),
				TextSize = Design.text.section,
				Font = Design.fonts.bold,
				TextColor3 = Design.color("textDim"),
				TextXAlignment = Enum.TextXAlignment.Left,
				BackgroundTransparency = 1,
				Size = UDim2.new(1, 0, 0, 14),
				LayoutOrder = 0,
			}, box)

			return {
				frame = box,
				header = header,
				setters = {},
				values = {},
				Register = function(section, flag, setter, getter)
					if not flag then
						return
					end
					section.setters[flag] = setter
					if getter then
						section.values[flag] = getter
					end
				end,
				Apply = function(section, values)
					for flag, value in values do
						local setter = section.setters[flag]
						if setter then
							pcall(setter, value)
						end
					end
				end,
			}
		end

		-- ==========================================================================
		-- Button
		-- ==========================================================================
		-- options: Text, Description, OnClick, Danger, Height

		function Materials.Button(parent, options)
			options = options or {}
			local height = options.Height or (options.Description and 48 or 32)
			local button = create("TextButton", {
				Text = "",
				AutoButtonColor = false,
				BackgroundColor3 = options.Danger and Design.color("negative") or Design.color("card"),
				BackgroundTransparency = options.Danger and 0.55 or 0.15,
				BorderSizePixel = 0,
				Size = UDim2.new(1, 0, 0, height),
				LayoutOrder = #parent:GetChildren() + 1,
			}, parent)
			corner(button, Design.radius.field)
			local border = stroke(button)

			local title = label(button, options.Text or "Button", Design.text.label, Design.color("text"),
				UDim2.fromOffset(10, options.Description and 6 or 0),
				UDim2.new(1, -20, 0, options.Description and 18 or height))
			title.TextYAlignment = Enum.TextYAlignment.Center
			if options.Description then
				label(button, options.Description, Design.text.hint, Design.color("textDim"),
					UDim2.fromOffset(10, 24), UDim2.new(1, -20, 0, 16))
			end

			local function tint(hovering)
				local target = hovering and Design.color("cardHover") or Design.color("card")
				tintTo(button, target)
				border.Transparency = hovering and 0.35 or 0.6
			end

			button.MouseEnter:Connect(function()
				tint(true)
			end)
			button.MouseLeave:Connect(function()
				tint(false)
			end)
			button.Activated:Connect(function()
				if type(options.OnClick) == "function" then
					local ok, err = pcall(options.OnClick, button)
					if not ok then
						Core:Log("error", "button '" .. tostring(options.Text) .. "': " .. tostring(err))
					end
				end
			end)

			local self = handle(button, nil, nil)
			-- Assignment, not `function self.X(...)`: when the caller writes
			-- `handle:SetBusy(true)` the method syntax passes `self` first, so the
			-- implicit-self form would shift every argument by one.
			self.SetBusy = function(_, busy)
				button.Active = not busy
				title.TextTransparency = busy and 0.5 or 0
			end
			---Change the caption at runtime (a Run button that becomes Stop).
			self.SetText = function(_, text)
				title.Text = tostring(text)
			end
			return self
		end

		-- ==========================================================================
		-- Toggle
		-- ==========================================================================
		-- options: Text, Description, Default, Flag, OnChange

		function Materials.Toggle(parent, options)
			options = options or {}
			local height = options.Description and 46 or 32
			local card = create("TextButton", {
				Text = "",
				AutoButtonColor = false,
				BackgroundColor3 = Design.color("card"),
				BackgroundTransparency = 0.15,
				BorderSizePixel = 0,
				Size = UDim2.new(1, 0, 0, height),
				LayoutOrder = #parent:GetChildren() + 1,
			}, parent)
			corner(card, Design.radius.field)
			-- The border exists so the row reads as a control at rest; the hover
			-- state below only recolours the fill, and dropping the stroke would make
			-- a disabled-looking row slightly lighter than its neighbours.
			stroke(card)

			-- 18x18 box at x=9: the shell's checkbox, kept identical on purpose so
			-- the project tab and the base tab cannot drift apart.
			local box = create("Frame", {
				Size = UDim2.fromOffset(18, 18),
				Position = UDim2.new(0, 9, 0.5, -9),
				BackgroundColor3 = Design.color("element"),
				BorderSizePixel = 0,
			}, card)
			corner(box, 4)
			local boxBorder = stroke(box, Design.color("outline"), 0.4)

			local tick = label(box, "✓", 12, Design.color("onAccent"), UDim2.new(), UDim2.new(1, 0, 1, 0))
			tick.TextXAlignment = Enum.TextXAlignment.Center
			tick.Font = Design.fonts.bold
			tick.TextTransparency = 1

			local textX = 32
			label(card, options.Text or "Toggle", Design.text.label, Design.color("text"),
				UDim2.fromOffset(textX, options.Description and 6 or 0),
				UDim2.new(1, -textX - 10, 0, options.Description and 18 or height))
			if options.Description then
				label(card, options.Description, Design.text.hint, Design.color("textDim"),
					UDim2.fromOffset(textX, 24), UDim2.new(1, -textX - 10, 0, 16))
			end

			local value = options.Default == true
			local handlers = {}

			local function paint()
				tick.TextTransparency = value and 0 or 1
				box.BackgroundColor3 = value and Design.color("accent") or Design.color("element")
				boxBorder.Color = value and Design.color("accent") or Design.color("outline")
			end

			local function set(nextValue, silent)
				value = nextValue and true or false
				paint()
				if silent then
					return
				end
				for _, handler in handlers do
					local ok, err = pcall(handler, value)
					if not ok then
						Core:Log("error", "toggle '" .. tostring(options.Text) .. "': " .. tostring(err))
					end
				end
			end

			paint()

			card.MouseEnter:Connect(function()
				card.BackgroundColor3 = Design.color("cardHover")
				card.BackgroundTransparency = 0
			end)
			card.MouseLeave:Connect(function()
				card.BackgroundColor3 = Design.color("card")
				card.BackgroundTransparency = 0.15
			end)
			card.Activated:Connect(function()
				set(not value)
			end)

			local self = handle(card, set, function()
				return value
			end)
			-- Colon-called (`handle:OnChange(fn)`), so the first parameter is `self`.
			self.OnChange = function(this, handler)
				table.insert(handlers, handler)
				return this
			end
			self:OnChange(options.OnChange)
			if parent.Register then
				parent.Register(parent, options.Flag, function(nextValue)
					set(nextValue and nextValue ~= false)
				end, function()
					return value
				end)
			end
			if value then
				set(true, true)
			end
			return self
		end

		-- ==========================================================================
		-- Slider
		-- ==========================================================================
		-- options: Text, Min, Max, Default, Suffix, Step, Flag, OnChange

		function Materials.Slider(parent, options)
			options = options or {}
			local min = tonumber(options.Min) or 0
			local max = tonumber(options.Max) or 100
			if max <= min then
				max = min + 1
			end
			local step = tonumber(options.Step) or 1
			local suffix = options.Suffix or ""

			local holder = create("Frame", {
				Name = tostring(options.Text or "Slider"),
				Size = UDim2.new(1, 0, 0, 44),
				BackgroundColor3 = Design.color("card"),
				BackgroundTransparency = 0.15,
				BorderSizePixel = 0,
				LayoutOrder = #parent:GetChildren() + 1,
			}, parent)
			corner(holder, Design.radius.field)
			stroke(holder)

			label(holder, options.Text or "Slider", Design.text.label, Design.color("text"),
				UDim2.fromOffset(10, 5), UDim2.new(1, -60, 0, 16))

			local readout = label(holder, "", Design.text.value, Design.color("accent"),
				UDim2.new(1, -56, 0, 5), UDim2.fromOffset(46, 16))
			readout.TextXAlignment = Enum.TextXAlignment.Right

			-- 6 px hit area: a 4 px track is impossible to grab on a phone.
			local track = create("Frame", {
				Size = UDim2.new(1, -20, 0, 6),
				Position = UDim2.new(0, 10, 1, -16),
				BackgroundColor3 = Design.color("element"),
				BorderSizePixel = 0,
			}, holder)
			corner(track, 3)

			local fill = create("Frame", {
				Size = UDim2.new(0, 0, 1, 0),
				BackgroundColor3 = Design.color("accent"),
				BorderSizePixel = 0,
			}, track)
			corner(fill, 3)

			local knob = create("Frame", {
				Size = UDim2.fromOffset(12, 12),
				AnchorPoint = Vector2.new(0.5, 0.5),
				Position = UDim2.new(0, 0, 0.5, 0),
				BackgroundColor3 = Design.color("text"),
				BorderSizePixel = 0,
			}, track)
			corner(knob, Design.radius.pill)

			local value = math.clamp(tonumber(options.Default) or min, min, max)
			local handlers = {}
			local dragging = false

			local function format(number)
				if step < 1 then
					return ("%.2f%s"):format(number, suffix)
				end
				return ("%d%s"):format(math.floor(number + 0.5), suffix)
			end

			local function paint()
				local alpha = (value - min) / (max - min)
				fill.Size = UDim2.new(alpha, 0, 1, 0)
				knob.Position = UDim2.new(alpha, 0, 0.5, 0)
				readout.Text = format(value)
			end

			local function commit(nextValue, silent)
				local snapped = math.round((nextValue - min) / step) * step + min
				value = math.clamp(snapped, min, max)
				paint()
				if silent then
					return
				end
				for _, handler in handlers do
					pcall(handler, value)
				end
			end

			paint()

			local function valueAtX(x)
				local relative = math.clamp((x - track.AbsolutePosition.X) / math.max(track.AbsoluteSize.X, 1), 0, 1)
				return min + relative * (max - min)
			end

			local stepLink = Core:GetService("renderConnection") -- shared heartbeat
			track.InputBegan:Connect(function(input)
				if input.UserInputType == Enum.UserInputType.MouseButton1
					or input.UserInputType == Enum.UserInputType.Touch then
					dragging = true
					commit(valueAtX(input.Position.X))
				end
			end)
			track.InputEnded:Connect(function(input)
				if input.UserInputType == Enum.UserInputType.MouseButton1
					or input.UserInputType == Enum.UserInputType.Touch then
					dragging = false
				end
			end)
			if stepLink then
				-- One shared RenderStepped for every slider, owned by FatCatCore, so
				-- dragging five sliders does not create five global loops.
				stepLink(function()
					if not dragging then
						return
					end
					local mouse = Core:GetService("mouse")
					if not mouse then
						return
					end
					commit(valueAtX(mouse.X))
				end)
			end

			local self = handle(holder, nil, function()
				return value
			end)
			---Set the slider. Coerced here, not in `commit`, because a preset can
			---carry a string ("70") after a round trip through JSON and arithmetic on
			---it would throw inside the button callback with no link back to here.
			-- `self.Set = function(nextValue)` and NOT `function self.Set(nextValue)`:
			-- the colon-free method syntax still passes `self` as the first argument
			-- when the field is called as `handle:Set(57)`, so the number would arrive
			-- in `self` and the real value would be nil.
			self.Set = function(_, nextValue)
				local number = tonumber(nextValue)
				if number == nil then
					Core:Log("warn", ("slider '%s' ignored a non-number value (%s)"):format(
						tostring(options.Text), typeof(nextValue)))
					return
				end
				commit(number)
			end
			-- Colon-called (`handle:OnChange(fn)`), so the first parameter is `self`.
			self.OnChange = function(this, handler)
				table.insert(handlers, handler)
				return this
			end
			self:OnChange(options.OnChange)
			if parent.Register then
				parent.Register(parent, options.Flag, function(nextValue)
					commit(tonumber(nextValue) or min)
				end, function()
					return value
				end)
			end
			return self
		end

		-- ==========================================================================
		-- Dropdown
		-- ==========================================================================
		-- options: Text, Options, Default, Flag, OnChange

		function Materials.Dropdown(parent, options)
			options = options or {}
			local choices = options.Options or {}
			local current = options.Default or choices[1]

			local holder = create("TextButton", {
				Text = "",
				AutoButtonColor = false,
				BackgroundColor3 = Design.color("card"),
				BackgroundTransparency = 0.15,
				BorderSizePixel = 0,
				Size = UDim2.new(1, 0, 0, 32),
				LayoutOrder = #parent:GetChildren() + 1,
			}, parent)
			corner(holder, Design.radius.field)
			stroke(holder)

			label(holder, options.Text or "Select", Design.text.label, Design.color("textOff"),
				UDim2.fromOffset(10, 0), UDim2.new(0.45, -10, 1, 0))
			local shown = label(holder, tostring(current), Design.text.value, Design.color("text"),
				UDim2.new(0.45, 0, 0, 0), UDim2.new(0.55, -26, 1, 0))
			shown.TextXAlignment = Enum.TextXAlignment.Right
			label(holder, "▾", Design.text.hint, Design.color("textDim"),
				UDim2.new(1, -18, 0, 0), UDim2.fromOffset(12, 32))

			local handlers = {}
			local popup = nil

			local function close()
				if popup then
					popup:Destroy()
					popup = nil
				end
			end

			local function choose(choice, silent)
				current = choice
				shown.Text = tostring(choice)
				close()
				if silent then
					return
				end
				for _, handler in handlers do
					pcall(handler, choice)
				end
			end

			holder.Activated:Connect(function()
				if popup then
					close()
					return
				end
				-- Parented to the screen, positioned under this row: a list inside a
				-- scrolling column would be clipped by the column's canvas.
				local layer = options.Layer or Design.canvas or holder.Parent
				popup = create("Frame", {
					BackgroundColor3 = Design.color("element"),
					BorderSizePixel = 0,
					Size = UDim2.fromOffset(holder.AbsoluteSize.X, math.min(#choices, 6) * 24 + 8),
					Position = UDim2.fromOffset(holder.AbsolutePosition.X, holder.AbsolutePosition.Y + holder.AbsoluteSize.Y + 4),
					ZIndex = 40,
				}, layer)
				corner(popup, Design.radius.field)
				stroke(popup, Design.color("outline"), 0.25)
				create("UIPadding", { PaddingTop = UDim.new(0, 4), PaddingBottom = UDim.new(0, 4) }, popup)
				for index, choice in choices do
					local item = create("TextButton", {
						Text = tostring(choice),
						TextSize = Design.text.body,
						Font = Design.fonts.regular,
						TextColor3 = choice == current and Design.color("accent") or Design.color("text"),
						TextXAlignment = Enum.TextXAlignment.Left,
						TextTruncate = Enum.TextTruncate.AtEnd,
						AutoButtonColor = false,
						BackgroundTransparency = 1,
						Size = UDim2.new(1, -8, 0, 24),
						Position = UDim2.fromOffset(4, 4 + (index - 1) * 24),
						ZIndex = 41,
					}, popup)
					item.Activated:Connect(function()
						choose(choice)
					end)
				end
			end)

			local self = handle(holder, function(nextValue)
				choose(nextValue)
			end, function()
				return current
			end)
			-- Colon-called (`handle:OnChange(fn)`), so the first parameter is `self`.
			self.OnChange = function(this, handler)
				table.insert(handlers, handler)
				return this
			end
			self:OnChange(options.OnChange)
			self.Destroy = function(_)
				close()
				holder:Destroy()
			end
			if parent.Register then
				parent.Register(parent, options.Flag, function(nextValue)
					choose(nextValue)
				end, function()
					return current
				end)
			end
			return self
		end

		-- ==========================================================================
		-- Input
		-- ==========================================================================
		-- options: Text, Placeholder, Default, Flag, OnSubmit

		function Materials.Input(parent, options)
			options = options or {}
			local card = create("Frame", {
				BackgroundColor3 = Design.color("card"),
				BackgroundTransparency = 0.15,
				BorderSizePixel = 0,
				Size = UDim2.new(1, 0, 0, 50),
				LayoutOrder = #parent:GetChildren() + 1,
			}, parent)
			corner(card, Design.radius.field)
			stroke(card)

			label(card, options.Text or "Input", Design.text.label, Design.color("text"),
				UDim2.fromOffset(10, 4), UDim2.new(1, -20, 0, 16))

			local field = create("TextBox", {
				Size = UDim2.new(1, -20, 0, 22),
				Position = UDim2.fromOffset(10, 22),
				BackgroundColor3 = Design.color("element"),
				BorderSizePixel = 0,
				PlaceholderText = options.Placeholder or "Type here",
				PlaceholderColor3 = Design.color("textDim"),
				Text = tostring(options.Default or ""),
				TextColor3 = Design.color("text"),
				TextSize = Design.text.body,
				Font = Design.fonts.regular,
				TextXAlignment = Enum.TextXAlignment.Left,
				TextTruncate = Enum.TextTruncate.AtEnd,
				ClearTextOnFocus = false,
			}, card)
			corner(field, Design.radius.field)
			create("UIPadding", { PaddingLeft = UDim.new(0, 8), PaddingRight = UDim.new(0, 8) }, field)
			stroke(field, Design.color("outline"), 0.55)

			field.Focused:Connect(function()
				field.Size = UDim2.new(1, -20, 0, 22)
			end)
			field.FocusLost:Connect(function()
				if type(options.OnSubmit) == "function" then
					pcall(options.OnSubmit, field.Text)
				end
			end)

			local self = handle(card, function(nextValue)
				field.Text = tostring(nextValue)
			end, function()
				return field.Text
			end)
			if parent.Register then
				parent.Register(parent, options.Flag, function(nextValue)
					field.Text = tostring(nextValue)
				end, function()
					return field.Text
				end)
			end
			return self
		end

		-- ==========================================================================
		-- Status / label / divider
		-- ==========================================================================

		---Dot + text, no card. For readouts that must not look clickable.
		function Materials.Status(parent, text, state)
			local row = create("Frame", {
				Size = UDim2.new(1, 0, 0, 20),
				BackgroundTransparency = 1,
				LayoutOrder = #parent:GetChildren() + 1,
			}, parent)
			local colors = {
				on = Design.color("positive"),
				off = Design.color("negative"),
				warn = Design.color("accentAlt"),
				info = Design.color("accent"),
			}
			local dot = create("Frame", {
				Size = UDim2.fromOffset(6, 6),
				Position = UDim2.fromOffset(2, 7),
				BackgroundColor3 = colors[state or "info"] or Design.color("accent"),
				BorderSizePixel = 0,
			}, row)
			corner(dot, Design.radius.pill)
			local cap = label(row, text, Design.text.body, Design.color("textOff"),
				UDim2.fromOffset(14, 0), UDim2.new(1, -16, 1, 0))

			local self = handle(row, function(nextText, nextState)
				cap.Text = tostring(nextText)
				dot.BackgroundColor3 = colors[nextState or "info"] or Design.color("accent")
			end, function()
				return cap.Text
			end)
			return self
		end

		function Materials.Label(parent, text)
			local card = create("Frame", {
				Size = UDim2.new(1, 0, 0, 0),
				AutomaticSize = Enum.AutomaticSize.Y,
				BackgroundTransparency = 1,
				LayoutOrder = #parent:GetChildren() + 1,
			}, parent)
			local cap = create("TextLabel", {
				Text = tostring(text),
				TextSize = Design.text.body,
				Font = Design.fonts.regular,
				TextColor3 = Design.color("textDim"),
				TextWrapped = true,
				TextXAlignment = Enum.TextXAlignment.Left,
				TextYAlignment = Enum.TextYAlignment.Top,
				BackgroundTransparency = 1,
				Size = UDim2.new(1, 0, 0, 0),
				AutomaticSize = Enum.AutomaticSize.Y,
			}, card)
			local self = handle(card, function(nextText)
				cap.Text = tostring(nextText)
			end, function()
				return cap.Text
			end)
			return self
		end

		function Materials.Divider(parent)
			local holder = create("Frame", {
				Size = UDim2.new(1, 0, 0, 9),
				BackgroundTransparency = 1,
				LayoutOrder = #parent:GetChildren() + 1,
			}, parent)
			local line = create("Frame", {
				Size = UDim2.new(1, -12, 0, 1),
				Position = UDim2.fromOffset(6, 4),
				BackgroundColor3 = Design.color("outline"),
				BackgroundTransparency = 0.6,
				BorderSizePixel = 0,
			}, holder)
			Design.fade(1, line)
			return handle(holder, nil, nil)
		end

		---Code viewer: monospaced, scrolls both ways, capped line count.
		function Materials.Code(parent, options)
			options = options or {}
			local card = create("Frame", {
				BackgroundColor3 = Design.color("element"),
				BackgroundTransparency = 0.1,
				BorderSizePixel = 0,
				Size = UDim2.new(1, 0, 0, options.Height or 140),
				LayoutOrder = #parent:GetChildren() + 1,
			}, parent)
			corner(card, Design.radius.field)
			stroke(card, Design.color("outline"), 0.6)

			local scroll = create("ScrollingFrame", {
				Size = UDim2.new(1, -8, 1, -8),
				Position = UDim2.fromOffset(4, 4),
				BackgroundTransparency = 1,
				BorderSizePixel = 0,
				ScrollBarThickness = 2,
				ScrollBarImageColor3 = Design.color("outline"),
				ScrollBarImageTransparency = 0.4,
				CanvasSize = UDim2.new(),
				ScrollingDirection = Enum.ScrollingDirection.XY,
			}, card)
			local text = create("TextLabel", {
				Text = "",
				TextSize = Design.text.code,
				Font = Design.fonts.mono,
				TextColor3 = Design.color("textOff"),
				TextXAlignment = Enum.TextXAlignment.Left,
				TextYAlignment = Enum.TextYAlignment.Top,
				BackgroundTransparency = 1,
				Size = UDim2.new(1, 0, 0, 0),
				AutomaticSize = Enum.AutomaticSize.XY,
			}, scroll)
			scroll.AutomaticCanvasSize = Enum.AutomaticSize.XY

			local lines = {}
			local self = handle(card, nil, nil)
			---Replace the buffer and keep only the newest `limit` lines.
			---Accepts a table of lines or one multi-line string.
			self.SetLines = function(_, newLines, limit)
				table.clear(lines)
				if type(newLines) == "string" then
					for line in (newLines .. "\n"):gmatch("([^\n]*)\n") do
						table.insert(lines, line)
					end
				else
					for _, line in newLines or {} do
						table.insert(lines, line)
					end
				end
				local cap = limit or 300
				while #lines > cap do
					table.remove(lines, 1)
				end
				text.Text = table.concat(lines, "\n")
			end
			self.Push = function(_, line)
				table.insert(lines, tostring(line))
				while #lines > 300 do
					table.remove(lines, 1)
				end
				text.Text = table.concat(lines, "\n")
			end
			self.ScrollToBottom = function(_)
				scroll.CanvasPosition = Vector2.new(0, math.max(text.AbsoluteSize.Y - scroll.AbsoluteSize.Y, 0))
			end
			self.SetLines(options.Lines or options.Text or "")
			return self
		end

		return function(core, design, _signal)
			Core = core
			Design = design
			return Materials
		end
	end)()
	Modules['FatCatMaterials'] = module
end
-- ---------------------------------------------------------------------
-- FatCatMath.lua
-- ---------------------------------------------------------------------
do
	local module = (function()
		-- Fat Cat Project | Utilities, Console & Math/FatCatMath.lua
		--
		-- Vectors, world-to-screen, prediction and trajectories. No state, no
		-- instances, no globals: every function takes its inputs and returns a value,
		-- which is why this is the one module the tests can hammer without a mock.
		--
		--   local Math = FatCat.require("FatCatMath")
		--   local point, onScreen = Math.worldToScreen(camera, position)
		--   local lead = Math.predict(targetPosition, targetVelocity, projectileSpeed)
		--
		-- Coordinate conventions used everywhere below:
		--   * positions are Vector3 in world space, studs;
		--   * the camera looks down -Z in its own space (Roblox convention);
		--   * a point behind the camera is never projected: the divide by Z would
		--     flip it to the wrong side of the screen. `onScreen` is false instead.

		local Math2
		Math2 = {}

		-- ==========================================================================
		-- Scalars and vectors
		-- ==========================================================================

		function Math2.clamp(value, low, high)
			return math.clamp(value, low, high)
		end

		---Linear interpolation, unclamped t (extrapolation is legal).
		function Math2.lerp(from, to, t)
			return from + (to - from) * t
		end

		---Map `value` from one range to another, clamped to the output range.
		function Math2.remap(value, inMin, inMax, outMin, outMax)
			if inMax == inMin then
				return outMin
			end
			local t = math.clamp((value - inMin) / (inMax - inMin), 0, 1)
			return outMin + (outMax - outMin) * t
		end

		---Length of a Vector3, tolerant of a nil input (0).
		function Math2.length(vector)
			if not vector then
				return 0
			end
			return vector.Magnitude
		end

		---Unit vector, or a zero vector when the input has no length.
		function Math2.normalize(vector)
			if not vector then
				return Vector3.zero
			end
			local magnitude = vector.Magnitude
			if magnitude < 1e-6 then
				return Vector3.zero
			end
			return vector / magnitude
		end

		---Horizontal (XZ) distance. Height differences should not make a ground
		---check read as "far away".
		function Math2.flatDistance(a, b)
			if not (a and b) then
				return math.huge
			end
			local dx, dz = a.X - b.X, a.Z - b.Z
			return math.sqrt(dx * dx + dz * dz)
		end

		function Math2.distance(a, b)
			if not (a and b) then
				return math.huge
			end
			return (a - b).Magnitude
		end

		---Dot product of two Vector3, 0 when either is missing.
		function Math2.dot(a, b)
			if not (a and b) then
				return 0
			end
			return a:Dot(b)
		end

		---Angle between two vectors in degrees, 0 when either is degenerate.
		function Math2.angleBetween(a, b)
			local ua, ub = Math2.normalize(a), Math2.normalize(b)
			if ua == Vector3.zero or ub == Vector3.zero then
				return 0
			end
			return math.deg(math.acos(math.clamp(ua:Dot(ub), -1, 1)))
		end

		-- ==========================================================================
		-- World to screen
		-- ==========================================================================
		-- Returns screenX, screenY, onScreen, depth. Screen coordinates are pixels in
		-- the camera's viewport; a caller drawing a 2D overlay can use them directly.

		---Project a world position through `camera`.
		function Math2.worldToScreen(camera, position)
			if not camera or not position then
				return 0, 0, false, 0
			end

			local viewport = camera.ViewportSize
			if not viewport or viewport.X <= 0 or viewport.Y <= 0 then
				return 0, 0, false, 0
			end

			local relative = camera.CFrame:PointToObjectSpace(position)
			-- Behind (or exactly on) the near plane: no valid projection exists.
			if relative.Z > -0.01 then
				return 0, 0, false, relative.Z
			end

			local focal = viewport.Y / 2
			local tanHalf = math.tan(math.rad(camera.FieldOfView) / 2)
			if tanHalf <= 0 then
				return 0, 0, false, relative.Z
			end
			focal = focal / tanHalf

			local x = viewport.X / 2 + (relative.X / -relative.Z) * focal
			local y = viewport.Y / 2 + (-relative.Y / -relative.Z) * focal

			local onScreen = x >= 0 and y >= 0 and x <= viewport.X and y <= viewport.Y
			return x, y, onScreen, -relative.Z
		end

		---Screen-space size of a world-space sphere, in pixels. Used by the ESP to
		---keep boxes proportional at range instead of drawing a fixed rectangle.
		function Math2.worldToScreenSize(camera, position, worldRadius)
			local _, _, _, depth = Math2.worldToScreen(camera, position)
			if depth <= 0 then
				return 0
			end
			local viewport = camera.ViewportSize
			local tanHalf = math.tan(math.rad(camera.FieldOfView) / 2)
			if tanHalf <= 0 then
				return 0
			end
			return (worldRadius * 2 * (viewport.Y / 2)) / (depth * tanHalf)
		end

		---True when `point` is inside the camera frustum, with a margin in pixels.
		function Math2.inView(camera, point, margin)
			if not (camera and point) then
				return false
			end
			local x, y, _, depth = Math2.worldToScreen(camera, point)
			if depth <= 0 then
				return false
			end
			local viewport = camera.ViewportSize
			local pad = margin or 0
			return x >= -pad and y >= -pad and x <= viewport.X + pad and y <= viewport.Y + pad
		end

		-- ==========================================================================
		-- Prediction
		-- ==========================================================================
		-- The projectile problem: by the time a bullet reaches the target, the target
		-- has moved. Given a muzzle position, a target position and velocity, and a
		-- projectile speed, solve for the lead point.
		--
		-- This is the closed-form solution for constant target velocity and constant
		-- projectile speed (a quadratic in time). It is correct for the common case
		-- (a game with gravity-less or fast projectiles) and it degrades sanely when
		-- there is no solution: a target that outruns the projectile returns nil,
		-- which the caller must handle rather than silently aiming behind.

		---Lead point, or nil when the projectile can never catch the target.
		---@param muzzle Vector3
		---@param target Vector3
		---@param velocity Vector3
		---@param speed number        studs per second
		function Math2.predict(muzzle, target, velocity, speed)
			if not (muzzle and target and velocity) then
				return nil
			end
			speed = tonumber(speed) or 0
			if speed <= 0 then
				return nil
			end

			local offset = target - muzzle
			local a = velocity:Dot(velocity) - speed * speed
			local b = 2 * offset:Dot(velocity)
			local c = offset:Dot(offset)

			local function leadAt(t)
				return target + velocity * t
			end

			-- a ~ 0: the target moves at exactly projectile speed, linear equation.
			if math.abs(a) < 1e-6 then
				if math.abs(b) < 1e-6 then
					return nil
				end
				local t = -c / b
				if t < 0 then
					return nil
				end
				return leadAt(t)
			end

			local discriminant = b * b - 4 * a * c
			if discriminant < 0 then
				return nil
			end
			local root = math.sqrt(discriminant)
			local t1 = (-b + root) / (2 * a)
			local t2 = (-b - root) / (2 * a)

			-- Two roots: the earlier positive one is the first intercept.
			local t = nil
			if t1 > 0 and t2 > 0 then
				t = math.min(t1, t2)
			elseif t1 > 0 then
				t = t1
			elseif t2 > 0 then
				t = t2
			end
			if not t then
				return nil
			end
			return leadAt(t)
		end

		---Same as predict, but returns the flight time too.
		function Math2.timeToImpact(muzzle, target, speed)
			if not (muzzle and target) then
				return nil
			end
			speed = tonumber(speed) or 0
			if speed <= 0 then
				return nil
			end
			return (target - muzzle).Magnitude / speed
		end

		-- ==========================================================================
		-- Trajectories
		-- ==========================================================================
		-- Points along an arc, for drawing a grenade path or a prediction rail. The
		-- arc is a parabola in world space with an explicit gravity constant, so a
		-- game that uses different gravity can pass its own.

		function Math2.arc(origin, velocity, gravity, duration, steps)
			gravity = gravity or Vector3.new(0, -workspace.Gravity, 0)
			duration = duration or 1
			steps = math.max(steps or 16, 2)
			local points = {}
			for index = 0, steps do
				local t = duration * (index / steps)
				points[index + 1] = origin + velocity * t + gravity * (0.5 * t * t)
			end
			return points
		end

		---Where the arc lands on a plane at `height`.
		function Math2.arcLanding(origin, velocity, gravity, height)
			gravity = gravity or Vector3.new(0, -workspace.Gravity, 0)
			height = height or 0
			local rise = origin.Y - height
			-- rise + vy*t + 0.5*gy*t^2 = 0, solve for the positive root.
			local a = 0.5 * gravity.Y
			local b = velocity.Y
			local c = rise
			if math.abs(a) < 1e-6 then
				if math.abs(b) < 1e-6 then
					return nil
				end
				local t = -c / b
				if t < 0 then
					return nil
				end
				return origin + velocity * t + gravity * (0.5 * t * t), t
			end
			local discriminant = b * b - 4 * a * c
			if discriminant < 0 then
				return nil
			end
			local root = math.sqrt(discriminant)
			local t1 = (-b + root) / (2 * a)
			local t2 = (-b - root) / (2 * a)
			local t = (t1 > 0 and t2 > 0) and math.min(t1, t2) or math.max(t1, t2)
			if t < 0 then
				return nil
			end
			return origin + Vector3.new(velocity.X * t, velocity.Y * t + 0.5 * gravity.Y * t * t, velocity.Z * t), t
		end

		-- ==========================================================================
		-- Angles and directions
		-- ==========================================================================

		---Unit direction vector from Euler angles in degrees, Roblox look convention.
		function Math2.directionFromAngles(pitch, yaw)
			local p = math.rad(pitch or 0)
			local y = math.rad(yaw or 0)
			return Vector3.new(
				-math.sin(y) * math.cos(p),
				math.sin(p),
				-math.cos(y) * math.cos(p)
			)
		end

		---Aim at `target` from `origin`, as (pitch, yaw) in degrees.
		function Math2.anglesTo(origin, target)
			if not (origin and target) then
				return 0, 0
			end
			local delta = target - origin
			local yaw = math.deg(math.atan2(-delta.X, -delta.Z))
			local flat = math.sqrt(delta.X * delta.X + delta.Z * delta.Z)
			local pitch = math.deg(math.atan2(delta.Y, flat))
			return pitch, yaw
		end

		---Normalise an angle to (-180, 180].
		function Math2.wrapAngle(degrees)
			degrees = degrees % 360
			if degrees > 180 then
				degrees -= 360
			end
			return degrees
		end

		return function(_core)
			return Math2
		end
	end)()
	Modules['FatCatMath'] = module
end
-- ---------------------------------------------------------------------
-- FatCatInspect.lua
-- ---------------------------------------------------------------------
do
	local module = (function()
		-- Fat Cat Project | Creation & Inspection Tools/FatCatInspect.lua
		--
		-- Inspection without touching the game: hierarchies, property lists, and
		-- table printers, all read-only and all depth-limited.
		--
		--   local I = FatCat.require("FatCatInspect")
		--   I.describe(workspace.Baseplate)      -- one line
		--   I.tree(game.Players, 3)              -- nested table, depth 3
		--   I.properties(part, { "Size", "Color" })
		--   I.format(coreTemplate)               -- readable string, cycle-safe
		--
		-- Read-only is the design rule, not a limitation: everything the exploit tabs
		-- show is produced by these functions, and a printer that can mutate what it
		-- prints cannot be trusted to debug it.
		--
		-- Two hard problems this solves:
		--   * cycles: a table that contains itself must print as `{...}` instead of
		--     recursing until the stack dies;
		--   * hostile metatables: indexing a userdata can throw, so every read is
		--     wrapped and a thrown read prints as `<error>` instead of killing the
		--     whole dump.

		local Materials, Inspect
		Inspect = {}

		---Maximum nodes the tree walker will visit, so a 300 000 part workspace
		---cannot lock the menu while it prints.
		Inspect.MAX_NODES = 400

		-- ==========================================================================
		-- Values
		-- ==========================================================================

		local function safeIndex(target, key)
			local ok, value = pcall(function()
				return (target :: any)[key]
			end)
			if ok then
				return value
			end
			return nil, tostring(value)
		end

		---One-line description of any value.
		function Inspect.describe(value)
			local kind = typeof(value)
			if kind == "Instance" then
				return ("%s [%s]"):format(value.Name, value.ClassName)
			elseif kind == "string" then
				return ("%q"):format(value)
			elseif kind == "number" then
				if value ~= value then
					return "nan"
				end
				return tostring(value)
			elseif kind == "table" then
				local count = 0
				for _ in value do
					count += 1
				end
				return ("table (%d)"):format(count)
			elseif kind == "userdata" or kind == "Vector3" or kind == "CFrame"
				or kind == "Color3" or kind == "UDim2" or kind == "Vector2" then
				return tostring(value)
			end
			return ("%s %s"):format(kind, tostring(value))
		end

		---Recursive, cycle-safe, depth-limited formatting.
		function Inspect.format(value, options)
			options = options or {}
			local depthLimit = options.Depth or 3
			local seen = {}
			local lines = {}

			local function walk(item, depth, prefix)
				if depth > depthLimit then
					table.insert(lines, prefix .. "…")
					return
				end

				local kind = typeof(item)
				if kind ~= "table" then
					table.insert(lines, prefix .. Inspect.describe(item))
					return
				end
				if seen[item] then
					table.insert(lines, prefix .. "{cycle}")
					return
				end
				seen[item] = true

				local keys = {}
				for key in item do
					table.insert(keys, key)
				end
				-- Strings first, then numbers, then everything else: a template's
				-- named fields read better before its numeric array part.
				table.sort(keys, function(a, b)
					local ra, rb = type(a), type(b)
					if ra ~= rb then
						return ra < rb
					end
					if ra == "number" or ra == "string" then
						return a < b
					end
					return tostring(a) < tostring(b)
				end)

				for _, key in keys do
					local entry, errorText = safeIndex(item, key)
					local label = type(key) == "string" and key or ("[" .. tostring(key) .. "]")
					if errorText then
						table.insert(lines, ("%s%s = <error: %s>"):format(prefix, label, errorText))
					elseif typeof(entry) == "table" then
						table.insert(lines, ("%s%s ="):format(prefix, label))
						walk(entry, depth + 1, prefix .. "  ")
					else
						table.insert(lines, ("%s%s = %s"):format(prefix, label, Inspect.describe(entry)))
					end
				end
				seen[item] = nil
			end

			walk(value, 1, "")
			return table.concat(lines, "\n")
		end

		-- ==========================================================================
		-- Instances
		-- ==========================================================================

		---Nested { name, class, children } up to `depth`, capped at MAX_NODES.
		function Inspect.tree(root, depth)
			local visited = 0
			local function walk(instance, level)
				visited += 1
				local node = {
					name = instance.Name,
					class = instance.ClassName,
					children = {},
				}
				if level >= depth or visited >= Inspect.MAX_NODES then
					local count = #instance:GetChildren()
					if count > 0 then
						node.omitted = count
					end
					return node
				end
				for _, child in instance:GetChildren() do
					if visited >= Inspect.MAX_NODES then
						node.truncated = true
						break
					end
					table.insert(node.children, walk(child, level + 1))
				end
				return node
			end
			return walk(root, 1)
		end

		---Indented text for the tree above, one line per node.
		function Inspect.treeText(root, depth)
			local rootNode = Inspect.tree(root, depth)
			local lines = {}
			local function walk(node, level)
				local suffix = ""
				if node.omitted then
					suffix = ("  (+%d)"):format(node.omitted)
				elseif node.truncated then
					suffix = "  (truncated)"
				end
				table.insert(lines, ("%s%s [%s]%s"):format(
					string.rep("  ", level - 1), node.name, node.class, suffix))
				for _, child in node.children do
					walk(child, level + 1)
				end
			end
			walk(rootNode, 1)
			return table.concat(lines, "\n")
		end

		---Read a property, or nil plus the error string.
		function Inspect.property(instance, name)
			if not instance then
				return nil, "no instance"
			end
			return safeIndex(instance, name)
		end

		---Every property name a class exposes, via pcall'd GetProperties? Not
		---available on every executor: fall back to indexing a probe instance.
		function Inspect.propertyNames(className)
			local names = {}
			local ok, probe = pcall(Instance.new, className)
			if not ok then
				return names
			end
			-- There is no portable property enumeration in vanilla Luau; the common
			-- executor surface exposes it through getproperties on some builds, and
			-- through the API dump on others. Return the probe so the caller can list
			-- what it actually needs instead of inventing a list.
			probe:Destroy()
			return names
		end

		-- ==========================================================================
		-- Tab
		-- ==========================================================================

		local function mount(page)
			local section = page:Section("Hierarchy", 1)
			local target = Materials.Input(section.frame, {
				Text = "Instance path",
				Default = "game.Workspace",
				Placeholder = "game.Workspace",
			})
			local output = Materials.Code(section.frame, { Height = 260 })

			local function resolve(path)
				local chunks = {}
				for piece in tostring(path):gmatch("[^%.]+") do
					table.insert(chunks, piece)
				end
				local current = game
				for _, piece in chunks do
					if current == game and game:GetService(piece) then
						current = game:GetService(piece)
					else
						local ok, child = pcall(function()
							return current:FindFirstChild(piece)
						end)
						if not ok or not child then
							return nil, piece
						end
						current = child
					end
				end
				return current
			end

			Materials.Button(section.frame, {
				Text = "Print hierarchy",
				OnClick = function()
					local instance, missing = resolve(target:Get())
					if not instance then
						output:SetLines("Could not resolve '" .. tostring(missing) .. "'")
						return
					end
					output:SetLines(Inspect.treeText(instance, 3), 300)
				end,
			})

			local props = page:Section("Properties", 2)
			local propTarget = Materials.Input(props.frame, { Text = "Instance name", Default = "Workspace" })
			local propOutput = Materials.Code(props.frame, { Height = 260 })
			Materials.Button(props.frame, {
				Text = "Show table",
				OnClick = function()
					local instance, missing = resolve("game." .. propTarget:Get())
					if not instance then
						propOutput:SetLines("No instance named '" .. tostring(missing) .. "'")
						return
					end
					propOutput:SetLines(Inspect.format({
						Name = instance.Name,
						ClassName = instance.ClassName,
						Parent = instance.Parent and instance.Parent.Name or nil,
						Children = #instance:GetChildren(),
						Archivable = instance.Archivable,
					}), 120)
				end,
			})

			return { mount = true }
		end

		Inspect.mount = mount

		return function(_core, materials)
			Materials = materials
			return Inspect
		end
	end)()
	Modules['FatCatInspect'] = module
end
-- ---------------------------------------------------------------------
-- FatCatCreate.lua
-- ---------------------------------------------------------------------
do
	local module = (function()
		-- Fat Cat Project | Creation & Inspection Tools/FatCatCreate.lua
		--
		-- A visual GUI builder: a design surface, a property list, and a tree, all
		-- editing one plain data table. The data table is the thing that matters —
		-- it serialises to a preset, round-trips through FatCatConfig, and can be
		-- turned into live instances at any point.
		--
		--   local Create = FatCat.require("FatCatCreate")
		--   Create.mount(page)                    -- the editor tab
		--   local doc = Create.new("My Panel")    -- programmatic document
		--   Create.add(doc, "TextButton", { ... })
		--   Create.build(doc, parentGui)          -- instantiate for real
		--   Create.serialize(doc)                  -- JSON-safe table
		--
		-- The document shape:
		--
		--   {
		--     name = "My Panel",
		--     tree = {                        -- every node is a child by `parent`
		--       { id = 1, class = "ScreenGui", props = {...}, parent = nil },
		--       { id = 2, class = "Frame", props = {...}, parent = 1 },
		--     },
		--     nextId = 3,
		--     selection = 2,
		--   }
		--
		-- A tree in an array (ids, not nested tables) makes reordering, deletion and
		-- JSON round-trips trivial; nesting re-introduces the deep-copy problems the
		-- document exists to avoid.

		local Core, Design, Materials, Create
		Create = {}

		-- Classes the editor offers. Deliberately short: these are the ones with a
		-- stable property set, and every entry has defaults so a new node is valid.
		Create.CLASSES = {
			{ class = "ScreenGui", label = "Screen", defaults = { ResetOnSpawn = false } },
			{ class = "Frame", label = "Frame", defaults = { Size = { 0.4, 0, 0.3, 0 }, BackgroundColor3 = "card" } },
			{ class = "TextLabel", label = "Label", defaults = { Text = "Label", TextSize = 13, Size = { 0.4, 0, 0, 20 } } },
			{ class = "TextButton", label = "Button", defaults = { Text = "Button", TextSize = 13, Size = { 0.4, 0, 0, 28 } } },
			{ class = "TextBox", label = "Input", defaults = { Text = "", PlaceholderText = "Type...", Size = { 0.4, 0, 0, 24 } } },
			{ class = "ScrollingFrame", label = "Scroll", defaults = { ScrollBarThickness = 2, Size = { 0.4, 0, 0.3, 0 } } },
			{ class = "ImageLabel", label = "Image", defaults = { Size = { 0.1, 0, 0.1, 0 } } },
		}

		local defaultsById = {}
		for _, entry in Create.CLASSES do
			defaultsById[entry.class] = entry
		end

		-- ==========================================================================
		-- Document
		-- ==========================================================================

		---A new document with a single ScreenGui root.
		function Create.new(name)
			local document = {
				name = name or "Untitled",
				tree = {},
				nextId = 1,
				selection = nil,
			}
			local root = Create.add(document, "ScreenGui", { Name = name or "ScreenGui" })
			document.selection = root.id
			return document
		end

		---Add a node. Returns the node, or nil plus a reason for an unknown class.
		function Create.add(document, class, props)
			local entry = defaultsById[class]
			if not entry then
				return nil, ("unknown class '%s'"):format(tostring(class))
			end

			local merged = {}
			for key, value in entry.defaults do
				merged[key] = value
			end
			for key, value in props or {} do
				merged[key] = value
			end

			local node = {
				id = document.nextId,
				class = class,
				props = merged,
				parent = document.selection,
			}
			document.nextId += 1
			table.insert(document.tree, node)
			return node
		end

		---Find a node by id.
		function Create.get(document, id)
			for _, node in document.tree do
				if node.id == id then
					return node
				end
			end
			return nil
		end

		---Children of `id` (nil = roots).
		function Create.children(document, id)
			local list = {}
			for _, node in document.tree do
				if node.parent == id then
					table.insert(list, node)
				end
			end
			return list
		end

		---Remove a node and everything under it. Returns the removed nodes.
		function Create.remove(document, id)
			local doomed, stack = {}, { id }
			while #stack > 0 do
				local current = table.remove(stack)
				doomed[current] = true
				for _, child in Create.children(document, current) do
					table.insert(stack, child.id)
				end
			end

			local kept = {}
			for _, node in document.tree do
				if not doomed[node.id] then
					table.insert(kept, node)
				end
			end
			document.tree = kept
			if doomed[document.selection] then
				document.selection = nil
			end
			return doomed
		end

		---Reparent. Refuses a cycle (dropping a node into its own descendant).
		function Create.reparent(document, id, newParent)
			if id == newParent then
				return false, "a node cannot be its own parent"
			end
			local node = Create.get(document, id)
			if not node then
				return false, "no such node"
			end
			-- Walk up from the target: if we meet `id`, this would make a loop.
			local cursor = newParent
			while cursor do
				if cursor == id then
					return false, "that would put the node inside itself"
				end
				local parent = Create.get(document, cursor)
				cursor = parent and parent.parent or nil
			end
			node.parent = newParent
			return true
		end

		---Set one property, validating the two that cause the worst breakage.
		function Create.setProperty(document, id, key, value)
			local node = Create.get(document, id)
			if not node then
				return false, "no such node"
			end
			if key == "Name" and (type(value) ~= "string" or value == "") then
				return false, "a name cannot be empty"
			end
			if key == "class" then
				return false, "changing a class would drop its properties"
			end
			node.props[key] = value
			return true
		end

		---JSON-safe copy: colours become palette keys, UDim2 becomes 4 numbers, so a
		---preset written today still loads if a palette changes tomorrow.
		function Create.serialize(document)
			local tree = {}
			for _, node in document.tree do
				local props = {}
				for key, value in node.props do
					local kind = typeof(value)
					if kind == "Color3" then
						props[key] = { rgb = {
							math.round(value.R * 255),
							math.round(value.G * 255),
							math.round(value.B * 255),
						} }
					elseif kind == "UDim2" then
						props[key] = {
							xs = value.X.Scale, xo = value.X.Offset,
							ys = value.Y.Scale, yo = value.Y.Offset,
						}
					elseif kind == "string" or kind == "number" or kind == "boolean" then
						props[key] = value
					end
				end
				table.insert(tree, { id = node.id, class = node.class, props = props, parent = node.parent })
			end
			return { name = document.name, tree = tree, nextId = document.nextId }
		end

		---Rebuild a document from Create.serialize output.
		function Create.deserialize(payload)
			if type(payload) ~= "table" or type(payload.tree) ~= "table" then
				return nil, "not a document"
			end
			local document = {
				name = payload.name or "Untitled",
				tree = {},
				nextId = payload.nextId or 1,
				selection = nil,
			}
			for _, entry in payload.tree do
				table.insert(document.tree, {
					id = entry.id or document.nextId,
					class = entry.class,
					props = entry.props or {},
					parent = entry.parent,
				})
			end
			return document
		end

		-- ==========================================================================
		-- Instantiation
		-- ==========================================================================

		local function applyProps(instance, props)
			for key, value in props do
				if key == "Size" or key == "Position" then
					if type(value) == "table" then
						instance[key] = UDim2.new(value[1] or 0, value[2] or 0, value[3] or 0, value[4] or 0)
					end
				elseif key == "BackgroundColor3" and type(value) == "string" then
					-- A palette key, resolved at build time so a theme switch is one
					-- palette change, not a rebuild.
					instance.BackgroundColor3 = Design.color(value)
				else
					local ok = pcall(function()
						(instance :: any)[key] = value
					end)
					-- A property the class does not have is skipped, not fatal: a
					-- document written for a newer class must still load.
					if not ok then
						Core:Log("debug", ("%s has no property %s"):format(instance.ClassName, key))
					end
				end
			end
		end

		---Turn the document into real instances under `parent`.
		function Create.build(document, parent)
			local created = {}
			local function buildNode(node, target)
				local ok, instance = pcall(Instance.new, node.class)
				if not ok then
					Core:Log("error", ("cannot create %s: %s"):format(tostring(node.class), tostring(instance)))
					return
				end
				applyProps(instance :: Instance, node.props)
				instance.Parent = target
				created[node.id] = instance
				for _, child in Create.children(document, node.id) do
					buildNode(child, instance)
				end
			end

			for _, rootNode in Create.children(document, nil) do
				buildNode(rootNode, parent)
			end
			return created
		end

		---Destroy instances returned by build.
		function Create.clear(created)
			for _, instance in created or {} do
				pcall(function()
					instance:Destroy()
				end)
			end
		end

		-- ==========================================================================
		-- Editor tab
		-- ==========================================================================

		local function describe(node)
			local name = node.props.Name or node.class
			return ("%s (%s)"):format(tostring(name), node.class)
		end

		---Build the Create tab into a page.
		---@param page table  a Page from the shell (has :Section)
		function Create.mount(page)
			local section = page:Section("Builder", 1)
			Materials.Label(section.frame,
				"Pick a class, click Add, then edit its properties. Every change is written "
				.. "to the document immediately; Save writes it as a preset.")
			Materials.Divider(section.frame)

			local document = Create.new("Untitled")
			Core.state.createDocument = document

			local treeSection = page:Section("Tree", 2)
			local listHolder = treeSection.frame
			local selectedLabel = Materials.Status(listHolder, "nothing selected", "info")

			local properties = Materials.Section(listHolder, "Properties")
			local propertyRows = {}
			local refreshProperties -- defined below; the tree rows call it

			local function refreshTree()
				for _, handle in propertyRows do
					handle:Destroy()
				end
				table.clear(propertyRows)

				local nodes = Create.children(document, nil)
				local function walk(id, depth)
					for _, node in Create.children(document, id) do
						local prefix = string.rep("  ", depth)
						local row = Materials.Button(listHolder, {
							Text = prefix .. describe(node),
							Height = 26,
							OnClick = function()
								document.selection = node.id
								selectedLabel:Set(describe(node), "on")
								refreshProperties()
							end,
						})
						table.insert(propertyRows, row)
						walk(node.id, depth + 1)
					end
				end
				walk(nil, 0)
				if #nodes == 0 then
					table.insert(propertyRows, Materials.Label(listHolder, "The document is empty. Add a class above."))
				end
			end

			refreshProperties = function()
				local node = document.selection and Create.get(document, document.selection) or nil
				if not node then
					return
				end
				for _, key in { "Name", "Text", "TextSize" } do
					if node.props[key] ~= nil then
						local field = Materials.Input(properties.frame, {
							Text = key,
							Default = tostring(node.props[key]),
							OnSubmit = function(value)
								local converted = value
								if key == "TextSize" then
									converted = tonumber(value) or node.props.TextSize
								end
								Create.setProperty(document, node.id, key, converted)
								refreshTree()
							end,
						})
						table.insert(propertyRows, field)
					end
				end
			end

			local picker = Materials.Dropdown(section.frame, {
				Text = "Class",
				Options = (function()
					local names = {}
					for _, entry in Create.CLASSES do
						table.insert(names, entry.label)
					end
					return names
				end)(),
				Default = "Frame",
			})
			local classByLabel = {}
			for _, entry in Create.CLASSES do
				classByLabel[entry.label] = entry.class
			end

			Materials.Button(section.frame, {
				Text = "Add child",
				OnClick = function()
					local chosen = classByLabel[picker:Get()] or "Frame"
					local node = Create.add(document, chosen, {})
					if node then
						document.selection = node.id
						selectedLabel:Set(describe(node), "on")
						refreshTree()
						refreshProperties()
					end
				end,
			})
			Materials.Button(section.frame, {
				Text = "Delete selected",
				Danger = true,
				OnClick = function()
					if not document.selection then
						return
					end
					Create.remove(document, document.selection)
					selectedLabel:Set("nothing selected", "info")
					refreshTree()
				end,
			})
			Materials.Button(section.frame, {
				Text = "Preview on screen",
				OnClick = function()
					local previous = Core:GetService("createPreview")
					if previous then
						Create.clear(previous)
					end
					local layer = Design.canvas
					if not layer then
						return
					end
					local created = Create.build(document, layer)
					Core:SetService("createPreview", created, function()
						Create.clear(created)
					end)
				end,
			})

			refreshTree()
			return {
				document = document,
				refresh = refreshTree,
			}
		end

		return function(core, design, _signal, materials)
			Core = core
			Design = design
			Materials = materials
			return Create
		end
	end)()
	Modules['FatCatCreate'] = module
end
-- ---------------------------------------------------------------------
-- FatCatExtractor.lua
-- ---------------------------------------------------------------------
do
	local module = (function()
		-- Fat Cat Project | Advanced Analysis/FatCatExtractor.lua
		--
		-- Extract a script's source from the running client: bytecode if that is all
		-- the executor can give, decompiled text if a decompiler is available.
		--
		--   local X = FatCat.require("FatCatExtractor")
		--   local sources = X.sources()          -- every script it can reach, with flags
		--   local text, how = X.source(script)   -- "source" | "bytecode" | nil
		--   X.save("extracted/Remote.lua", text)
		--
		-- Two realities this module is built around:
		--
		--   * `script.Source` is empty on the client for every server script. A tool
		--     that reads Source and reports "empty script" is useless. Real
		--     extraction goes through getscriptbytecode / getscriptclosure, and the
		--     result is bytecode, not source.
		--   * decompilation is a separate, optional capability. When the executor
		--     ships a decompiler (decompile, or the requirement "decompiler") this
		--     module calls it; when it does not, it returns the bytecode and says so
		--     plainly instead of pretending the text is source.
		--
		-- This is read-only: it never writes back to a script, never replaces a
		-- closure, and never modifies the running game.

		local Core, Materials, Extractor
		Extractor = {}

		Extractor.OUTPUT = "FatCatProject/extracted"

		-- ==========================================================================
		-- Discovery
		-- ==========================================================================

		local function kindOf(instance)
			local ok, isLua = pcall(function()
				return instance:IsA("LuaSourceContainer")
			end)
			if ok and isLua then
				return "script"
			end
			return nil
		end

		---Every script instance reachable from a service, plus nil-parented ones.
		---Returns a list of { instance, name, class, parent, local }.
		function Extractor.sources(limit)
			limit = limit or 2000
			local found = {}
			local seen = {}

			local function visit(root)
				if not root then
					return
				end
				local ok, descendants = pcall(function()
					return root:GetDescendants()
				end)
				if not ok then
					return
				end
				for _, descendant in descendants do
					if #found >= limit then
						return
					end
					if not seen[descendant] and kindOf(descendant) then
						seen[descendant] = true
						local parent = descendant.Parent
						table.insert(found, {
							instance = descendant,
							name = descendant.Name,
							class = descendant.ClassName,
							parent = parent and parent.Name or "<nil>",
							localScript = descendant:IsA("LocalScript"),
						})
					end
				end
			end

			visit(game:GetService("ReplicatedStorage"))
			visit(game:GetService("ReplicatedFirst"))
			visit(game:GetService("StarterPlayer"))
			visit(game:GetService("StarterGui"))
			visit(game:GetService("Workspace"))
			visit(game:GetService("Players"))

			-- getnilinstances finds scripts whose parent is nil, which is where a lot
			-- of anti-cheat and loader scripts live.
			local nilInstances = Core.env.getnilinstances
			if type(nilInstances) == "function" then
				local ok, list = pcall(nilInstances)
				if ok then
					for _, instance in list do
						if #found >= limit then
							break
						end
						if not seen[instance] and kindOf(instance) then
							seen[instance] = true
							table.insert(found, {
								instance = instance,
								name = instance.Name,
								class = instance.ClassName,
								parent = "<nil>",
								localScript = instance:IsA("LocalScript"),
							})
						end
					end
				end
			end

			return found
		end

		-- ==========================================================================
		-- Bytecode and decompilation
		-- ==========================================================================

		local function bytesToString(bytecode)
			if type(bytecode) == "string" then
				return bytecode
			end
			if typeof(bytecode) == "buffer" then
				local asBuffer = bytecode :: buffer
				return buffer.tostring(asBuffer)
			end
			return nil
		end

		---The raw bytecode of a script, or nil plus a reason.
		function Extractor.bytecode(instance)
			local getBytecode = Core.env.getscriptbytecode
			if type(getBytecode) ~= "function" then
				return nil, "this executor has no getscriptbytecode()"
			end
			local ok, result = pcall(getBytecode, instance)
			if not ok then
				return nil, tostring(result)
			end
			local text = bytesToString(result)
			if not text or text == "" then
				return nil, "the executor returned no bytecode (the script may be C-protected)"
			end
			return text, "bytecode"
		end

		---A decompiler function, when the executor has one.
		local function decompiler()
			local candidates = { "decompile", "decompilefunction", "decompiler" }
			for _, name in candidates do
				local impl = Core.env[name]
				if type(impl) == "function" then
					return impl, name
				end
			end
			local ok, module = pcall(require, "decompiler")
			if ok and type(module) == "function" then
				return module, "require(decompiler)"
			end
			return nil
		end

		---True when source text can be produced (a decompiler exists).
		function Extractor.canDecompile()
			return decompiler() ~= nil
		end

		---Try source first, then decompile, then bytecode.
		---Returns text, how, where "how" is "source" | "decompiled" | "bytecode".
		function Extractor.source(instance)
			local ok, source = pcall(function()
				return instance.Source
			end)
			if ok and type(source) == "string" and source ~= "" then
				return source, "source"
			end

			local decompile = decompiler()
			if decompile then
				local closure = nil
				if type(Core.env.getscriptclosure) == "function" then
					local gotClosure, result = pcall(Core.env.getscriptclosure, instance)
					if gotClosure then
						closure = result
					end
				end
				if closure then
					local success, text = pcall(decompile, closure)
					if success and type(text) == "string" and text ~= "" then
						return text, "decompiled"
					end
				end
			end

			local raw, why = Extractor.bytecode(instance)
			if not raw then
				return nil, nil, why
			end
			raw = raw :: string
			-- Bytecode is bytes; store it escaped so the file survives a round trip.
			local hex = {}
			for index = 1, math.min(#raw, 200000) do
				hex[#hex + 1] = ("%02x"):format(string.byte(raw, index))
			end
			return table.concat(hex), "bytecode"
		end

		-- ==========================================================================
		-- Saving
		-- ==========================================================================

		---Write text to the project folder. Returns path, or nil plus a reason.
		function Extractor.save(relativePath, text)
			if type(text) ~= "string" then
				return nil, "nothing to save"
			end
			local write = Core.env.writefile
			if type(write) ~= "function" then
				return nil, "this executor has no writefile()"
			end
			if type(Core.env.makefolder) == "function" then
				pcall(Core.env.makefolder, "FatCatProject")
				pcall(Core.env.makefolder, Extractor.OUTPUT)
			end
			local path = Extractor.OUTPUT .. "/" .. relativePath
			local ok, err = pcall(write, path, text)
			if not ok then
				return nil, tostring(err)
			end
			return path
		end

		---Strip characters an executor filesystem may reject, then add the extension.
		function Extractor.fileName(entry, how)
			local base = entry.name:gsub("[^%w_%- ]", "_")
			if base == "" then
				base = "script"
			end
			local extension = ".lua"
			if how == "bytecode" then
				extension = ".luac.hex"
			end
			return ("%s_%s%s"):format(base, entry.class, extension)
		end

		---Extract everything reachable and save it. `onProgress(done, total, name)`.
		---Returns { saved = n, skipped = n, reasons = { ... } }.
		function Extractor.extractAll(options)
			options = options or {}
			local onProgress = options.onProgress
			local entries = Extractor.sources(options.limit)
			local report = { saved = 0, skipped = 0, reasons = {} }

			for index, entry in entries do
				if onProgress then
					onProgress(index, #entries, entry.name)
				end
				local text, how, why = Extractor.source(entry.instance)
				if text then
					local path, saveError = Extractor.save(Extractor.fileName(entry, how), text)
					if path then
						report.saved += 1
					else
						report.skipped += 1
						table.insert(report.reasons, ("%s: %s"):format(entry.name, tostring(saveError)))
					end
				else
					report.skipped += 1
					table.insert(report.reasons, ("%s: %s"):format(entry.name, tostring(why)))
				end
			end
			return report
		end

		-- ==========================================================================
		-- Tab
		-- ==========================================================================

		local function mount(page)
			local section = page:Section("Scripts", 1)
			local status = Materials.Status(section.frame, "not scanned", "info")
			local output = Materials.Code(section.frame, { Height = 300 })
			local listing = {}

			Materials.Button(section.frame, {
				Text = "List scripts",
				OnClick = function()
					listing = Extractor.sources()
					local lines = {}
					for index, entry in listing do
						table.insert(lines, ("%3d  %-14s %s"):format(index, entry.class, entry.name))
					end
					output:SetLines(#lines > 0 and lines or { "No scripts reachable." }, 300)
					status:Set(("%d script(s)"):format(#listing), #listing > 0 and "on" or "warn")
				end,
			})

			local indexField = Materials.Input(section.frame, { Text = "Index from the list", Default = "1" })

			Materials.Button(section.frame, {
				Text = "Decompile one",
				OnClick = function()
					local index = math.floor(tonumber(indexField:Get()) or 0)
					local entry = listing[index]
					if not entry then
						output:SetLines({ "Run 'List scripts' first, then pick an index from it." })
						return
					end
					local text, how, why = Extractor.source(entry.instance)
					if not text then
						output:SetLines({ ("%s: %s"):format(entry.name, tostring(why)) })
						return
					end
					local lines = { ("-- %s (%s) via %s"):format(entry.name, entry.class, how) }
					for line in (text .. "\n"):gmatch("([^\n]*)\n") do
						table.insert(lines, line)
					end
					output:SetLines(lines, 400)
					status:Set(("showing %s (%s)"):format(entry.name, how), how == "source" and "on" or "warn")
				end,
			})

			Materials.Button(section.frame, {
				Text = "Extract everything",
				OnClick = function()
					local report = Extractor.extractAll({
						onProgress = function(done, total, name)
							if done % 10 == 0 or done == total then
								status:Set(("%d/%d · %s"):format(done, total, name), "info")
							end
						end,
					})
					local lines = {
						("saved %d, skipped %d to %s"):format(report.saved, report.skipped, Extractor.OUTPUT),
					}
					for index = 1, math.min(#report.reasons, 40) do
						table.insert(lines, report.reasons[index])
					end
					output:SetLines(lines, 300)
					status:Set(("saved %d"):format(report.saved), report.saved > 0 and "on" or "off")
				end,
			})

			local tools = page:Section("Capabilities", 2)
			local lines = {
				("getscriptbytecode: %s"):format(Core.env.getscriptbytecode ~= nil and "yes" or "no"),
				("getscriptclosure: %s"):format(Core.env.getscriptclosure ~= nil and "yes" or "no"),
				("getnilinstances: %s"):format(Core.env.getnilinstances ~= nil and "yes" or "no"),
				("decompiler: %s"):format(Extractor.canDecompile() and "yes" or "no"),
				("writefile: %s"):format(Core.env.writefile ~= nil and "yes" or "no"),
			}
			Materials.Code(tools.frame, { Height = 132, Lines = table.concat(lines, "\n") })
			Materials.Label(tools.frame,
				"When no decompiler is installed, extraction returns bytecode and says so. "
				.. "That is the honest result: the client never holds server source text.")

			return { extract = Extractor.extractAll }
		end

		Extractor.mount = mount

		return function(core, materials)
			Core = core
			Materials = materials
			return Extractor
		end
	end)()
	Modules['FatCatExtractor'] = module
end
-- ---------------------------------------------------------------------
-- FatCatDecompiler.lua
-- ---------------------------------------------------------------------
do
	local module = (function()
		-- Fat Cat Project | Advanced Analysis/FatCatDecompiler.lua
		--
		-- A decompiler front end: pick a script, call the executor's decompiler, show
		-- the result with line numbers, and save it. Nothing here is a decompiler
		-- itself — writing one is a year of work and every serious executor already
		-- ships one. What is missing in practice is a UI that:
		--
		--   * refuses to call a nil function and says why, instead of throwing;
		--   * falls back from decompile → getscriptclosure → getscriptbytecode in a
		--     defined order, and reports which one it used;
		--   * keeps the last 20 results so a second look does not re-run the work;
		--   * writes to a predictable folder with a predictable name.
		--
		--   local D = FatCat.require("FatCatDecompiler")
		--   local text, how = D.decompile(scriptInstance)
		--   D.open(text)               -- fill the tab's code view
		--   D.save("Remote.lua", text)

		local Core, Materials, Decompiler
		Decompiler = {}

		Decompiler.OUTPUT = "FatCatProject/decompiled"
		Decompiler.MAX_CACHE = 20
		Decompiler.cache = {}          -- name -> { text = string, how = string, at = number }

		-- ==========================================================================
		-- Decompiler discovery
		-- ==========================================================================

		local KNOWN = { "decompile", "decompilefunction", "decompiler" }

		---The decompiler this executor has, or nil.
		function Decompiler.impl()
			for _, name in KNOWN do
				local fn = Core.env[name]
				if type(fn) == "function" then
					return fn, name
				end
			end
			local ok, module = pcall(require, "decompiler")
			if ok and type(module) == "function" then
				return module, "require(decompiler)"
			end
			return nil
		end

		---True/false plus a sentence for the status row.
		function Decompiler.available()
			local _, name = Decompiler.impl()
			if name then
				return true, name .. "()"
			end
			return false, "no decompiler on this executor"
		end

		-- ==========================================================================
		-- Decompile
		-- ==========================================================================

		local function closureFor(instance)
			local getClosure = Core.env.getscriptclosure
			if type(getClosure) ~= "function" then
				return nil
			end
			local ok, result = pcall(getClosure, instance)
			if ok then
				return result
			end
			return nil
		end

		local function cacheGet(key)
			for _, entry in Decompiler.cache do
				if entry.key == key then
					return entry
				end
			end
			return nil
		end

		local function cachePut(entry)
			table.insert(Decompiler.cache, entry)
			while #Decompiler.cache > Decompiler.MAX_CACHE do
				table.remove(Decompiler.cache, 1)
			end
		end

		---Decompile one script. Returns text, how, or nil plus a reason.
		---`how` is "decompiled", "source" or "bytecode".
		function Decompiler.decompile(instance, options)
			options = options or {}
			if not instance then
				return nil, nil, "no script selected"
			end

			local key = tostring(instance) .. instance.Name
			if not options.refresh then
				local hit = cacheGet(key)
				if hit then
					return hit.text, hit.how
				end
			end

			-- 1. The client's own Source, when the executor exposes it at all.
			local ok, source = pcall(function()
				return instance.Source
			end)
			if ok and type(source) == "string" and source ~= "" then
				cachePut({ key = key, text = source, how = "source", at = os.clock() })
				return source, "source"
			end

			-- 2. The executor's decompiler, on the script's closure.
			local impl, implName = Decompiler.impl()
			if impl then
				local closure = closureFor(instance)
				if closure then
					local success, text = pcall(impl, closure)
					if success and type(text) == "string" and text ~= "" then
						cachePut({ key = key, text = text, how = "decompiled", at = os.clock() })
						return text, "decompiled"
					end
					if not success then
						Core:Log("warn", ("%s failed on %s: %s"):format(
							tostring(implName), instance.Name, tostring(text)))
					end
				end
				-- Some builds accept the instance directly.
				local direct, directText = pcall(impl, instance)
				if direct and type(directText) == "string" and directText ~= "" then
					cachePut({ key = key, text = directText, how = "decompiled", at = os.clock() })
					return directText, "decompiled"
				end
			end

			-- 3. Bytecode as hex, which is what is left when there is no decompiler.
			local getBytecode = Core.env.getscriptbytecode
			if type(getBytecode) == "function" then
				local success, raw = pcall(getBytecode, instance)
				if success and type(raw) == "string" and raw ~= "" then
					local parts = {}
					for index = 1, math.min(#raw, 100000) do
						parts[#parts + 1] = ("%02x"):format(string.byte(raw, index))
					end
					local text = table.concat(parts)
					cachePut({ key = key, text = text, how = "bytecode", at = os.clock() })
					return text, "bytecode"
				end
			end

			return nil, nil, "no source, no decompiler, no bytecode: this script cannot be read"
		end

		-- ==========================================================================
		-- Output helpers
		-- ==========================================================================

		---Number every line: "  12 | local x = 1". A decompiled listing without line
		---numbers is a listing nobody can point at in a bug report.
		function Decompiler.numbered(text)
			local lines = {}
			local index = 0
			for line in (text .. "\n"):gmatch("([^\n]*)\n") do
				index += 1
				table.insert(lines, ("%4d | %s"):format(index, line))
				-- A 20 000-line script would freeze the label; 2 000 is plenty to
				-- read and the rest is saved to disk instead.
				if index >= 2000 then
					table.insert(lines, "… truncated; save the file to see the rest")
					break
				end
			end
			return lines
		end

		---Write text to the project folder.
		function Decompiler.save(fileName, text)
			if type(text) ~= "string" then
				return nil, "nothing to save"
			end
			local write = Core.env.writefile
			if type(write) ~= "function" then
				return nil, "this executor has no writefile()"
			end
			local makeFolder = Core.env.makefolder
			if type(makeFolder) == "function" then
				pcall(makeFolder, "FatCatProject")
				pcall(makeFolder, Decompiler.OUTPUT)
			end
			local safe = tostring(fileName):gsub("[^%w_%-%. ]", "_")
			if not safe:match("%.luau?$") then
				safe ..= ".lua"
			end
			local path = Decompiler.OUTPUT .. "/" .. safe
			local ok, err = pcall(write, path, text)
			if not ok then
				return nil, tostring(err)
			end
			return path
		end

		-- ==========================================================================
		-- Tab
		-- ==========================================================================

		local function mount(page)
			local section = page:Section("Decompiler", 1)
			local ok, how = Decompiler.available()
			local status = Materials.Status(section.frame, how, ok and "on" or "warn")
			local output = Materials.Code(section.frame, { Height = 320 })

			local listing = {}

			Materials.Button(section.frame, {
				Text = "List scripts",
				OnClick = function()
					local Extractor = Core:TryRequire("FatCatExtractor")
					if not Extractor then
						output:SetLines({ "FatCatExtractor failed to load." })
						return
					end
					listing = Extractor.sources()
					local lines = {}
					for index, entry in listing do
						table.insert(lines, ("%3d  %s"):format(index, entry.name))
					end
					output:SetLines(#lines > 0 and lines or { "No scripts reachable." }, 300)
					status:Set(("%d script(s)"):format(#listing), "info")
				end,
			})

			local pick = Materials.Input(section.frame, { Text = "Index", Default = "1" })

			local function show(index)
				local entry = listing[index]
				if not entry then
					output:SetLines({ "List scripts first, then type an index from that list." })
					return
				end
				local text, method, why = Decompiler.decompile(entry.instance)
				if not text then
					output:SetLines({ ("%s: %s"):format(entry.name, tostring(why)) })
					status:Set("failed", "off")
					return
				end
				output:SetLines(Decompiler.numbered(text), 400)
				status:Set(("%s via %s · %d byte(s)"):format(entry.name, method, #text), "on")
			end

			Materials.Button(section.frame, {
				Text = "Decompile",
				OnClick = function()
					show(math.floor(tonumber(pick:Get()) or 0))
				end,
			})
			Materials.Button(section.frame, {
				Text = "Save this result",
				OnClick = function()
					local entry = listing[math.floor(tonumber(pick:Get()) or 0)]
					if not entry then
						return
					end
					local text = Decompiler.decompile(entry.instance)
					if type(text) ~= "string" then
						return
					end
					local path, err = Decompiler.save(entry.name, text)
					status:Set(path or tostring(err), path and "on" or "off")
				end,
			})

			local notes = page:Section("Notes", 2)
			Materials.Label(notes.frame,
				"Source is tried first, then the executor's decompiler, then bytecode. "
				.. "The status row says which one produced what you are reading.")
			Materials.Label(notes.frame,
				("Results are cached (last %d), so opening the same script twice does not re-run the decompiler.")
					:format(Decompiler.MAX_CACHE))

			return { show = show, save = Decompiler.save }
		end

		Decompiler.mount = mount

		return function(core, materials)
			Core = core
			Materials = materials
			return Decompiler
		end
	end)()
	Modules['FatCatDecompiler'] = module
end
-- ---------------------------------------------------------------------
-- FatCatStealer.lua
-- ---------------------------------------------------------------------
do
	local module = (function()
		-- Fat Cat Project | Advanced Analysis/FatCatStealer.lua
		--
		-- Asset stealer: copies what the client already has — images, sounds, meshes,
		-- animations — into a local folder, and writes a manifest with asset ids,
		-- sizes and the script that referenced them.
		--
		--   local S = FatCat.require("FatCatStealer")
		--   local assets = S.collect()        -- scan instances for asset ids
		--   S.download(assets)                -- optional: fetch and save the bytes
		--   S.manifest(assets)                -- JSON-safe table
		--
		-- The honest version of this feature, and why it looks like this:
		--
		--   * every asset it finds is *already* downloaded to the client's cache. The
		--     scan lists ids; nothing is extracted from another player or a server.
		--   * downloading requires the executor's `request`/`http_request` and the
		--     asset's id to be public. A private asset returns 403 and this module
		--     reports that instead of writing a zero-byte file.
		--   * a mesh's geometry is not an asset URL: Roblox serves meshes through a
		--     separate endpoint and most executors block it. The scan reports the id
		--     and the file type it would be, not a promise.
		--
		-- What this does NOT do: no credential theft, no session tokens, no reading
		-- another user's data. "Stealer" here means "asset collector", and the code is
		-- written so it cannot be mistaken for the other thing.

		local Core, Materials, Stealer
		Stealer = {}

		Stealer.OUTPUT = "FatCatProject/assets"

		-- Instance class -> the property that holds the asset id and its file type.
		local SOURCES = {
			{ class = "Decal", property = "Texture", kind = "png" },
			{ class = "Texture", property = "Texture", kind = "png" },
			{ class = "ImageLabel", property = "Image", kind = "png" },
			{ class = "ImageButton", property = "Image", kind = "png" },
			{ class = "Sky", property = "SkyboxUp", kind = "png" },
			{ class = "Sound", property = "SoundId", kind = "ogg" },
			{ class = "MeshPart", property = "MeshId", kind = "mesh" },
			{ class = "SpecialMesh", property = "MeshId", kind = "mesh" },
			{ class = "Animation", property = "AnimationId", kind = "rbxm" },
		}

		-- ==========================================================================
		-- Collection
		-- ==========================================================================

		---`rbxassetid://123456` or `rbxasset://textures/x.png` -> 123456 / nil.
		local function assetId(url)
			if type(url) ~= "string" then
				return nil
			end
			local digits = url:match("rbxassetid://(%d+)")
			if digits then
				return tonumber(digits)
			end
			return nil
		end
		Stealer.assetId = assetId

		local function scanRoot(root, found, seen, limit)
			if not root or #found >= limit then
				return
			end
			local walkable, descendants = pcall(function()
				return root:GetDescendants()
			end)
			if not walkable then
				return
			end
			for _, instance in descendants do
				if #found >= limit then
					return
				end
				for _, source in SOURCES do
					if instance:IsA(source.class) then
						local ok, url = pcall(function()
							return (instance :: any)[source.property]
						end)
						if ok then
							local id = assetId(url)
							if id and not seen[id] then
								seen[id] = true
								table.insert(found, {
									id = id,
									kind = source.kind,
									class = source.class,
									property = source.property,
									name = instance.Name,
									url = url,
								})
							end
						end
					end
				end
			end
		end

		---Every asset id the client is already using.
		function Stealer.collect(limit)
			limit = limit or 500
			local found, seen = {}, {}
			scanRoot(game:GetService("Workspace"), found, seen, limit)
			scanRoot(game:GetService("ReplicatedStorage"), found, seen, limit)
			scanRoot(game:GetService("ReplicatedFirst"), found, seen, limit)
			scanRoot(game:GetService("StarterGui"), found, seen, limit)
			scanRoot(game:GetService("Lighting"), found, seen, limit)
			local players = game:GetService("Players")
			for _, other in players:GetPlayers() do
				if other.Character then
					scanRoot(other.Character, found, seen, limit)
				end
			end
			return found
		end

		-- ==========================================================================
		-- Download
		-- ==========================================================================

		local function httpGet(url)
			local request = Core.env.request or Core.env.http_request
			if type(request) ~= "function" then
				return nil, "this executor has no request()/http_request()"
			end
			local ok, response = pcall(request, { Url = url, Method = "GET" })
			if not ok then
				return nil, tostring(response)
			end
			if type(response) ~= "table" then
				return nil, "the http client returned no response table"
			end
			if response.StatusCode and response.StatusCode ~= 200 then
				return nil, ("HTTP %s"):format(tostring(response.StatusCode))
			end
			return response.Body or response.body
		end

		---Filesystem name for an asset.
		function Stealer.fileName(asset)
			return ("%s_%d.%s"):format(asset.name:gsub("[^%w_%-]", "_"), asset.id, asset.kind)
		end

		---Download one asset and write it. Returns path or nil, reason.
		function Stealer.fetch(asset)
			local write = Core.env.writefile
			if type(write) ~= "function" then
				return nil, "this executor has no writefile()"
			end

			local url
			if asset.kind == "mesh" then
				-- Meshes do not come from the asset CDN; the endpoint that serves them
				-- is not available to most executors.
				return nil, "mesh geometry is not downloadable from the client"
			elseif asset.kind == "rbxm" then
				url = ("https://assetdelivery.roblox.com/v1/asset/?id=%d"):format(asset.id)
			else
				url = ("https://assetdelivery.roblox.com/v1/asset/?id=%d"):format(asset.id)
			end

			local body, errorText = httpGet(url)
			if not body then
				return nil, errorText
			end
			if #body == 0 then
				return nil, "the asset returned an empty body (private asset?)"
			end

			local makeFolder = Core.env.makefolder
			if type(makeFolder) == "function" then
				pcall(makeFolder, "FatCatProject")
				pcall(makeFolder, Stealer.OUTPUT)
			end
			local path = Stealer.OUTPUT .. "/" .. Stealer.fileName(asset)
			local ok, err = pcall(write, path, body)
			if not ok then
				return nil, tostring(err)
			end
			return path, #body
		end

		---A JSON-safe manifest: what was found, where it is used, and what was saved.
		function Stealer.manifest(assets, saved)
			local rows = {}
			for _, asset in assets or {} do
				table.insert(rows, {
					id = asset.id,
					kind = asset.kind,
					class = asset.class,
					property = asset.property,
					name = asset.name,
					url = asset.url,
				})
			end
			return {
				generatedAt = os.time(),
				count = #rows,
				saved = saved or 0,
				assets = rows,
			}
		end

		---Write the manifest next to the files.
		function Stealer.saveManifest(assets, savedCount)
			local ok, text = pcall(function()
				return game:GetService("HttpService"):JSONEncode(Stealer.manifest(assets, savedCount))
			end)
			if not ok then
				return nil, "HttpService could not encode the manifest"
			end
			local write = Core.env.writefile
			if type(write) ~= "function" then
				return nil, "this executor has no writefile()"
			end
			local path = Stealer.OUTPUT .. "/manifest.json"
			local wrote, err = pcall(write, path, text)
			if not wrote then
				return nil, tostring(err)
			end
			return path
		end

		-- ==========================================================================
		-- Tab
		-- ==========================================================================

		local function mount(page)
			local section = page:Section("Assets in this game", 1)
			local status = Materials.Status(section.frame, "not scanned", "info")
			local output = Materials.Code(section.frame, { Height = 300 })
			local assets = {}

			Materials.Button(section.frame, {
				Text = "Scan",
				OnClick = function()
					assets = Stealer.collect()
					local counts = {}
					for _, asset in assets do
						counts[asset.kind] = (counts[asset.kind] or 0) + 1
					end
					local lines = {}
					for kind, count in counts do
						table.insert(lines, ("%s: %d"):format(kind, count))
					end
					table.sort(lines)
					for index = 1, math.min(#assets, 60) do
						local asset = assets[index]
						table.insert(lines, ("%d  %s  %s.%s"):format(
							asset.id, asset.kind, asset.class, asset.property))
					end
					output:SetLines(lines, 300)
					status:Set(("%d asset(s)"):format(#assets), #assets > 0 and "on" or "warn")
				end,
			})

			Materials.Button(section.frame, {
				Text = "Download images and sounds",
				OnClick = function()
					if #assets == 0 then
						output:SetLines({ "Scan first." })
						return
					end
					local saved, skipped, reasons = 0, 0, {}
					for _, asset in assets do
						if asset.kind == "mesh" or asset.kind == "rbxm" then
							skipped += 1
						else
							local path, why = Stealer.fetch(asset)
							if path then
								saved += 1
							else
								skipped += 1
								if #reasons < 8 then
									table.insert(reasons, ("%d: %s"):format(asset.id, tostring(why)))
								end
							end
						end
					end
					Stealer.saveManifest(assets, saved)
					local lines = { ("saved %d, skipped %d"):format(saved, skipped) }
					for _, reason in reasons do
						table.insert(lines, reason)
					end
					output:SetLines(lines, 300)
					status:Set(("saved %d"):format(saved), saved > 0 and "on" or "off")
				end,
			})

			local notes = page:Section("What this can and cannot do", 2)
			Materials.Label(notes.frame,
				"Everything listed is already downloaded to this client; the scan only reads ids from instances.")
			Materials.Label(notes.frame,
				"Images and sounds can be fetched when the asset is public. Private assets return 403 and are reported, not saved as empty files.")
			Materials.Label(notes.frame,
				"Mesh geometry is served from a different endpoint that most executors block, so meshes are listed but never reported as saved.")

			return { collect = Stealer.collect, assets = function()
				return assets
			end }
		end

		Stealer.mount = mount

		return function(core, materials)
			Core = core
			Materials = materials
			return Stealer
		end
	end)()
	Modules['FatCatStealer'] = module
end
-- ---------------------------------------------------------------------
-- FatCatSpy.lua
-- ---------------------------------------------------------------------
do
	local module = (function()
		-- Fat Cat Project | Advanced Analysis/FatCatSpy.lua
		--
		-- Remote spy: logs every RemoteEvent / RemoteFunction the client fires or
		-- receives, with argument types and a short preview of each value.
		--
		--   local Spy = FatCat.require("FatCatSpy")
		--   Spy.start()                       -- hook and begin logging
		--   Spy.stop()                        -- restore the originals
		--   Spy.entries                       -- ring buffer, newest last
		--   Spy.subscribe(function(entry) ... end)
		--
		-- How the hook works, and why it is written this way:
		--
		--   * the originals are looked up once and stored, so stop() restores exactly
		--     what was there before and can never leave a remote permanently wrapped;
		--   * every hook is wrapped in newcclosure when the executor has it, so the
		--     game cannot detect a foreign Luau closure on the remote;
		--   * the call is passed through with pcall and the original error is
		--     re-raised: a spy that swallows errors would hide the game's own bugs;
		--   * arguments are rendered eagerly into strings, not stored as references.
		--     A RemoteEvent argument can be a table the game mutates a frame later;
		--     keeping the reference would make every log entry show the final state.
		--
		-- This is a diagnostic. It does not modify arguments, drop calls, or replay
		-- them, and that is on purpose: a spy that can also forge remotes is a griefing
		-- tool, not an analysis one.

		local Core, Signal, Materials, Spy
		Spy = {}

		Spy.MAX_ENTRIES = 200
		Spy.entries = {}
		Spy.listening = false

		local originals = {}   -- remote -> { FireServer = fn, ... }
		local subscriptions = {}
		local changed = nil

		-- ==========================================================================
		-- Argument rendering
		-- ==========================================================================

		local function describe(value, depth)
			depth = depth or 0
			local kind = typeof(value)
			if kind == "string" then
				local shown = value
				if #shown > 60 then
					shown = shown:sub(1, 57) .. "..."
				end
				return ("%q"):format(shown)
			elseif kind == "number" or kind == "boolean" or kind == "nil" then
				return tostring(value)
			elseif kind == "Instance" then
				return ("%s[%s]"):format(value.Name, value.ClassName)
			elseif kind == "Vector3" then
				return ("V3(%.1f, %.1f, %.1f)"):format(value.X, value.Y, value.Z)
			elseif kind == "CFrame" then
				local p = value.Position
				return ("CF(%.0f, %.0f, %.0f)"):format(p.X, p.Y, p.Z)
			elseif kind == "Color3" then
				return ("RGB(%d, %d, %d)"):format(
					math.round(value.R * 255), math.round(value.G * 255), math.round(value.B * 255))
			elseif kind == "table" then
				if depth >= 1 then
					return "{...}"
				end
				local parts = {}
				local count = 0
				for key, entry in value do
					count += 1
					if count > 6 then
						table.insert(parts, "…")
						break
					end
					table.insert(parts, ("%s=%s"):format(tostring(key), describe(entry, depth + 1)))
				end
				return "{" .. table.concat(parts, ", ") .. "}"
			elseif kind == "userdata" then
				return "<userdata>"
			end
			return ("<%s>"):format(kind)
		end

		Spy.describe = describe

		local function describeAll(...)
			local count = select("#", ...)
			local parts = {}
			for index = 1, count do
				table.insert(parts, describe(select(index, ...)))
			end
			return table.concat(parts, ", ")
		end

		-- ==========================================================================
		-- Ring buffer
		-- ==========================================================================

		local function push(entry)
			table.insert(Spy.entries, entry)
			while #Spy.entries > Spy.MAX_ENTRIES do
				table.remove(Spy.entries, 1)
			end
			if changed then
				changed:Fire(entry)
			end
			for _, handler in subscriptions do
				pcall(handler, entry)
			end
		end

		---Subscribe to new entries. Returns an unsubscribe function.
		function Spy.subscribe(handler)
			table.insert(subscriptions, handler)
			return function()
				for index = #subscriptions, 1, -1 do
					if subscriptions[index] == handler then
						table.remove(subscriptions, index)
					end
				end
			end
		end

		---Clear the log without stopping the hook.
		function Spy.clear()
			table.clear(Spy.entries)
		end

		-- ==========================================================================
		-- Hooks
		-- ==========================================================================

		local function hookMethod(remote, methodName, direction, namecallName)
			local original = (remote :: any)[methodName]
			if type(original) ~= "function" then
				return false
			end

			originals[remote] = originals[remote] or {}
			originals[remote][methodName] = original

			local replacement = function(self, ...)
				-- checkcaller tells us the call came from executor code (us) rather
				-- than from the game; only the game's calls are interesting.
				local fromGame = true
				if Spy._checkCaller then
					local ok, result = pcall(Spy._checkCaller)
					fromGame = ok and not result
				end

				if fromGame then
					push({
						remote = remote,
						name = remote.Name,
						className = remote.ClassName,
						method = namecallName or methodName,
						direction = direction,
						args = describeAll(...),
						time = os.clock(),
					})
				end

				local results = table.pack(original(self, ...))
				return table.unpack(results, 1, results.n)
			end

			local expose = Core.env.newcclosure
			if type(expose) == "function" then
				local ok, wrapped = pcall(expose, replacement)
				if ok then
					replacement = wrapped
				end
			end

			(remote :: any)[methodName] = replacement
			return true
		end

		local function restoreAll()
			for remote, methods in originals do
				for methodName, original in methods do
					pcall(function()
						(remote :: any)[methodName] = original
					end)
				end
			end
			table.clear(originals)
		end

		---Start spying. Returns true, and the number of remotes hooked.
		function Spy.start()
			if Spy.listening then
				return true, #originals
			end
			if Core.env.checkcaller then
				Spy._checkCaller = Core.env.checkcaller
			end

			local hooked = 0
			local function visit(parent)
				if not parent then
					return
				end
				local ok, descendants = pcall(function()
					return parent:GetDescendants()
				end)
				if not ok then
					return
				end
				for _, child in descendants do
					if child:IsA("RemoteEvent") then
						if hookMethod(child, "FireServer", "→") then
							hooked += 1
						end
						if hookMethod(child, "OnClientEvent", "←") then
							hooked += 1
						end
					elseif child:IsA("RemoteFunction") then
						if hookMethod(child, "InvokeServer", "→", "InvokeServer") then
							hooked += 1
						end
						if hookMethod(child, "OnClientInvoke", "←", "OnClientInvoke") then
							hooked += 1
						end
					elseif child:IsA("UnreliableRemoteEvent") then
						if hookMethod(child, "FireServer", "→") then
							hooked += 1
						end
					elseif child:IsA("BindableEvent") then
						if hookMethod(child, "Fire", "·", "Fire") then
							hooked += 1
						end
					end
				end
			end

			visit(game:GetService("ReplicatedStorage"))
			visit(game:GetService("ReplicatedFirst"))
			visit(game:GetService("Workspace"))

			Spy.listening = true
			Core:OnDestroy("spy", Spy.stop)
			return true, hooked
		end

		---Restore every hooked remote.
		function Spy.stop()
			if not Spy.listening then
				return true
			end
			restoreAll()
			Spy.listening = false
			return true
		end

		---Readable log: one line per entry, newest last.
		function Spy.report()
			local lines = {}
			for _, entry in Spy.entries do
				table.insert(lines, ("%6.2f %s %s:%s(%s)"):format(
					entry.time % 1000, entry.direction, entry.name, entry.method, entry.args))
			end
			return table.concat(lines, "\n")
		end

		-- ==========================================================================
		-- Tab
		-- ==========================================================================

		local function mount(page)
			local section = page:Section("Remote spy", 1)
			local status = Materials.Status(section.frame, "stopped", "off")
			local output = Materials.Code(section.frame, { Height = 300 })
			local live = {}

			Materials.Button(section.frame, {
				Text = "Start",
				OnClick = function()
					local ok, count = Spy.start()
					if ok then
						status:Set(("listening · %d hook(s)"):format(count or 0), "on")
					else
						status:Set(tostring(count), "off")
					end
				end,
			})
			Materials.Button(section.frame, {
				Text = "Stop",
				Danger = true,
				OnClick = function()
					Spy.stop()
					status:Set("stopped", "off")
				end,
			})
			Materials.Button(section.frame, {
				Text = "Clear",
				OnClick = function()
					Spy.clear()
					table.clear(live)
					output:SetLines({})
				end,
			})

			Spy.subscribe(function(entry)
				table.insert(live, ("%s %s:%s(%s)"):format(
					entry.direction, entry.name, entry.method, entry.args))
				while #live > 200 do
					table.remove(live, 1)
				end
				output:SetLines(live, 200)
				output:ScrollToBottom()
			end)

			return { clear = Spy.clear, entries = function()
				return Spy.entries
			end }
		end

		Spy.mount = mount

		return function(core, signal, materials)
			Core = core
			Signal = signal
			Materials = materials
			changed = Signal.new("spy:entry")
			return Spy
		end
	end)()
	Modules['FatCatSpy'] = module
end
-- ---------------------------------------------------------------------
-- FatCatProjectiles.lua
-- ---------------------------------------------------------------------
do
	local module = (function()
		-- Fat Cat Project | Advanced Analysis/FatCatProjectiles.lua
		--
		-- Reads the projectile table out of a game's scripts and predicts where a
		-- shot will land, so the trajectory line and the aim assist agree with the
		-- game's own physics instead of a guess.
		--
		--   local P = FatCat.require("FatCatProjectiles")
		--   P.scan()                     -- find { Speed = ..., Gravity = ... } in loaded scripts
		--   P.set({ Speed = 300, Gravity = 196.2 })
		--   P.lead(muzzle, target, velocity)   -- Vector3 or nil
		--   P.arc(origin, direction)           -- points for a trail
		--
		-- Where the numbers come from. There are three sources, in order of trust:
		--
		--   1. the user, on the Projectiles tab: a speed and a gravity, typed in;
		--   2. scanning loaded scripts for a module table that has both a speed-like
		--      and a gravity-like field (see `scan`);
		--   3. the engine default (workspace.Gravity, no drag).
		--
		-- The scan is heuristic by design: it reports candidates instead of picking
		-- one, because two plausible tables in a game is a decision the user should
		-- make, not this module. Nothing is written back — the table stays the game's.

		local Core, Math2, Materials, Projectiles
		Projectiles = {}

		Projectiles.current = { Speed = 300, Gravity = 196.2, Drag = 0 }

		-- Field names seen in the wild for the two numbers that matter.
		local SPEED_KEYS = { "Speed", "Velocity", "MuzzleVelocity", "ProjectileSpeed", "speed", "velocity" }
		local GRAVITY_KEYS = { "Gravity", "gravity", "Grav", "DropConstant", "Arc" }

		-- ==========================================================================
		-- Scanning
		-- ==========================================================================

		local function numeric(tableValue, keys)
			for _, key in keys do
				local value = tableValue[key]
				if type(value) == "number" and value > 0 then
					return value, key
				end
			end
			return nil
		end

		---Walk gc objects looking for tables shaped like a projectile config.
		---Returns candidates: { table, speed, gravity, path }.
		function Projectiles.scan(limit)
			limit = limit or 4000
			local candidates = {}
			local seen = {}
			local gc = Core.env.getgc
			if type(gc) ~= "function" then
				return candidates, "getgc is not available on this executor"
			end

			local ok, objects = pcall(gc, true)
			if not ok then
				return candidates, "getgc failed: " .. tostring(objects)
			end

			local visited = 0
			for _, object in objects do
				visited += 1
				if visited > limit then
					break
				end
				if type(object) == "table" and not seen[object] then
					seen[object] = true
					local speed, speedKey = numeric(object, SPEED_KEYS)
					if speed then
						local gravity, gravityKey = numeric(object, GRAVITY_KEYS)
						if gravity then
							table.insert(candidates, {
								table = object,
								speed = speed,
								speedKey = speedKey,
								gravity = gravity,
								gravityKey = gravityKey,
							})
							if #candidates >= 40 then
								break
							end
						end
					end
				end
			end

			return candidates
		end

		---Use a specific config. `values` = { Speed = number, Gravity = number }.
		function Projectiles.set(values)
			if type(values) ~= "table" then
				return false, "pass a table with Speed and Gravity"
			end
			local speed = tonumber(values.Speed)
			local gravity = tonumber(values.Gravity)
			if not speed or speed <= 0 then
				return false, "Speed must be a positive number"
			end
			if not gravity then
				return false, "Gravity must be a number"
			end
			Projectiles.current = {
				Speed = speed,
				Gravity = gravity,
				Drag = tonumber(values.Drag) or 0,
			}
			return true, Projectiles.current
		end

		---Fall back to the engine's own gravity, with no drag.
		function Projectiles.useEngineGravity()
			Projectiles.current = {
				Speed = Projectiles.current.Speed,
				Gravity = workspace.Gravity,
				Drag = 0,
			}
			return Projectiles.current
		end

		-- ==========================================================================
		-- Prediction
		-- ==========================================================================

		---Lead point for the current config. Returns Vector3 or nil plus a reason.
		function Projectiles.lead(muzzle, target, targetVelocity)
			if not (muzzle and target and targetVelocity) then
				return nil, "muzzle, target and velocity are required"
			end
			local config = Projectiles.current
			if config.Drag and config.Drag > 0 then
				-- With drag the closed form no longer holds; a numerical search is the
				-- honest answer, and it is cheap at this scale.
				return Projectiles.leadWithDrag(muzzle, target, targetVelocity, config)
			end
			local point = Math2.predict(muzzle, target, targetVelocity, config.Speed)
			if not point then
				return nil, ("the target outruns a %d stud/s projectile"):format(config.Speed)
			end
			return point
		end

		---Simulate forward in small steps, compare distance to the moving target,
		---keep the closest approach. Coarse then fine: 64 steps over 3 seconds, then
		---16 steps around the best one.
		function Projectiles.leadWithDrag(muzzle, target, targetVelocity, config)
			local function simulate(dt, frames)
				local position = muzzle
				local velocity = (target - muzzle).Unit * config.Speed
				local bestT, bestDistance = nil, math.huge
				for frame = 1, frames do
					local t = frame * dt
					local dragFactor = math.max(0, 1 - config.Drag * t)
					position += velocity * dt * dragFactor
					local targetAt = target + targetVelocity * t
					local distance = (position - targetAt).Magnitude
					if distance < bestDistance then
						bestDistance, bestT = distance, t
					end
				end
				return bestT, bestDistance
			end

			local coarseT = simulate(3 / 64, 64)
			if not coarseT then
				return nil, "no intercept found"
			end
			-- Refine around the coarse hit.
			local start = math.max(coarseT - 3 / 64, 0)
			local best, bestDistance = nil, math.huge
			for index = 0, 16 do
				local t = start + (3 / 64) * (index / 16)
				local dragFactor = math.max(0, 1 - config.Drag * t)
				local position = muzzle + (target - muzzle).Unit * config.Speed * t * dragFactor
				local distance = (position - (target + targetVelocity * t)).Magnitude
				if distance < bestDistance then
					bestDistance, best = distance, t
				end
			end
			if not best then
				return nil, "no intercept found"
			end
			return target + targetVelocity * best
		end

		---Points of the arc for a trail, using the current config.
		function Projectiles.arc(origin, direction, steps, duration)
			local config = Projectiles.current
			local velocity = direction.Unit * config.Speed
			duration = duration or 1.2
			steps = steps or 24
			if config.Drag and config.Drag > 0 then
				-- With drag the path is not a parabola; integrate it.
				local points = {}
				local position = origin
				local currentVelocity = velocity
				local dt = duration / steps
				for index = 0, steps do
					points[index + 1] = position
					position += currentVelocity * dt
					currentVelocity = Vector3.new(
						currentVelocity.X * (1 - config.Drag * dt),
						currentVelocity.Y + (-config.Gravity) * dt,
						currentVelocity.Z * (1 - config.Drag * dt)
					)
				end
				return points
			end
			return Math2.arc(origin, velocity, Vector3.new(0, -config.Gravity, 0), duration, steps)
		end

		---Where the arc crosses a horizontal plane, e.g. the floor.
		function Projectiles.landing(origin, direction)
			local config = Projectiles.current
			local velocity = direction.Unit * config.Speed
			return Math2.arcLanding(origin, velocity, Vector3.new(0, -config.Gravity, 0), 0)
		end

		-- ==========================================================================
		-- Drawing
		-- ==========================================================================

		local trailFolder = nil

		---Draw the arc as thin parts. Returns the count drawn.
		function Projectiles.trail(origin, direction, points)
			Projectiles.clearTrail()
			local layer = workspace.CurrentCamera
			if not layer then
				return 0
			end
			local folder = Instance.new("Folder")
			folder.Name = "FatCatTrail"
			folder.Parent = layer
			trailFolder = folder

			points = points or Projectiles.arc(origin, direction)
			local drawn = 0
			for index = 1, #points - 1 do
				local a, b = points[index], points[index + 1]
				local part = Instance.new("Part")
				part.Anchored = true
				part.CanCollide = false
				part.CanQuery = false
				part.CastShadow = false
				part.Material = Enum.Material.Neon
				part.Color = Color3.fromRGB(94, 194, 255)
				part.Size = Vector3.new(0.06, 0.06, (b - a).Magnitude)
				part.CFrame = CFrame.lookAt(a, b)
				part.Parent = folder
				drawn += 1
			end
			return drawn
		end

		function Projectiles.clearTrail()
			if trailFolder then
				trailFolder:Destroy()
				trailFolder = nil
			end
		end

		-- ==========================================================================
		-- Tab
		-- ==========================================================================

		local function mount(page)
			local section = page:Section("Projectile config", 1)
			local config = Projectiles.current
			local speedField = Materials.Input(section.frame, {
				Text = "Speed (studs/s)",
				Default = tostring(config.Speed),
				OnSubmit = function(value)
					Projectiles.set({ Speed = tonumber(value) or config.Speed, Gravity = config.Gravity })
				end,
			})
			local gravityField = Materials.Input(section.frame, {
				Text = "Gravity",
				Default = tostring(config.Gravity),
				OnSubmit = function(value)
					Projectiles.set({ Speed = config.Speed, Gravity = tonumber(value) or config.Gravity })
				end,
			})
			Materials.Button(section.frame, {
				Text = "Use workspace gravity",
				OnClick = function()
					local values = Projectiles.useEngineGravity()
					gravityField:Set(values.Gravity)
				end,
			})

			local scanSection = page:Section("Found in scripts", 2)
			local scanOutput = Materials.Code(scanSection.frame, { Height = 260 })
			Materials.Button(scanSection.frame, {
				Text = "Scan loaded scripts",
				OnClick = function()
					local candidates, reason = Projectiles.scan()
					if #candidates == 0 then
						scanOutput:SetLines({ reason or "No projectile tables found. Set the values above." })
						return
					end
					local lines = {}
					for index, candidate in candidates do
						local entry = ("%d) Speed=%s (%s)  Gravity=%s (%s)"):format(
							index, tostring(candidate.speed), candidate.speedKey,
							tostring(candidate.gravity), candidate.gravityKey)
						table.insert(lines, entry)
						-- Clicking a candidate is out of scope for a code view; the
						-- first scan result can be applied with the button below.
					end
					scanOutput:SetLines(lines, 200)
					Projectiles._lastScan = candidates
				end,
			})
			Materials.Button(scanSection.frame, {
				Text = "Apply first match",
				OnClick = function()
					local candidates = Projectiles._lastScan
					if not candidates or #candidates == 0 then
						return
					end
					local first = candidates[1]
					Projectiles.set({ Speed = first.speed, Gravity = first.gravity })
					speedField:Set(first.speed)
					gravityField:Set(first.gravity)
				end,
			})

			Core:OnDestroy("projectiles:trail", Projectiles.clearTrail)
			return { speedField = speedField, gravityField = gravityField }
		end

		Projectiles.mount = mount

		return function(core, mathModule, materials)
			Core = core
			Math2 = mathModule
			Materials = materials
			return Projectiles
		end
	end)()
	Modules['FatCatProjectiles'] = module
end
-- ---------------------------------------------------------------------
-- FatCatVMHook.lua
-- ---------------------------------------------------------------------
do
	local module = (function()
		-- Fat Cat Project | Advanced Analysis/FatCatVMHook.lua
		--
		-- A small hook manager: install a wrapper on an executor function or a
		-- metatable method, observe or transform the call, and restore it exactly.
		--
		--   local Hook = FatCat.require("FatCatVMHook")
		--   local link = Hook.functionHook("HttpGet", function(original, url)
		--       print("fetched", url)
		--       return original(url)
		--   end)
		--   link:Remove()
		--
		--   local namecall = Hook.metamethod("__namecall", function(original, self, ...)
		--       return original(self, ...)
		--   end)
		--
		-- The rules this module enforces, because getting them wrong is how a script
		-- gets detected or leaves the game broken:
		--
		--   * every hook is registered before it is installed, so Remove() and the
		--     Unload teardown can always find it — a hook with no handle is a leak;
		--   * a wrapper receives the original as its first argument and MUST call it
		--     (except when it is deliberately blocking, which is opt-in via
		--     { passthrough = false });
		--   * newcclosure wraps every replacement when available, so the game sees a
		--     C closure rather than a Luau function;
		--   * Remove() restores the exact original reference and is idempotent.
		--
		-- This module never touches a function it did not hook, never edits a
		-- read-only table without restoring the read-only flag, and never writes to
		-- another process.

		local Core, Materials, Hook
		Hook = {}

		Hook.hooks = {}       -- list of records, in install order
		Hook.MAX_HOOKS = 64

		local function wrap(fn)
			local newcclosure = Core.env.newcclosure
			if type(newcclosure) == "function" then
				local ok, wrapped = pcall(newcclosure, fn)
				if ok and type(wrapped) == "function" then
					return wrapped
				end
			end
			return fn
		end

		local function record(kind, target, replacement, restore)
			local entry = {
				kind = kind,
				target = target,
				replacement = replacement,
				restore = restore,
				active = true,
			}
			table.insert(Hook.hooks, entry)

			function entry:Remove()
				if not self.active then
					return false
				end
				self.active = false
				pcall(self.restore)
				for index = #Hook.hooks, 1, -1 do
					if Hook.hooks[index] == self then
						table.remove(Hook.hooks, index)
					end
				end
				return true
			end
			return entry
		end

		---Number of live hooks.
		function Hook.count()
			return #Hook.hooks
		end

		---Remove every hook, newest first. Registered as a Core teardown below.
		function Hook.removeAll()
			local removed = 0
			for index = #Hook.hooks, 1, -1 do
				local entry = Hook.hooks[index]
				if entry:Remove() then
					removed += 1
				end
			end
			return removed
		end

		-- ==========================================================================
		-- Function hooks
		-- ==========================================================================

		---Hook a named global function (executor function or game function).
		---`replacement(original, ...)` returns whatever the wrapper wants to return.
		function Hook.functionHook(name, replacement)
			local target = Core.env[name]
			if type(target) ~= "function" then
				return nil, ("%s is not a function on this executor"):format(tostring(name))
			end
			if #Hook.hooks >= Hook.MAX_HOOKS then
				return nil, "too many hooks installed"
			end

			local wrapper = wrap(function(...)
				return replacement(target, ...)
			end)
			Core.env[name] = wrapper

			return record("function:" .. name, name, wrapper, function()
				Core.env[name] = target
			end)
		end

		---Hook a table's method: `table[key]`.
		function Hook.methodHook(container, key, replacement)
			if type(container) ~= "table" then
				return nil, "the container is not a table"
			end
			local target = container[key]
			if type(target) ~= "function" then
				return nil, ("%s is not a function"):format(tostring(key))
			end

			local wrapper = wrap(function(...)
				return replacement(target, ...)
			end)
			container[key] = wrapper

			return record("method:" .. tostring(key), container, wrapper, function()
				container[key] = target
			end)
		end

		-- ==========================================================================
		-- Metamethod hooks
		-- ==========================================================================

		---Hook `__namecall` (or another metamethod) on an object's metatable.
		---`replacement(original, self, ...)` keeps the namecall method available via
		---getnamecallmethod, which is why it is passed through unchanged.
		function Hook.metamethod(metamethod, replacement)
			local getRaw = Core.env.getrawmetatable
			if type(getRaw) ~= "function" then
				return nil, "this executor has no getrawmetatable()"
			end

			local metatable = getRaw(game)
			if type(metatable) ~= "table" then
				return nil, "the game's metatable is not reachable"
			end

			local original = metatable[metamethod]
			if type(original) ~= "function" then
				return nil, ("the game's metatable has no %s"):format(metamethod)
			end

			-- Writing to a locked metatable throws; unlock, write, relock. The
			-- original read-only state is remembered and restored on Remove, so the
			-- game's own protection is exactly as it was.
			local setReadOnly = Core.env.setreadonly
			local wasReadOnly = nil
			if type(Core.env.isreadonly) == "function" then
				local ok, value = pcall(Core.env.isreadonly, metatable)
				if ok then
					wasReadOnly = value
				end
			end
			if type(setReadOnly) == "function" and wasReadOnly == true then
				pcall(setReadOnly, metatable, false)
			end

			local wrapper = wrap(function(self, ...)
				return replacement(original, self, ...)
			end)
			metatable[metamethod] = wrapper

			return record("metamethod:" .. metamethod, metatable, wrapper, function()
				metatable[metamethod] = original
				if type(setReadOnly) == "function" and wasReadOnly == true then
					pcall(setReadOnly, metatable, true)
				end
			end)
		end

		-- ==========================================================================
		-- Reporting
		-- ==========================================================================

		---Rows for the tab: { label, active }.
		function Hook.report()
			local rows = {}
			for _, entry in Hook.hooks do
				table.insert(rows, { label = entry.kind, active = entry.active })
			end
			return rows
		end

		-- ==========================================================================
		-- Tab
		-- ==========================================================================

		local function mount(page)
			local section = page:Section("Hooks", 1)
			local status = Materials.Status(section.frame, "0 active", "info")
			local output = Materials.Code(section.frame, { Height = 200 })

			local function refresh()
				local rows = Hook.report()
				local lines = {}
				for index, row in rows do
					table.insert(lines, ("%d  %s"):format(index, row.label))
				end
				output:SetLines(#lines > 0 and lines or { "No hooks installed." }, 100)
				status:Set(("%d active"):format(#rows), #rows > 0 and "warn" or "info")
			end

			local target = Materials.Input(section.frame, { Text = "Global function", Default = "HttpGet" })
			Materials.Button(section.frame, {
				Text = "Log calls to it",
				OnClick = function()
					local name = target:Get()
					local link, why = Hook.functionHook(name, function(original, ...)
						Core:Log("info", ("%s(%s)"):format(name, tostring(select("#", ...))) .. " arg(s)")
						return original(...)
					end)
					if not link then
						Core:Log("warn", tostring(why))
					end
					refresh()
				end,
			})
			Materials.Button(section.frame, {
				Text = "Remove all",
				Danger = true,
				OnClick = function()
					Hook.removeAll()
					refresh()
				end,
			})

			local caps = page:Section("Capabilities", 2)
			local lines = {
				("newcclosure: %s"):format(Core.env.newcclosure ~= nil and "yes" or "no"),
				("getrawmetatable: %s"):format(Core.env.getrawmetatable ~= nil and "yes" or "no"),
				("setreadonly: %s"):format(Core.env.setreadonly ~= nil and "yes" or "no"),
				("hookfunction: %s"):format(Core.env.hookfunction ~= nil and "yes" or "no"),
				("hookmetamethod: %s"):format(Core.env.hookmetamethod ~= nil and "yes" or "no"),
			}
			Materials.Code(caps.frame, { Height = 132, Lines = table.concat(lines, "\n") })
			Materials.Label(caps.frame,
				"Metamethod hooks unlock the metatable, wrap one key, and relock it. Remove restores the original "
				.. "function and the original read-only flag.")

			refresh()
			Core:OnDestroy("vmhook", function()
				Hook.removeAll()
			end)
			return { refresh = refresh }
		end

		Hook.mount = mount

		return function(core, _signal, materials)
			Core = core
			Materials = materials
			return Hook
		end
	end)()
	Modules['FatCatVMHook'] = module
end
-- ---------------------------------------------------------------------
-- FatCatMemoryScanner.lua
-- ---------------------------------------------------------------------
do
	local module = (function()
		-- Fat Cat Project | Advanced Analysis/FatCatMemoryScanner.lua
		--
		-- Search the client's live object graph for values: strings, numbers, and
		-- booleans reachable from `getgc()`, plus Roblox instances via `getinstances()`.
		--
		--   local Scan = FatCat.require("FatCatMemoryScanner")
		--   local hits = Scan.scan(1337)                  -- number under every table key
		--   local hits = Scan.scan("aimbot", { strings = true })
		--   Scan.setPath("config/settings.lua", "fov", 120)  -- write back
		--
		-- Honest naming: this is a *graph* scanner, not a process memory scanner. It
		-- reads what Luau's GC and the instance registry expose. It cannot read
		-- arbitrary RAM, another process, or addresses the executor hides.
		--
		-- Writing back is deliberately narrow. `setPath` starts from a table you
		-- found in a scan (or a global), walks named keys, and assigns one value. It
		-- never scans for an address and pokes it, because that is the difference
		-- between a debugging tool and a crash generator.

		local Core, Materials, Scan
		Scan = {}

		Scan.MAX_RESULTS = 200

		-- ==========================================================================
		-- Value matching
		-- ==========================================================================

		local function matches(value, query, options)
			local kind = typeof(value)
			if options.strings and kind == "string" then
				if options.exact then
					return value == query
				end
				return value:find(tostring(query), 1, true) ~= nil
			end
			if options.numbers and kind == "number" then
				local target = tonumber(query)
				if not target then
					return false
				end
				if options.tolerance and options.tolerance > 0 then
					return math.abs(value - target) <= options.tolerance
				end
				return value == target
			end
			if options.booleans and kind == "boolean" then
				if type(query) == "boolean" then
					return value == query
				end
				local text = tostring(query):lower()
				return (value == true and text == "true") or (value == false and text == "false")
			end
			return false
		end

		-- ==========================================================================
		-- Graph scan
		-- ==========================================================================

		---Scan the object graph.
		---@param query any          string, number or boolean
		---@param options table|nil  { strings, numbers, booleans, tolerance, limit }
		---@return table hits        { { container, key, value, kind, path } }
		function Scan.scan(query, options)
			options = options or {}
			-- Default: infer the mode from the query, so scan("abc") searches strings
			-- and scan(120) searches numbers without extra arguments.
			if options.strings == nil and options.numbers == nil and options.booleans == nil then
				local kind = typeof(query)
				options.strings = kind == "string"
				options.numbers = kind == "number"
				options.booleans = kind == "boolean"
			end
			local limit = options.limit or Scan.MAX_RESULTS
			local hits = {}
			local seen = {}

			local getgc = Core.env.getgc
			local getinstances = Core.env.getinstances
			if type(getgc) ~= "function" and type(getinstances) ~= "function" then
				return hits, "neither getgc() nor getinstances() is available"
			end

			-- 1. Tables reachable from the GC.
			if type(getgc) == "function" then
				local ok, objects = pcall(getgc, true)
				if ok then
					for _, object in objects do
						if #hits >= limit then
							break
						end
						if type(object) == "table" and not seen[object] then
							seen[object] = true
							for key, value in object do
								if #hits >= limit then
									break
								end
								if matches(value, query, options) then
									table.insert(hits, {
										container = object,
										key = key,
										value = value,
										kind = typeof(value),
										path = ("%s.%s"):format(tostring(object), tostring(key)),
									})
								end
							end
						end
					end
				end
			end

			-- 2. Instance properties, which the GC scan does not see (they live in C).
			if type(getinstances) == "function" then
				local ok, instances = pcall(getinstances)
				if ok then
					for _, instance in instances do
						if #hits >= limit then
							break
						end
						for _, property in options.properties or { "Name", "Text", "Value", "IntValue", "StringValue" } do
							local success, value = pcall(function()
								return (instance :: any)[property]
							end)
							if success and matches(value, query, options) then
								table.insert(hits, {
									container = instance,
									key = property,
									value = value,
									kind = "Instance",
									path = ("%s.%s"):format(instance:GetFullName(), property),
								})
							end
						end
					end
				end
			end

			return hits
		end

		-- ==========================================================================
		-- Write back
		-- ==========================================================================

		---Resolve `root` then walk `path`. Returns the last table plus its key.
		function Scan.resolve(root, path)
			local keys = {}
			for piece in tostring(path):gmatch("[^/%.]+") do
				table.insert(keys, piece)
			end
			if #keys == 0 then
				return nil, nil, "empty path"
			end

			local current = root
			for index = 1, #keys - 1 do
				local key = keys[index]
				local numeric = tonumber(key)
				local nextValue = (current :: any)[numeric or key]
				if type(nextValue) ~= "table" then
					return nil, nil, ("%s is not a table"):format(key)
				end
				current = nextValue
			end
			return current, keys[#keys]
		end

		---Set one value at a slash-separated path from `root`.
		---   Scan.setPath("config/settings.lua", "aim/fov", 120)
		---`root` is a path from the globals table: "config" is `_G.config`, and
		---"config/settings.lua" walks `_G.config["settings.lua"]`.
		function Scan.setPath(rootPath, path, value)
			local keys = {}
			for piece in tostring(rootPath):gmatch("[^/%.]+") do
				table.insert(keys, piece)
			end
			local current = Core.env
			for _, key in keys do
				if type(current) ~= "table" then
					return false, ("%s is not a table"):format(key)
				end
				current = (current :: any)[key]
			end
			if type(current) ~= "table" then
				return false, ("%s did not resolve to a table"):format(rootPath)
			end

			local holder, lastKey, reason = Scan.resolve(current, path)
			if not holder then
				return false, reason
			end
			local numeric = tonumber(lastKey)
			local target = (holder :: any)
			target[numeric or lastKey] = value
			return true
		end

		---Convenience: write a value into a hit returned by scan().
		function Scan.writeHit(hit, value)
			if not hit or hit.container == nil then
				return false, "no hit"
			end
			local key = hit.key
			if typeof(hit.container) == "Instance" then
				local ok, err = pcall(function()
					(hit.container :: any)[key] = value
				end)
				if not ok then
					return false, tostring(err)
				end
				return true
			end
			(hit.container :: any)[key] = value
			return true
		end

		-- ==========================================================================
		-- Tab
		-- ==========================================================================

		local function mount(page)
			local section = page:Section("Search", 1)
			local query = Materials.Input(section.frame, { Text = "Value", Default = "0" })
			local strings = Materials.Toggle(section.frame, { Text = "Search strings", Default = true })
			local numbers = Materials.Toggle(section.frame, { Text = "Search numbers", Default = true })
			local booleans = Materials.Toggle(section.frame, { Text = "Search booleans", Default = false })
			local tolerance = Materials.Input(section.frame, { Text = "Number tolerance", Default = "0" })
			local output = Materials.Code(section.frame, { Height = 280 })
			local hits = {}

			Materials.Button(section.frame, {
				Text = "Scan",
				OnClick = function()
					local raw = query:Get()
					local numeric = tonumber(raw)
					hits = Scan.scan(numeric or raw, {
						strings = strings:Get(),
						numbers = numbers:Get() and numeric ~= nil,
						booleans = booleans:Get(),
						tolerance = tonumber(tolerance:Get()) or 0,
					})
					local lines = {}
					for index = 1, math.min(#hits, 120) do
						local hit = hits[index]
						table.insert(lines, ("%3d %s = %s"):format(index, hit.path, tostring(hit.value)))
					end
					output:SetLines(#lines > 0 and lines or { "No match. Try a tolerance for numbers." }, 300)
				end,
			})

			local writer = page:Section("Write back", 2)
			local indexField = Materials.Input(writer.frame, { Text = "Hit number", Default = "1" })
			local valueField = Materials.Input(writer.frame, { Text = "New value", Default = "" })
			Materials.Button(writer.frame, {
				Text = "Write to that hit",
				OnClick = function()
					local index = math.floor(tonumber(indexField:Get()) or 0)
					local hit = hits[index]
					if not hit then
						return
					end
					local raw = valueField:Get()
					local value = tonumber(raw)
					if value == nil then
						if raw == "true" then
							value = true
						elseif raw == "false" then
							value = false
						else
							value = raw
						end
					end
					Scan.writeHit(hit, value)
				end,
			})
			Materials.Label(writer.frame,
				"Only values that live in a Luau table or on an instance property can be written. "
				.. "Values inside the engine's C++ structures are read-only from here.")

			return { scan = Scan.scan, hits = function()
				return hits
			end }
		end

		Scan.mount = mount

		return function(core, materials)
			Core = core
			Materials = materials
			return Scan
		end
	end)()
	Modules['FatCatMemoryScanner'] = module
end
-- ---------------------------------------------------------------------
-- FatCatEnvSpoofer.lua
-- ---------------------------------------------------------------------
do
	local module = (function()
		-- Fat Cat Project | Advanced Analysis/FatCatEnvSpoofer.lua
		--
		-- What the executor reports about itself, and a place to change the parts that
		-- are safe to change: the identity handed to identifyexecutor, the global
		-- environment other scripts see, and the properties of a client-side instance.
		--
		--   local E = FatCat.require("FatCatEnvSpoofer")
		--   E.spoofIdentity("Solara")      -- identifyexecutor() now answers "Solara"
		--   E.restore()
		--
		-- ==========================================================================
		-- What this deliberately does not do
		-- ==========================================================================
		-- A "spoofer" in the wild means faking your identity to a game's anti-cheat,
		-- faking your platform, or lying about your request headers. That is a
		-- detection-evasion tool, and building one into this project would:
		--
		--   * break the first time the game checks a third signal (ping, HWID, join
		--     time), which is why public spoofers are always "detected again";
		--   * get users banned for something that never actually worked;
		--   * make every other diagnostic in this project untrustworthy, because the
		--     thing reporting the environment would be the thing lying about it.
		--
		-- So this module spoofs only what is a display or a debugging concern:
		--
		--   * `identifyexecutor` — so screenshots and bug reports can be anonymised;
		--   * a sandboxed `getgenv()` for a script you run from the console;
		--   * instance properties that are visual (a BillboardGui's text, a name).
		--
		-- Every change is reversible and registered with Core, and `restore()` puts
		-- the environment back exactly as it was.

		local Core, Materials, Env
		Env = {}

		local saved = {}          -- name -> original function
		local restores = {}       -- list of functions
		local active = {}

		local function remember(label, restore)
			table.insert(restores, { label = label, run = restore })
			active[label] = true
		end

		---True when anything is currently spoofed.
		function Env.isActive()
			for _ in active do
				return true
			end
			return false
		end

		---Labels of what is currently spoofed.
		function Env.listing()
			local labels = {}
			for label in active do
				table.insert(labels, label)
			end
			table.sort(labels)
			return labels
		end

		-- ==========================================================================
		-- Identity
		-- ==========================================================================

		---Make identifyexecutor() answer `name` until restore().
		---This is a display change: nothing in the game's detection path calls
		---identifyexecutor, so it cannot protect anybody from anything.
		function Env.spoofIdentity(name)
			name = tostring(name or "FatCat")
			local original = Core.env.identifyexecutor
			if type(original) ~= "function" then
				return false, "this executor has no identifyexecutor() to spoof"
			end
			if saved.identifyexecutor then
				return false, "identity is already spoofed; restore() first"
			end

			saved.identifyexecutor = original
			Core.env.identifyexecutor = function()
				return name
			end
			Core.state.executor = name
			remember("identity", function()
				Core.env.identifyexecutor = original
			end)
			return true, name
		end

		-- ==========================================================================
		-- Environment sandbox
		-- ==========================================================================

		---Return a shallow copy of the executor environment with `overrides` applied.
		---A script launched from the console can be given this table instead of the
		---real one, so a global it sets does not leak into the game or the executor.
		function Env.sandbox(overrides)
			local source = Core.env
			local copy = {}
			for key, value in source do
				copy[key] = value
			end
			for key, value in overrides or {} do
				copy[key] = value
			end
			return copy
		end

		---True when this environment can actually run something in a sandbox.
		---`setfenv` existing is not enough: some executor layers expose one that
		---ignores a native chunk and still reports success, which would make
		---"sandboxed" a lie. The capability is *proven* once with a one-line probe and
		---cached, because the answer cannot change during a session.
		function Env.canSandbox()
			if Env._canSandbox ~= nil then
				return Env._canSandbox
			end
			local setfenv = Core.env.setfenv
			local loadstring = Core.env.loadstring
			if type(setfenv) ~= "function" or type(loadstring) ~= "function" then
				Env._canSandbox = false
				return false
			end
			local chunk = loadstring("return sandboxProbe")
			if type(chunk) ~= "function" then
				Env._canSandbox = false
				return false
			end
			local marker = { sandboxProbe = true }
			if not pcall(setfenv, chunk, marker) then
				Env._canSandbox = false
				return false
			end
			local ok, result = pcall(chunk)
			-- The probe must *see* the marker. Reading the real globals instead means
			-- the chunk was never rebound.
			Env._canSandbox = ok and result == true
			return Env._canSandbox
		end

		---Run `chunk` with `env` as its global table.
		---Returns ok, result. Refuses, rather than silently running unsandboxed, when
		---the environment cannot rebind a chunk.
		function Env.runSandboxed(chunk, env)
			if type(chunk) ~= "function" then
				return false, "not a function"
			end
			if not Env.canSandbox() then
				return false, "this environment cannot rebind a chunk (setfenv is absent or inert)"
			end
			local target = env or Env.sandbox()
			local ok, err = pcall(Core.env.setfenv, chunk, target)
			if not ok then
				return false, tostring(err)
			end
			local success, result = pcall(chunk)
			return success, result
		end

		-- ==========================================================================
		-- Instance properties
		-- ==========================================================================

		---Set a property on a client-side instance, remembering the old value so
		---restore() can put it back. Refuses server-owned objects.
		function Env.spoofProperty(instance, property, value)
			if typeof(instance) ~= "Instance" then
				return false, "not an instance"
			end
			local ok, current = pcall(function()
				return (instance :: any)[property]
			end)
			if not ok then
				return false, ("%s has no property %s"):format(instance.ClassName, tostring(property))
			end
			local okWrite, err = pcall(function()
				(instance :: any)[property] = value
			end)
			if not okWrite then
				-- The usual cause: the instance is replicated. Say so instead of
				-- leaving the user wondering why nothing happened.
				return false, ("the engine refused the write (%s); this object is probably server-owned"):format(
					tostring(err))
			end
			remember("property", function()
				pcall(function()
					(instance :: any)[property] = current
				end)
			end)
			return true, current
		end

		-- ==========================================================================
		-- Restore
		-- ==========================================================================

		---Undo every spoof, newest first.
		function Env.restore()
			local count = 0
			for index = #restores, 1, -1 do
				local entry = restores[index]
				local ok = pcall(entry.run)
				if ok then
					count += 1
				end
			end
			table.clear(restores)
			table.clear(active)
			table.clear(saved)
			-- Re-detect, since identifyexecutor may be back to its real answer.
			local runtime = Core.modules["FatCatEnv"]
			if runtime and type(runtime.detect) == "function" then
				pcall(runtime.detect)
			end
			return count
		end

		-- ==========================================================================
		-- Tab
		-- ==========================================================================

		local function mount(page)
			local section = page:Section("Identity", 1)
			local status = Materials.Status(section.frame, Env.isActive() and "active" or "clean", "info")
			local name = Materials.Input(section.frame, { Text = "Reported name", Default = "FatCat" })

			Materials.Button(section.frame, {
				Text = "Spoof identifyexecutor",
				OnClick = function()
					local ok, result = Env.spoofIdentity(name:Get())
					status:Set(ok and ("reporting " .. tostring(result)) or tostring(result), ok and "warn" or "off")
				end,
			})
			Materials.Button(section.frame, {
				Text = "Restore everything",
				Danger = true,
				OnClick = function()
					Env.restore()
					status:Set("clean", "on")
				end,
			})
			Materials.Label(section.frame,
				"This changes only what identifyexecutor reports. It does not hide the executor from a game's "
				.. "anti-cheat, and nothing here should be presented as if it did.")

			local caps = page:Section("What the executor exposes", 2)
			local lines = {}
			for _, entry in Core.modules["FatCatEnv"] and (Core.modules["FatCatEnv"]).CAPABILITIES or {} do
				if type(Core.env[entry]) == "function" then
					table.insert(lines, entry)
				end
			end
			Materials.Code(caps.frame, { Height = 260, Lines = table.concat(lines, "\n") })
			Materials.Label(caps.frame,
				"Sandboxed runs use a copy of this environment, so a script's globals do not leak into the game.")

			Core:OnDestroy("envspoofer", Env.restore)
			return { restore = Env.restore }
		end

		Env.mount = mount

		return function(core, materials)
			Core = core
			Materials = materials
			return Env
		end
	end)()
	Modules['FatCatEnvSpoofer'] = module
end
-- ---------------------------------------------------------------------
-- FatCatUniversal.lua
-- ---------------------------------------------------------------------
do
	local module = (function()
		-- Fat Cat Project | Utilities, Console & Math/FatCatUniversal.lua
		--
		-- The movement/visual utilities that work in any game: ESP, fly, noclip,
		-- fullbright, walk speed, jump power, teleport. "Universal" means exactly
		-- that: nothing here reads a game-specific remote or offset.
		--
		--   local U = FatCat.require("FatCatUniversal")
		--   U.esp(true)                  -- boxes + names on every player
		--   U.fly(true)                  -- free camera-relative flight
		--   U.noclip(true)               -- through walls, until turned off
		--   U.unload()                   -- restore walkspeed/jump/camera, drop ESP
		--
		-- Every feature here is reversible and registers its own restore with Core,
		-- so `FatCatEnv.unload()` puts the character back the way it was: a script
		-- that leaves a player at walkspeed 500 after "unloading" is worse than one
		-- that never ran.
		--
		-- What this module deliberately does NOT do:
		--   * no anti-cheat evasion, no detection-string removal, no hooking;
		--   * no per-game exploits (that is what the analysis modules are for);
		--   * nothing that writes to another player's character.
		-- If a game forbids what these do, that is a server rule, not a technical
		-- problem this file can solve.

		local Core, Design, U
		U = {}

		local player = game:GetService("Players").LocalPlayer
		local runService = game:GetService("RunService")
		local userInput = game:GetService("UserInputService")

		-- Original values, captured the first time a feature changes them.
		local originals = {
			walkSpeed = nil,
			jumpPower = nil,
			jumpHeight = nil,
			hipHeight = nil,
			gravity = nil,
			lighting = nil,
		}
		local espFolder = nil
		local espCache = {}
		local flyState = nil
		local noclipOn = false

		local function character()
			local char = player and player.Character
			if not char then
				return nil
			end
			local humanoid = char:FindFirstChildOfClass("Humanoid")
			if not humanoid then
				return nil
			end
			return char, humanoid
		end

		local function rootPart(char)
			if not char then
				return nil
			end
			return char:FindFirstChild("HumanoidRootPart") or char.PrimaryPart
		end

		-- ==========================================================================
		-- Walk speed / jump
		-- ==========================================================================

		---Set walkspeed, remembering the original once so unload can restore it.
		function U.walkSpeed(speed)
			local _, humanoid = character()
			if not humanoid then
				return false, "no character yet"
			end
			speed = math.clamp(tonumber(speed) or 16, 0, 1000)
			if originals.walkSpeed == nil then
				originals.walkSpeed = humanoid.WalkSpeed
				Core:OnDestroy("universal:walkSpeed", function()
					if humanoid.Parent then
						humanoid.WalkSpeed = originals.walkSpeed
					end
				end)
			end
			humanoid.WalkSpeed = speed
			return true, speed
		end

		---Set jump power (classic) or jump height (newer games), whichever the
		---humanoid is configured to use.
		function U.jumpPower(power)
			local _, humanoid = character()
			if not humanoid then
				return false, "no character yet"
			end
			power = math.clamp(tonumber(power) or 50, 0, 1000)
			if humanoid.UseJumpPower then
				if originals.jumpPower == nil then
					originals.jumpPower = humanoid.JumpPower
					Core:OnDestroy("universal:jumpPower", function()
						if humanoid.Parent then
							humanoid.JumpPower = originals.jumpPower
						end
					end)
				end
				humanoid.JumpPower = power
			else
				if originals.jumpHeight == nil then
					originals.jumpHeight = humanoid.JumpHeight
					Core:OnDestroy("universal:jumpHeight", function()
						if humanoid.Parent then
							humanoid.JumpHeight = originals.jumpHeight
						end
					end)
				end
				humanoid.JumpHeight = power
			end
			return true, power
		end

		-- ==========================================================================
		-- Noclip
		-- ==========================================================================
		-- Noclip works by clearing CanCollide on every BasePart of the character each
		-- frame. The alternative (writing to the part's `CanCollide` only once) fails
		-- because the character controller re-enables collision on respawn and on
		-- every state change, so this has to be a per-frame pass.
		local noclipConnection = nil

		function U.noclip(on)
			on = on and true or false
			if on == noclipOn then
				return true, on
			end
			noclipOn = on

			if on then
				local link = runService.Stepped:Connect(function()
					local char = character()
					if not char then
						return
					end
					for _, part in char:GetDescendants() do
						if part:IsA("BasePart") then
							part.CanCollide = false
						end
					end
				end)
				noclipConnection = link
				Core:OnDestroy("universal:noclip", function()
					if link then
						link:Disconnect()
					end
					noclipOn = false
				end)
			else
				if noclipConnection then
					noclipConnection:Disconnect()
					noclipConnection = nil
				end
				local char = character()
				if char then
					for _, part in char:GetDescendants() do
						if part:IsA("BasePart") and part.Name ~= "HumanoidRootPart" then
							part.CanCollide = true
						end
					end
				end
			end
			return true, on
		end

		-- ==========================================================================
		-- Fly
		-- ==========================================================================
		-- Free flight: a BodyVelocity on the root part, driven toward the movement
		-- vector the player is holding, with Space/Ctrl for vertical. The camera is
		-- left alone; the character follows the camera's yaw.
		--
		-- Turning it off removes the velocity, restores PlatformStand (some games
		-- freeze you in the air with it on), and gives the character a moment of
		-- zero gravity so it falls instead of hovering.

		function U.fly(on, speed)
			on = on and true or false
			speed = tonumber(speed) or 60

			if not on then
				if flyState then
					if flyState.velocity then
						flyState.velocity:Destroy()
					end
					if flyState.connection then
						flyState.connection:Disconnect()
					end
					local _, humanoid = character()
					if humanoid then
						humanoid.PlatformStand = false
					end
					flyState = nil
				end
				return true, false
			end

			if flyState then
				-- Already flying: change the speed without rebuilding the body mover.
				flyState.speed = speed
				return true, true
			end

			local char, humanoid = character()
			local root = rootPart(char)
			if not (root and humanoid) then
				return false, "no character yet"
			end

			humanoid.PlatformStand = true
			local body = Instance.new("BodyVelocity")
			body.Name = "FatCatFly"
			body.Velocity = Vector3.zero
			body.MaxForce = Vector3.new(1e5, 1e5, 1e5)
			body.Parent = root

			local state = { velocity = body, speed = speed, connection = nil }
			flyState = state

			state.connection = runService.RenderStepped:Connect(function()
				local currentChar = player and player.Character
				local currentRoot = currentChar and currentChar:FindFirstChild("HumanoidRootPart")
				if not currentRoot or not body.Parent then
					return
				end

				local camera = workspace.CurrentCamera
				local direction = Vector3.zero
				if userInput:IsKeyDown(Enum.KeyCode.W) then
					direction += camera.CFrame.LookVector
				end
				if userInput:IsKeyDown(Enum.KeyCode.S) then
					direction -= camera.CFrame.LookVector
				end
				if userInput:IsKeyDown(Enum.KeyCode.D) then
					direction += camera.CFrame.RightVector
				end
				if userInput:IsKeyDown(Enum.KeyCode.A) then
					direction -= camera.CFrame.RightVector
				end
				if userInput:IsKeyDown(Enum.KeyCode.Space) then
					direction += Vector3.yAxis
				end
				if userInput:IsKeyDown(Enum.KeyCode.LeftControl) then
					direction -= Vector3.yAxis
				end

				if direction.Magnitude > 0 then
					body.Velocity = direction.Unit * state.speed
				else
					body.Velocity = Vector3.zero
				end
			end)

			Core:OnDestroy("universal:fly", function()
				if state.velocity then
					state.velocity:Destroy()
				end
				if state.connection then
					state.connection:Disconnect()
				end
				local _, currentHumanoid = character()
				if currentHumanoid then
					currentHumanoid.PlatformStand = false
				end
			end)
			return true, true
		end

		-- ==========================================================================
		-- ESP
		-- ==========================================================================
		-- One BillboardGui per player, parented to a folder in CoreGui so a single
		-- Destroy removes the whole thing. Boxes use the model's bounding box, so a
		-- crouching player gets a shorter box without any extra code.

		local function coreGui()
			local ok, container = pcall(function()
				return game:GetService("CoreGui")
			end)
			return ok and container or nil
		end

		local function clearEsp()
			if espFolder then
				espFolder:Destroy()
				espFolder = nil
			end
			table.clear(espCache)
		end

		local function styleFor(player)
			-- Colour by team when the game has teams; otherwise one accent. This is
			-- the one place a colour is hardcoded, and it is the palette's accent.
			local color = Design.color("accent")
			local success, teamColor = pcall(function()
				return player.TeamColor.Color
			end)
			if success and teamColor then
				color = teamColor
			end
			return color
		end

		local function addHighlight(target)
			if espCache[target] then
				return
			end
			local highlight = Instance.new("Highlight")
			highlight.Name = "FatCatESP"
			highlight.FillColor = styleFor(target)
			highlight.OutlineColor = Color3.new(1, 1, 1)
			highlight.FillTransparency = 0.72
			highlight.OutlineTransparency = 0.25
			highlight.Adornee = target.Character
			highlight.Parent = espFolder
			espCache[target] = highlight
		end

		local function refreshEsp()
			if not espFolder then
				return
			end
			local ok, players = pcall(function()
				return game:GetService("Players"):GetPlayers()
			end)
			if not ok or type(players) ~= "table" then
				return
			end
			for _, other in players do
				if other == player then
					continue
				end
				if other.Character then
					addHighlight(other)
				elseif espCache[other] then
					espCache[other]:Destroy()
					espCache[other] = nil
				end
			end
		end

		function U.esp(on)
			on = on and true or false
			if not on then
				clearEsp()
				return true, false
			end

			local container = coreGui()
			if not container then
				return false, "CoreGui is not accessible on this executor"
			end

			clearEsp()
			local folder = Instance.new("Folder")
			folder.Name = "FatCatESP"
			folder.Parent = container
			espFolder = folder

			refreshEsp()

			local join = game:GetService("Players").PlayerAdded:Connect(function()
				refreshEsp()
			end)
			local leave = game:GetService("Players").PlayerRemoving:Connect(function(other)
				if espCache[other] then
					espCache[other]:Destroy()
					espCache[other] = nil
				end
			end)

			Core:OnDestroy("universal:esp", function()
				join:Disconnect()
				leave:Disconnect()
				clearEsp()
			end)
			return true, true
		end

		-- ==========================================================================
		-- Lighting and teleport
		-- ==========================================================================

		---Fullbright: remove ambient occlusion and fog so a dark map is readable.
		---Restores the exact original Lighting properties on unload.
		function U.fullbright(on)
			local lighting = game:GetService("Lighting")
			if originals.lighting == nil then
				originals.lighting = {
					Ambient = lighting.Ambient,
					OutdoorAmbient = lighting.OutdoorAmbient,
					FogEnd = lighting.FogEnd,
					Brightness = lighting.Brightness,
					ClockTime = lighting.ClockTime,
				}
				Core:OnDestroy("universal:lighting", function()
					local saved = originals.lighting
					if saved then
						lighting.Ambient = saved.Ambient
						lighting.OutdoorAmbient = saved.OutdoorAmbient
						lighting.FogEnd = saved.FogEnd
						lighting.Brightness = saved.Brightness
						lighting.ClockTime = saved.ClockTime
					end
				end)
			end

			if on then
				lighting.Ambient = Color3.new(1, 1, 1)
				lighting.OutdoorAmbient = Color3.new(1, 1, 1)
				lighting.Brightness = 2
				lighting.FogEnd = 1e6
				lighting.ClockTime = 14
			else
				local saved = originals.lighting
				lighting.Ambient = saved.Ambient
				lighting.OutdoorAmbient = saved.OutdoorAmbient
				lighting.Brightness = saved.Brightness
				lighting.FogEnd = saved.FogEnd
				lighting.ClockTime = saved.ClockTime
			end
			return true, on
		end

		---Move the character to a position. Returns false with a reason when there is
		---no character; a nil Y keeps the current height.
		function U.teleport(position)
			local char = character()
			local root = rootPart(char)
			if not root or not position then
				return false, "no character yet"
			end
			local target = Vector3.new(position.X, position.Y or root.Position.Y, position.Z)
			root.CFrame = CFrame.new(target)
			return true, target
		end

		---Teleport to another player, offset so the two do not overlap.
		function U.teleportToPlayer(name)
			local players = game:GetService("Players")
			local found = players:FindFirstChild(name)
			if not found then
				return false, ("no player named '%s'"):format(tostring(name))
			end
			local char = found.Character
			local root = rootPart(char)
			if not root then
				return false, "that player has no character"
			end
			return U.teleport(root.Position + Vector3.new(0, 0, 3))
		end

		---Recharge the humanoid's health. Works on client-side humanoids only, which
		---is the only place a client script can write to.
		function U.heal()
			local _, humanoid = character()
			if not humanoid then
				return false, "no character yet"
			end
			humanoid.Health = humanoid.MaxHealth
			return true, humanoid.Health
		end

		---Take the camera off the character (free cam) or give it back.
		function U.freeCam(on)
			local camera = workspace.CurrentCamera
			if not camera then
				return false, "no camera"
			end
			if on then
				camera.CameraType = Enum.CameraType.Scriptable
			else
				camera.CameraType = Enum.CameraType.Custom
			end
			return true, camera.CameraType
		end

		---Restore everything this module touched. Called by FatCatEnv.unload via the
		---teardowns registered above, but exposed so the Utilities tab can offer it.
		function U.restore()
			U.fly(false)
			U.noclip(false)
			U.esp(false)
		end

		return function(core, design, _signal, _mathModule)
			Core = core
			Design = design
			return U
		end
	end)()
	Modules['FatCatUniversal'] = module
end
-- ---------------------------------------------------------------------
-- FatCatConsole.lua
-- ---------------------------------------------------------------------
do
	local module = (function()
		-- Fat Cat Project | Utilities, Console & Math/FatCatConsole.lua
		--
		-- The floating terminal: a log, a filter, and a place to run one-liners
		-- without leaving the menu.
		--
		--   local Console = FatCat.require("FatCatConsole")
		--   Console.write("info", "spy started")     -- also feeds Core.logSink
		--   Console.log                              -- array of entries
		--   Console.run("return 1 + 1")              -- 2
		--   Console.errorsOnly()                      -- filter
		--
		-- Why a console matters here: every other module in this project talks to the
		-- executor, and the executor's own console is usually hidden behind the game
		-- or shared with every other script in the session. When the spy hooks a
		-- hundred remotes, the only place to see a hook fail is here.
		--
		-- The runner is deliberately narrow. It compiles with `loadstring`, runs in a
		-- sandboxed environment by default (see FatCatEnv.sandbox), and prints
		-- nothing it was not asked to. `Console.run` never lets a thrown error reach
		-- the menu: the error text becomes a log entry, which is the whole point.

		local Core, Signal, Materials, Console
		Console = {}

		Console.MAX_ENTRIES = 400
		Console.log = {}
		Console.filter = nil       -- nil | "error" | "warn" | "info" | "debug"
		Console.subscribers = {}

		local changed = nil

		-- ==========================================================================
		-- Log
		-- ==========================================================================

		local function levelAllowed(level)
			if not Console.filter then
				return true
			end
			-- "error" and "warn" are always shown, even under a floor: hiding a
			-- failure behind a filter is how a broken module goes unnoticed.
			if level == "error" or level == "warn" then
				return true
			end
			return level == Console.filter
		end

		local function notify(entry)
			if changed then
				changed:Fire(entry)
			end
			for index = #Console.subscribers, 1, -1 do
				local handler = Console.subscribers[index]
				local ok = pcall(handler, entry)
				if not ok then
					table.remove(Console.subscribers, index)
				end
			end
		end

		---Append one entry. `level` is error | warn | info | debug.
		function Console.write(level, message, ...)
			local text = tostring(message)
			local extra = select("#", ...)
			if extra > 0 then
				local parts = {}
				for index = 1, extra do
					parts[index] = tostring((select(index, ...)))
				end
				text = text .. " " .. table.concat(parts, " ")
			end

			local entry = {
				level = level or "info",
				text = text,
				time = os.clock(),
				clock = ("%02d:%02d:%02d"):format(
					math.floor(os.clock() / 3600) % 24,
					math.floor(os.clock() / 60) % 60,
					math.floor(os.clock()) % 60),
			}
			table.insert(Console.log, entry)
			while #Console.log > Console.MAX_ENTRIES do
				table.remove(Console.log, 1)
			end
			notify(entry)
			return entry
		end

		---Subscribe to new entries; returns an unsubscribe function.
		function Console.subscribe(handler)
			table.insert(Console.subscribers, handler)
			return function()
				for index = #Console.subscribers, 1, -1 do
					if Console.subscribers[index] == handler then
						table.remove(Console.subscribers, index)
					end
				end
			end
		end

		---The text the code view shows, honouring the active filter.
		function Console.format()
			local lines = {}
			for _, entry in Console.log do
				if levelAllowed(entry.level) then
					table.insert(lines, ("%s %-5s %s"):format(entry.clock, entry.level:upper(), entry.text))
				end
			end
			return lines
		end

		function Console.setFilter(level)
			Console.filter = level
		end

		function Console.clear()
			table.clear(Console.log)
		end

		---Count entries per level, for the tab badges.
		function Console.counts()
			local counts = { error = 0, warn = 0, info = 0, debug = 0 }
			for _, entry in Console.log do
				counts[entry.level] = (counts[entry.level] or 0) + 1
			end
			return counts
		end

		-- ==========================================================================
		-- Runner
		-- ==========================================================================

		local function compile(source, chunkName)
			local loadstring = Core.env.loadstring
			if type(loadstring) ~= "function" then
				return nil, "this executor has no loadstring()"
			end
			local chunk, err = loadstring(source, chunkName or "=fatcat-console")
			if not chunk then
				return nil, tostring(err)
			end
			return chunk
		end

		---Run one line of Luau. Sandboxed by default: globals the line sets do not
		---escape into the game. Pass { sandbox = false } to run in the real env.
		---Returns ok, results (packed), or ok=false, error text.
		function Console.run(source, options)
			options = options or {}
			if type(source) ~= "string" or source == "" then
				return false, "nothing to run"
			end

			local chunk, compileError = compile(source, options.chunkName)
			if not chunk then
				Console.write("error", "compile: " .. tostring(compileError))
				return false, compileError
			end

			-- A copy of the executor environment by default: a global the snippet sets
			-- lands in the copy, not in the game. Whether that is possible is *proven*
			-- once by FatCatEnv.canSandbox (a setfenv that exists and does nothing is a
			-- real thing, and "sandboxed" must not be a claim). When it is not
			-- possible the snippet runs in the real environment and the log says so.
			if options.sandbox ~= false then
				local EnvModule = Core:TryRequire("FatCatEnvSpoofer")
				if EnvModule and type(EnvModule.canSandbox) == "function" and EnvModule.canSandbox() then
					pcall(Core.env.setfenv, chunk, EnvModule.sandbox())
				else
					Console.write("warn", "este entorno no puede aislar un chunk; el snippet corre en el real")
				end
			end

			local results = table.pack(pcall(chunk))
			local ok = results[1]
			if not ok then
				Console.write("error", tostring(results[2]))
				return false, tostring(results[2])
			end
			table.remove(results, 1)
			if results.n > 0 then
				local parts = {}
				for index = 1, results.n do
					parts[index] = tostring(results[index])
				end
				Console.write("info", "→ " .. table.concat(parts, ", "))
			end
			return true, results
		end

		---Compile only, for the "check syntax" button.
		function Console.check(source)
			local chunk, err = compile(source)
			if not chunk then
				return false, err
			end
			return true
		end

		-- ==========================================================================
		-- Tab
		-- ==========================================================================

		local function mount(page)
			local section = page:Section("Log", 1)
			local status = Materials.Status(section.frame, "0 entries", "info")
			local output = Materials.Code(section.frame, { Height = 300 })

			local function repaint()
				output:SetLines(Console.format(), Console.MAX_ENTRIES)
				output:ScrollToBottom()
				local counts = Console.counts()
				status:Set(("%d entry(s) · %d error(s) · %d warning(s)"):format(
					#Console.log, counts.error, counts.warn),
					counts.error > 0 and "off" or (counts.warn > 0 and "warn" or "info"))
			end

			Materials.Button(section.frame, {
				Text = "Show all",
				OnClick = function()
					Console.setFilter(nil)
					repaint()
				end,
			})
			Materials.Button(section.frame, {
				Text = "Errors and warnings only",
				OnClick = function()
					Console.setFilter("warn")
					repaint()
				end,
			})
			Materials.Button(section.frame, {
				Text = "Clear",
				OnClick = function()
					Console.clear()
					repaint()
				end,
			})

			local runner = page:Section("Run Luau", 2)
			Materials.Label(runner.frame,
				"Runs in a copy of the executor environment, so a global it sets does not leak. "
				.. "Errors are logged here instead of breaking the menu.")
			local sourceField = Materials.Input(runner.frame, {
				Text = "Code",
				Placeholder = "return 1 + 1",
			})
			local runStatus = Materials.Status(runner.frame, "idle", "info")
			Materials.Button(runner.frame, {
				Text = "Run",
				OnClick = function()
					local ok, results = Console.run(sourceField:Get())
					if ok then
						runStatus:Set("ran without errors", "on")
					else
						runStatus:Set(tostring(results), "off")
					end
					repaint()
				end,
			})
			Materials.Button(runner.frame, {
				Text = "Check syntax",
				OnClick = function()
					local ok, err = Console.check(sourceField:Get())
					runStatus:Set(ok and "syntax is valid" or tostring(err), ok and "on" or "off")
				end,
			})

			-- Live feed: every module that logs lands here without polling.
			Console.subscribe(function()
				repaint()
			end)
			repaint()

			Core:OnDestroy("console:ui", function()
				Console.subscribers = {}
			end)
			return { repaint = repaint }
		end

		Console.mount = mount

		---Install Console as the Core log sink, so Core:Log() shows up here.
		---FatCatInit calls this once, after the module loads.
		function Console.attach()
			Core:SetLogger(function(level, message, ...)
				Console.write(level, message, ...)
			end)
			Signal.errorHandler = function(name, message)
				Console.write("error", ("signal %s: %s"):format(tostring(name), tostring(message)))
			end
			-- Anything the shell warns about is worth seeing next to our own lines.
			return true
		end

		return function(core, signal, materials)
			Core = core
			Signal = signal
			Materials = materials
			changed = Signal.new("console:entry")
			return Console
		end
	end)()
	Modules['FatCatConsole'] = module
end
-- ---------------------------------------------------------------------
-- FatCatMenu.lua
-- ---------------------------------------------------------------------
do
	local module = (function()
		-- Fat Cat Project | UI & Styling Engine/FatCatMenu.lua
		--
		-- The container: it owns the tab layout, wires every feature module into it,
		-- and makes the project and the shell behave like one application.
		--
		-- The window is NOT reimplemented here. src/FatCatHub.lua already owns drag,
		-- resize, tabs, search, toasts and teardown, and it is the part the 94
		-- harness asserts exercise. This module builds on top of it through
		-- Hub:Mount, which means a rebuild (resolution change, tab added later,
		-- reload) reruns the same builder and nothing is lost.
		--
		--   local Menu = FatCat.require("FatCatMenu")
		--   Menu.build()             -- register the tab layout, idempotent
		--   Menu.tab("Console")
		--   Menu.setTheme("glacier")
		--
		-- Two rules this file exists to enforce:
		--
		--   1. Tabs are added with Hub._window:AddTab, one at a time. The tab bar
		--      divides its width by tab count and the underline recalculates on each
		--      add, so passing a list to Init would leave the indicator wrong.
		--
		--   2. Every control carries a `Flag`. The shell stores each flag's value in
		--      Hub.Values and its setter in Hub.Setters, and FatCatConfig saves that
		--      exact table - so one preset covers the whole menu for free.
		--
		-- Tab budget: the window opens at 460 px and the tab bar spends 12 px on its
		-- margins, so seven tabs get 64 px each. The widest name here measures 54 px
		-- at 13 px Gotham (measured, not guessed); an eighth tab would drop the slot
		-- to 56 px and "Settings" would start to crowd its neighbour. A second tool on
		-- the same page goes in a section, not in a new tab.

		local Core, Design, Menu
		Menu = {}

		-- name -> module path. Order is the tab order left to right.
		Menu.TABS = {
			{ "Home", nil },
			{ "Create", "FatCatCreate" },
			{ "Inspect", "FatCatInspect" },
			{ "Scripts", "FatCatDecompiler" },
			{ "Exploit", "FatCatExtractor" },
			{ "Network", "FatCatSpy" },
			{ "Settings", nil },
		}

		local built = false

		local function shell()
			return _G.FatCatHub
		end

		---True when the shell finished loading and has a window.
		function Menu.ready()
			local base = shell()
			return base ~= nil and base._window ~= nil
		end

		local function pageFor(window, name)
			local existing = window.pages[name]
			if existing then
				return existing
			end
			return window:AddTab(name)
		end

		-- ==========================================================================
		-- Home
		-- ==========================================================================

		local function buildHome(window)
			local page = pageFor(window, "Home")

			local status = page:Section("Estado", 1)
			local Env = Core:TryRequire("FatCatEnv")
			status:Status("Fat Cat Project", "on")
			status:Status(("Ejecutor: %s"):format(Env and Env.name or "desconocido"), Env and "on" or "warn")
			status:Status(("%d módulos cargados"):format(#Core.loadOrder), "info")
			if Env then
				for _, row in Env.summary() do
					status:Status(("Capacidades · %s"):format(row.label), row.ok and "on" or (row.partial and "warn" or "off"))
				end
			end

			-- The Unload button is the one control that must always be reachable, so
			-- it lives on Home as well as in Settings: a broken tab is exactly when a
			-- user needs it.
			status:Button({
				Text = "Descargar Fat Cat",
				Callback = function()
					local runtime = Core:TryRequire("FatCatEnv")
					if runtime then
						runtime.unload()
					else
						Menu.notify("No se pudo descargar", "error", "FatCatEnv no cargó")
					end
				end,
			})

			local look = page:Section("Apariencia", 2)
			look:Cycle({
				Text = "Paleta",
				Options = Design.order,
				Default = Design.current,
				Flag = "ui.palette",
				Callback = function(choice)
					Menu.setTheme(choice)
				end,
			})
			look:Toggle({
				Text = "Movimiento reducido",
				Default = false,
				Flag = "ui.reducedMotion",
				Description = "Todas las animaciones pasan a ser instantáneas",
				Callback = function(on)
					Design.setReducedMotion(on)
				end,
			})
			look:Keybind({
				Text = "Abrir menú",
				Default = "RightShift",
				Flag = "ui.menuKey",
				Callback = function(key)
					local base = shell()
					if base then
						base.menuKey = key
					end
				end,
			})
			local contrast, where = Design.auditContrast()
			look:Label(("Contraste mínimo de la paleta: %.1f:1 (%s)"):format(contrast, where))

			local fails = page:Section("Diagnóstico", 1)
			local failures = {}
			for name in Core.loadErrors or {} do
				table.insert(failures, name)
			end
			table.sort(failures)
			if #failures == 0 then
				fails:Status("Ningún módulo falló al cargar", "on")
			else
				for _, name in failures do
					fails:Status(("Falló: %s"):format(name), "off")
				end
			end
			if Env and type(Env.report) == "function" then
				fails:Button({
					Text = "Imprimir informe en la consola",
					Callback = function()
						Env.report()
					end,
				})
			end
		end

		-- ==========================================================================
		-- Settings
		-- ==========================================================================

		local function buildSettings(window)
			local page = pageFor(window, "Settings")
			local service = page:Section("Presets", 1)
			local Config = Core:TryRequire("FatCatConfig")

			if not Config then
				service:Label("FatCatConfig no se pudo cargar.")
			elseif not Config:Available() then
				service:Label("Guardar presets necesita writefile/readfile. " .. Config:UnavailableReason())
			else
				local names = Config:List()
				service:Label(("%d preset(s) en %s"):format(#names, Config.PRESET_DIR))
				if #names > 0 then
					service:Dropdown({
						Text = "Preset",
						Options = names,
						Default = Config:Active() or names[1],
						Flag = "ui.presetName",
					})
				end
				service:Button({
					Text = "Guardar valores actuales",
					Callback = function()
						local base = shell()
						local name = (base and base.Values and base.Values["ui.presetName"]) or "default"
						local ok, countOrReason = Config:SavePreset(name, (base and base.Values) or {})
						Menu.notify(ok and "Preset guardado" or "No se pudo guardar",
							ok and "success" or "error",
							ok and ("%s · %d valor(es)"):format(name, countOrReason) or tostring(countOrReason))
					end,
				})
				service:Button({
					Text = "Cargar preset",
					Callback = function()
						local base = shell()
						local name = (base and base.Values and base.Values["ui.presetName"]) or (names[1] or "default")
						local values, why = Config:LoadPreset(name)
						if not values then
							Menu.notify("No se pudo cargar", "error", tostring(why))
							return
						end
						-- Setters live on the shell; a preset written by an older build
						-- can name a flag that no longer exists, so each one is skipped
						-- individually instead of aborting the whole load.
						local applied, skipped = 0, 0
						for flag, value in values do
							local setter = base and base.Setters and base.Setters[flag]
							if setter and pcall(setter, value) then
								applied += 1
							else
								skipped += 1
							end
						end
						Menu.notify("Preset cargado", "success",
							("%s · %d aplicado(s), %d omitido(s)"):format(name, applied, skipped))
					end,
				})
				service:Button({
					Text = "Borrar preset",
					Danger = true,
					Callback = function()
						local base = shell()
						local name = (base and base.Values and base.Values["ui.presetName"]) or "default"
						local ok, why = Config:DeletePreset(name)
						Menu.notify(ok and "Preset borrado" or "No se pudo borrar",
							ok and "success" or "error", tostring(why or name))
					end,
				})
			end

			local session = page:Section("Sesión", 2)
			session:Status(("Versión: %s"):format(Core.VERSION), "info")
			session:Status(("Carpeta de datos: %s"):format(Config and Config.FOLDER or "FatCatProject"), "info")
			session:Button({
				Text = "Recargar interfaz",
				Callback = function()
					-- Reducing motion to on/off is the cheapest full repaint that also
					-- proves the design module is responsive; a raw Init would drop
					-- every flag the user just set.
					Design.setReducedMotion(Design.reducedMotion)
					Menu.notify("Interfaz recargada", "success")
				end,
			})
			session:Button({
				Text = "Descargar Fat Cat",
				Danger = true,
				Callback = function()
					local runtime = Core:TryRequire("FatCatEnv")
					if runtime then
						runtime.unload()
					end
				end,
			})
			session:Label("Descargar quita la ventana, los hooks y el ESP, y devuelve walkspeed y salto a su valor original.")
		end

		-- ==========================================================================
		-- Pages with more than one tool
		-- ==========================================================================
		-- Seven tabs is the budget (see the header). These two pages stack their
		-- second tool under the first, in the same scroll column.

		local function stackTools(page, firstPath, secondPath, title)
			local module, why = Core:TryRequire(firstPath)
			if not module then
				page:Section(title):Label(("No se pudo cargar %s: %s"):format(firstPath, tostring(why)))
				return
			end
			pcall(module.mount, page)

			local second, secondWhy = Core:TryRequire(secondPath)
			if not second then
				page:Section(title):Label(("No se pudo cargar %s: %s"):format(secondPath, tostring(secondWhy)))
				return
			end
			-- The second tool's own mount() looks for its page sections; passing the
			-- same page puts it underneath the first one instead of over it.
			pcall(second.mount, page)
		end

		local function attach(window, tabName, modulePath)
			local page = pageFor(window, tabName)
			if tabName == "Exploit" then
				stackTools(page, modulePath, "FatCatProjectiles", tabName)
				return
			end
			local module, why = Core:TryRequire(modulePath)
			if not module then
				page:Section(tabName):Label(("No se pudo cargar %s: %s"):format(modulePath, tostring(why)))
				return
			end
			if type(module.mount) ~= "function" then
				page:Section(tabName):Label(modulePath .. " no expone mount().")
				return
			end
			local ok, err = pcall(module.mount, page)
			if not ok then
				page:Section(tabName):Label(("La pestaña falló: %s"):format(tostring(err)))
				Core:Log("error", ("mount %s: %s"):format(modulePath, tostring(err)))
			end
		end

		-- ==========================================================================
		-- Build
		-- ==========================================================================

		function Menu.build()
			local base = shell()
			if not base then
				return false, "el shell Fat Cat no está cargado"
			end
			if built then
				base:EnsureBuilt()
				return true
			end
			built = true

			-- The shell ships with a default "Main" tab so it is useful on its own.
			-- The project replaces it: the window takes its tab list from
			-- `Hub._initOptions`, so naming the first real tab here is what stops a
			-- second, empty "Main" from taking a slot in the seven-tab budget. This has
			-- to happen before Mount, because Mount calls EnsureBuilt, which is the
			-- call that builds the window.
			base._initOptions = base._initOptions or {}
			base._initOptions.Tabs = { Menu.TABS[1][1] }

			base:Mount(function(_activeHub, window)
				buildHome(window)
				buildSettings(window)
				for _, entry in Menu.TABS do
					local name, modulePath = entry[1], entry[2]
					if modulePath then
						-- One pcall per page: a broken module costs one tab, never the
						-- menu.
						local ok, err = pcall(attach, window, name, modulePath)
						if not ok then
							Core:Log("error", ("attach %s: %s"):format(name, tostring(err)))
						end
					end
				end
				-- Adding a tab selects it, so the last one added would otherwise be
				-- what the user sees first. Home is the intended landing page.
				window:SelectTab("Home")
			end)

			return true
		end

		---Select a tab if it exists.
		function Menu.tab(name)
			local base = shell()
			if not base then
				return false, "no hay shell"
			end
			if not base._window then
				base:EnsureBuilt()
			end
			if not base._window or not base._window.pages[name] then
				return false, ("no hay pestaña '%s'"):format(tostring(name))
			end
			base._window:SelectTab(name)
			return true
		end

		---Switch palette and push the accent into the shell.
		function Menu.setTheme(name)
			local ok, why = Design.apply(name)
			if not ok then
				return false, why
			end
			local base = shell()
			if base and type(base.SetAccent) == "function" then
				pcall(base.SetAccent, Design.color("accent"), Design.color("accentAlt"))
			end
			return true
		end

		---Toast through the shell, when it has one.
		function Menu.notify(title, kind, detail)
			local base = shell()
			if base and type(base.Notify) == "function" then
				return base.Notify(title, kind, detail)
			end
			return false
		end

		---Drop the project's view of the shell. The GUI itself is the shell's job:
		---its ScreenGui was parented to CoreGui, and destroying it takes the tabs.
		function Menu.unmount()
			built = false
		end

		return function(core, design, _signal, _materials)
			Core = core
			Design = design
			Core:OnDestroy("FatCatMenu", Menu.unmount)
			return Menu
		end
	end)()
	Modules['FatCatMenu'] = module
end
-- ---------------------------------------------------------------------
-- FatCatShell.lua -- run on demand by FatCatInit, not at load time.
-- ---------------------------------------------------------------------
do
	local loadedShell = false
	Modules['FatCatShell'] = function()
		if loadedShell then
			return true
		end
		loadedShell = true
		-- Fat Cat | library, loader and UI builder.
		-- Derived from the FatCat Hub menu (KaliHub shell): the game-specific code is gone, the
		-- shell is rebuilt. Exposes _G.FatCatHub for loader scripts and game modules.
		--
		--   local Hub = loadstring(game:HttpGet("<url>"))()
		--   local Window = Hub:Window({ Title = "My Hub", Tabs = { "Main" } })
		--   local tab = Window:Tab("Main")
		--   local box = tab:Section("Options")
		--   box:Toggle({ Text = "Feature", Default = false, Flag = "feature" })
		--
		-- Structure:
		--   theme / animations / config   constants and small helpers
		--   hub                           state, input, notifications, storage
		--   components                    card, section, toggle, slider, cycle,
		--                                 input, dropdown, keybind, button, group,
		--                                 color, label, divider
		--   window                        frame, title bar, tab bar, pages, resize
		--   loader                        boot, xpcall diagnostics

		if _G.FatCatHub then
			pcall(function()
				_G.FatCatHub:Destroy()
			end)
		end

		do
			-- ======================================================================
			-- Services
			-- ======================================================================
			local playersService = game:GetService("Players")
			local userInputService = game:GetService("UserInputService")
			local httpService = game:GetService("HttpService")
			local tweenService = game:GetService("TweenService")

			local localPlayer = playersService.LocalPlayer

			-- ======================================================================
			-- Config
			-- ======================================================================
			local CONFIG = {
				-- Two words, no "Hub": that is the product name the menu shows.
				title = "Fat Cat",
				version = "1.0.0",
				width = 460,
				height = 560,
				minWidth = 380,
				minHeight = 380,
				maxWidth = 900,
				maxHeight = 820,
				titleHeight = 40,
				tabHeight = 34,
				footerHeight = 22,
				cornerRadius = 12,
				cardRadius = 8,
				tabs = { "Main" },
				-- Both shifts: a laptop keyboard has no right shift, and a menu that
				-- only opens with a key you do not have looks like a broken menu.
				menuKey = { "RightShift", "LeftShift" },
				hintsKeys = { "H" },
				searchPlaceholder = "Buscar...",
				saveFolder = "FatCatHub",
				saveFile = "FatCatHub/config.json",
				prefsFile = "FatCatHub/preferences.json",
			}

			local THEME = {
				backgroundTop = Color3.fromRGB(26, 26, 30),
				backgroundBottom = Color3.fromRGB(12, 12, 14),
				card = Color3.fromRGB(38, 38, 43),
				cardHover = Color3.fromRGB(47, 47, 53),
				element = Color3.fromRGB(19, 19, 22),
				elementHover = Color3.fromRGB(45, 45, 51),
				chip = Color3.fromRGB(28, 28, 32),
				section = Color3.fromRGB(17, 17, 20),
				outline = Color3.fromRGB(104, 104, 114),
				text = Color3.fromRGB(240, 240, 243),
				textOff = Color3.fromRGB(198, 198, 204),
				textDim = Color3.fromRGB(126, 126, 134),
				accent = Color3.fromRGB(236, 236, 240),
				accentAlt = Color3.fromRGB(138, 138, 148),
				negative = Color3.fromRGB(232, 92, 96),
				positive = Color3.fromRGB(124, 222, 146),
				onAccent = Color3.fromRGB(18, 18, 21),
			}

			-- Swappable at runtime: Hub:SetAccent(color1, color2).
			local colorA = THEME.accent
			local colorB = THEME.accentAlt

			local FONT = Enum.Font.Gotham
			local FONT_BOLD = Enum.Font.GothamBold
			-- Gotham renders every glyph at its own optical size; MediumBold keeps
			-- headings and values the same weight as their row text.
			local FONT_MEDIUM = Enum.Font.GothamMedium
			-- Monospace for anything that is code: a proportional face makes column
			-- alignment in a decompiled listing unreadable.
			local FONT_MONO = Enum.Font.RobotoMono

			local ANIM = {
				fast = TweenInfo.new(0.14, Enum.EasingStyle.Quad, Enum.EasingDirection.Out),
				slide = TweenInfo.new(0.07, Enum.EasingStyle.Quad, Enum.EasingDirection.Out),
				medium = TweenInfo.new(0.32, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
				pop = TweenInfo.new(0.26, Enum.EasingStyle.Back, Enum.EasingDirection.Out),
				-- Opening eases out of the overshoot instead of slamming in.
				open = TweenInfo.new(0.36, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
			}

			local TEXT_SIZE = { title = 14, tab = 13, label = 13, value = 13, section = 11, hint = 11, code = 11 }

			local UIELEMENT = Enum.RenderPriority.Character.Value + 100

			-- Forward declaration: the helpers below (retween in particular) touch the
			-- shared state table, which is filled in further down.
			local Hub = {
				Values = {},
				Defaults = {},
				Setters = {},
				Keybinds = {},
				Searchables = {},
				Connections = {},
				_entries = {},
				_cancels = setmetatable({}, { __mode = "k" }),
				_gradients = setmetatable({}, { __mode = "k" }),
				_listening = nil,
				_window = nil,
				_screen = nil,
				_toasts = nil,
			}

			-- ======================================================================
			-- Helpers
			-- ======================================================================

			---Create an instance with properties and a parent.
			local function create(className, properties, parent)
				local instance = Instance.new(className)
				for key, value in properties do
					instance[key] = value
				end
				instance.Parent = parent
				return instance
			end

			---Play a tween.
			local function tween(instance, info, goal)
				local newTween = tweenService:Create(instance, info, goal)
				newTween:Play()
				return newTween
			end

			---Kill any tween already running on an object, then play a new one.
			---Without this, a fast hover in/out leaves two tweens fighting over the same
			---property and the row sticks in its hovered colour. The handle is stored on
			---the (weak) registry and dropped when the tween completes, so a row that is
			---hovered ten thousand times keeps exactly one entry.
			local function retween(instance, info, goal)
				local running = Hub._cancels[instance]
				if running then
					for _, handle in running do
						pcall(function()
							handle:Cancel()
						end)
					end
					running = nil
				end
				local newTween = tweenService:Create(instance, info, goal)
				Hub._cancels[instance] = { newTween }
				newTween.Completed:Connect(function()
					local current = Hub._cancels[instance]
					if current and current[1] == newTween then
						Hub._cancels[instance] = nil
					end
				end)
				newTween:Play()
				return newTween
			end

			---Rounded corners plus an optional border stroke, in one call.
			local function round(instance, radius, outline)
				local corner = create("UICorner", { CornerRadius = UDim.new(0, radius) }, instance)
				if outline then
					create("UIStroke", {
						Color = THEME.outline,
						Transparency = outline.transparency or 0.6,
						Thickness = outline.thickness or 1,
						ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
					}, instance)
				end
				return corner
			end

			---Rotation-honest gradient. The base uses the live accent pair; a caller can
			---override the sequence for one-off tints (toasts, swatches).
			local function gradient(parent, rotation, sequence)
				return create("UIGradient", {
					Color = sequence or ColorSequence.new(colorA, colorB),
					Rotation = rotation or 0,
				}, parent)
			end

			---Format a slider value without trailing noise: 3 -> "3", 0.30 -> "0.3".
			local function formatNumber(value, decimals)
				if decimals <= 0 then
					return tostring(math.floor(value + 0.5))
				end
				local text = string.format("%." .. decimals .. "f", value)
				text = string.gsub(text, "0+$", "")
				text = string.gsub(text, "%.$", "")
				return text
			end

			---Clamp a UDim2 position so the frame stays on screen after a resolution
			---change or a drag past the viewport edge.
			local function clampToViewport(target)
				local viewport = workspace.CurrentCamera and workspace.CurrentCamera.ViewportSize or Vector2.new(1920, 1080)
				local size = target.AbsoluteSize
				local position = target.Position
				local x = position.X.Offset
				local y = position.Y.Offset
				local minX = -size.X + 64
				local maxX = viewport.X - 64
				local minY = 0
				local maxY = viewport.Y - CONFIG.titleHeight
				if x < minX then
					x = minX
				elseif x > maxX then
					x = maxX
				end
				if y < minY then
					y = minY
				elseif y > maxY then
					y = maxY
				end
				target.Position = UDim2.new(0, x, 0, y)
			end

			---True when an input is a primary press (mouse or touch).
			local function isPress(input)
				return input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch
			end

			---True when an input is pointer movement.
			local function isMove(input)
				return input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch
			end

			---Darken or lighten a colour by a factor, clamped to [0, 1].
			local function shade(color, factor)
				if factor >= 0 then
					return Color3.new(
						color.R + (1 - color.R) * factor,
						color.G + (1 - color.G) * factor,
						color.B + (1 - color.B) * factor
					)
				end
				return Color3.new(color.R * (1 + factor), color.G * (1 + factor), color.B * (1 + factor))
			end

			-- ======================================================================
			-- Hub state
			-- ======================================================================
			Hub._initOptions = { Title = CONFIG.title, Tabs = CONFIG.tabs }
			Hub._currentGroup = nil
			Hub._builders = {}
			Hub.deferBoot = false

			_G.FatCatHub = Hub

			---Track a global connection so Destroy can close it.
			local function connect(signal, callback)
				local connection = signal:Connect(callback)
				table.insert(Hub.Connections, connection)
				return connection
			end

			---Look up a KeyCode by name, nil when the name is unknown.
			---True when `keyCode` is any of `names` (a string or a list of strings).
			---Comparing KeyCodes by .Name keeps a typo in the config from silently
			---killing the hotkey: "RightShift" and Enum.KeyCode.RightShift match.
			local function matchesKey(keyCode, names)
				if keyCode == nil or names == nil then
					return false
				end
				if typeof(names) == "string" then
					return keyCode.Name == names
				end
				for _, name in names do
					if keyCode.Name == name then
						return true
					end
				end
				return false
			end

			---Any of the modifiers the hint strip accepts as "ctrl".
			local function isAnyControlDown()
				for _, code in { Enum.KeyCode.LeftControl, Enum.KeyCode.RightControl } do
					local ok, down = pcall(function()
						return userInputService:IsKeyDown(code)
					end)
					if ok and down then
						return true
					end
				end
				return false
			end

			local function keyCodeFromName(name)
				if typeof(name) ~= "string" or name == "" then
					return nil
				end
				for _, item in Enum.KeyCode:GetEnumItems() do
					if item.Name == name then
						return item
					end
				end
				return nil
			end

			---Save or read a JSON file when the executor allows it.
			local function writeJson(path, data)
				if not (writefile and httpService) then
					return false, "Saving is not supported by this executor."
				end
				local ok, result = pcall(function()
					if makefolder and isfolder then
						local folder = string.match(path, "^(.-)/[^/]+$")
						if folder and not isfolder(folder) then
							makefolder(folder)
						end
					end
					writefile(path, httpService:JSONEncode(data))
				end)
				return ok, result
			end

			local function readJson(path)
				if not (readfile and isfile and httpService and isfile(path)) then
					return nil
				end
				local ok, data = pcall(function()
					return httpService:JSONDecode(readfile(path))
				end)
				if ok and typeof(data) == "table" then
					return data
				end
				return nil
			end

			-- ======================================================================
			-- Theme API
			-- ======================================================================

			---Recolour the whole interface at runtime.
			function Hub:SetAccent(primary, secondary)
				colorA = primary or THEME.accent
				colorB = secondary or shade(colorA, -0.45)

				for instance, _ in pairs(Hub._gradients) do
					if instance.Parent then
						instance.Color = ColorSequence.new(colorA, colorB)
					end
				end
			end

			---Create a gradient and register it for recolouring.
			local function liveGradient(parent, rotation)
				local instance = gradient(parent, rotation)
				Hub._gradients[instance] = true
				return instance
			end

			-- ======================================================================
			-- Notifications
			-- ======================================================================
			local function ensureToasts()
				if Hub._toasts and Hub._toasts.Parent then
					return Hub._toasts
				end
				local holder = create("Frame", {
					Name = "Notifications",
					AnchorPoint = Vector2.new(1, 1),
					Position = UDim2.new(1, -16, 1, -16),
					Size = UDim2.fromOffset(252, 340),
					BackgroundTransparency = 1,
					ZIndex = 50,
				}, Hub._screen)
				create("UIListLayout", {
					Padding = UDim.new(0, 6),
					SortOrder = Enum.SortOrder.LayoutOrder,
					HorizontalAlignment = Enum.HorizontalAlignment.Right,
					VerticalAlignment = Enum.VerticalAlignment.Bottom,
				}, holder)
				Hub._toasts = holder
				return holder
			end

			---Show a stacked toast. `kind` is "on", "off" or "info".
			function Hub:Notify(title, kind, detail)
				if not (Hub._screen and Hub._screen.Parent) then
					return false
				end

				local holder = ensureToasts()
				local positive = kind == "on" or kind == "success"
				local negative = kind == "off" or kind == "error"
				local tint = positive and THEME.positive or (negative and THEME.negative or colorA)

				local toast = create("CanvasGroup", {
					Size = UDim2.fromOffset(252, 40),
					BackgroundColor3 = Color3.fromRGB(18, 18, 21),
					BorderSizePixel = 0,
					GroupTransparency = 1,
				}, holder)
				round(toast, 9)
				create("UIStroke", {
					Color = THEME.outline,
					Transparency = 0.72,
					ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
				}, toast)

				local bar = create("Frame", {
					Size = UDim2.new(0, 3, 1, -14),
					Position = UDim2.fromOffset(7, 7),
					BackgroundColor3 = tint,
					BorderSizePixel = 0,
				}, toast)
				round(bar, 2)

				create("TextLabel", {
					Size = UDim2.new(1, -92, 0, 16),
					Position = UDim2.fromOffset(19, 5),
					BackgroundTransparency = 1,
					Text = tostring(title),
					TextColor3 = THEME.text,
					TextSize = 13,
					Font = FONT_MEDIUM,
					TextXAlignment = Enum.TextXAlignment.Left,
					TextTruncate = Enum.TextTruncate.AtEnd,
				}, toast)

				if detail then
					create("TextLabel", {
						Size = UDim2.new(1, -92, 0, 14),
						Position = UDim2.fromOffset(19, 21),
						BackgroundTransparency = 1,
						Text = tostring(detail),
						TextColor3 = THEME.textDim,
						TextSize = 11,
						Font = FONT,
						TextXAlignment = Enum.TextXAlignment.Left,
						TextTruncate = Enum.TextTruncate.AtEnd,
					}, toast)
				end

				local badge = create("TextLabel", {
					Size = UDim2.fromOffset(52, 16),
					Position = UDim2.new(1, -60, 0, 5),
					BackgroundTransparency = 1,
					Text = positive and "ON" or (negative and "OFF" or "INFO"),
					TextColor3 = tint,
					TextSize = 11,
					Font = FONT_BOLD,
					TextXAlignment = Enum.TextXAlignment.Right,
				}, toast)

				local scale = create("UIScale", { Scale = 0.94 }, toast)
				retween(scale, ANIM.pop, { Scale = 1 })
				tween(toast, ANIM.fast, { GroupTransparency = 0 })

				if detail then
					badge.Position = UDim2.new(1, -60, 0, 7)
				end

				task.delay(detail and 3.4 or 2.4, function()
					if not toast.Parent then
						return
					end
					tween(toast, ANIM.medium, { GroupTransparency = 1 }).Completed:Connect(function()
						toast:Destroy()
					end)
				end)

				return true
			end

			---Older name kept so game modules written for FatCat Hub do not break.
			Hub.notify = function(title, enabled)
				Hub:Notify(title, enabled and "on" or "off")
			end

			-- ======================================================================
			-- Components
			-- ======================================================================

			local Components = {}
			Hub.Components = Components

			---Ripple that expands from the cursor inside a clipped card.
			local function addRipple(card)
				card.InputBegan:Connect(function(input)
					if not isPress(input) then
						return
					end
					local offset = Vector2.new(input.Position.X, input.Position.Y) - card.AbsolutePosition
					local ripple = create("Frame", {
						AnchorPoint = Vector2.new(0.5, 0.5),
						Position = UDim2.fromOffset(offset.X, offset.Y),
						Size = UDim2.fromOffset(0, 0),
						BackgroundColor3 = Color3.new(1, 1, 1),
						BackgroundTransparency = 0.86,
						BorderSizePixel = 0,
						ZIndex = 0,
					}, card)
					round(ripple, 999)
					local diameter = math.max(card.AbsoluteSize.X, card.AbsoluteSize.Y) * 2
					tween(ripple, ANIM.medium, {
						Size = UDim2.fromOffset(diameter, diameter),
						BackgroundTransparency = 1,
					}).Completed:Connect(function()
						ripple:Destroy()
					end)
				end)
			end

			---A rounded row card. Hover lifts the card instead of the old 0.35 <-> 0.65
			---transparency jump, and the stroke fades with it so the edge never flickers.
			---Register a new card with the open collapsible group, if any.
			local function adoptIntoGroup(card)
				local group = Hub._currentGroup
				if not group then
					return
				end
				table.insert(group.cards, card)
				card:SetAttribute("GroupHidden", group.collapsed)
				card.Visible = not group.collapsed
			end

			local function createCard(parent, text, height, interactive)
				local card = create(interactive and "TextButton" or "Frame", {
					Name = text,
					Size = UDim2.new(1, 0, 0, height),
					BackgroundColor3 = THEME.card,
					BackgroundTransparency = 0.06,
					BorderSizePixel = 0,
					AutoButtonColor = false,
					Text = "",
					ClipsDescendants = true,
					LayoutOrder = parent and parent:GetAttribute("CardCount") or nil,
				}, parent)

				if parent then
					parent:SetAttribute("CardCount", (parent:GetAttribute("CardCount") or 0) + 1)
				end

				round(card, CONFIG.cardRadius)
				local stroke = create("UIStroke", {
					Color = THEME.outline,
					Transparency = 0.66,
					ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
				}, card)

				card:SetAttribute("SearchText", text)
				addRipple(card)
				adoptIntoGroup(card)

				card.MouseEnter:Connect(function()
					retween(card, ANIM.fast, { BackgroundTransparency = 0, BackgroundColor3 = THEME.cardHover })
					retween(stroke, ANIM.fast, { Transparency = 0.4 })
				end)

				card.MouseLeave:Connect(function()
					retween(card, ANIM.fast, { BackgroundTransparency = 0.06, BackgroundColor3 = THEME.card })
					retween(stroke, ANIM.fast, { Transparency = 0.66 })
				end)

				return card, stroke
			end

			---A section header: uppercase caption, accent tick and a hairline divider.
			function Components.SectionHeader(parent, text)
				local holder = create("Frame", {
					Name = tostring(text) .. " Header",
					Size = UDim2.new(1, 0, 0, 24),
					BackgroundTransparency = 1,
					LayoutOrder = #parent:GetChildren() + 1,
				}, parent)

				local marker = create("Frame", {
					Size = UDim2.fromOffset(3, 11),
					Position = UDim2.new(0, 2, 0.5, -5),
					BackgroundColor3 = Color3.new(1, 1, 1),
					BorderSizePixel = 0,
				}, holder)
				round(marker, 2)
				liveGradient(marker, 90)

				create("TextLabel", {
					Size = UDim2.new(1, -16, 1, 0),
					Position = UDim2.fromOffset(12, 0),
					BackgroundTransparency = 1,
					Text = string.upper(tostring(text)),
					TextColor3 = THEME.textOff,
					TextSize = TEXT_SIZE.section,
					Font = FONT_BOLD,
					TextXAlignment = Enum.TextXAlignment.Left,
				}, holder)

				local line = create("Frame", {
					Size = UDim2.new(1, 0, 0, 1),
					Position = UDim2.new(0, 0, 1, -1),
					BackgroundColor3 = THEME.outline,
					BackgroundTransparency = 0.55,
					BorderSizePixel = 0,
				}, holder)
				create("UIGradient", {
					Transparency = NumberSequence.new(0.1, 1),
					Rotation = 0,
				}, line)

				return holder
			end

			---A bordered group box. Rows added to `Components.Section` land inside it.
			function Components.Section(parent, text)
				local box = create("Frame", {
					Name = tostring(text),
					Size = UDim2.new(1, 0, 0, 0),
					AutomaticSize = Enum.AutomaticSize.Y,
					BackgroundColor3 = THEME.section,
					BackgroundTransparency = 0.15,
					BorderSizePixel = 0,
					LayoutOrder = #parent:GetChildren() + 1,
				}, parent)
				round(box, CONFIG.cardRadius + 2)
				create("UIStroke", {
					Color = THEME.outline,
					Transparency = 0.7,
					ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
				}, box)
				create("UIPadding", {
					PaddingTop = UDim.new(0, 6),
					PaddingBottom = UDim.new(0, 6),
					PaddingLeft = UDim.new(0, 6),
					PaddingRight = UDim.new(0, 6),
				}, box)
				create("UIListLayout", {
					Padding = UDim.new(0, 4),
					SortOrder = Enum.SortOrder.LayoutOrder,
				}, box)

				Components.SectionHeader(box, text)
				return box
			end

			---Toggle row: checkbox with a pop, sliding label, optional keybind chip.
			function Components.Toggle(parent, options)
				options = options or {}
				local text = options.Text or options.Name or "Toggle"
				local default = options.Default == true
				local flag = options.Flag or text
				local callback = options.Callback
				local description = options.Description

				local iconColumn = options.Icon and 44 or 32
				local card = createCard(parent, flag, description and 46 or 32, true)

				local box = create("Frame", {
					Size = UDim2.fromOffset(18, 18),
					Position = UDim2.new(0, 9, 0, description and 9 or 7),
					BackgroundColor3 = THEME.element,
					BorderSizePixel = 0,
				}, card)
				round(box, 5)
				local boxStroke = create("UIStroke", {
					Color = default and colorA or THEME.outline,
					Transparency = default and 0 or 0.4,
					ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
				}, box)

				local check = create("Frame", {
					AnchorPoint = Vector2.new(0.5, 0.5),
					Position = UDim2.fromScale(0.5, 0.5),
					Size = default and UDim2.fromOffset(10, 10) or UDim2.fromOffset(0, 0),
					BackgroundColor3 = Color3.new(1, 1, 1),
					BorderSizePixel = 0,
				}, box)
				round(check, 3)
				liveGradient(check, 45)

				local label = create("TextLabel", {
					Size = UDim2.new(1, -(iconColumn + 12), 0, description and 18 or 32),
					Position = UDim2.fromOffset(iconColumn, description and 7 or 0),
					BackgroundTransparency = 1,
					Text = text,
					TextColor3 = default and THEME.text or THEME.textOff,
					TextSize = TEXT_SIZE.label,
					Font = FONT,
					TextXAlignment = Enum.TextXAlignment.Left,
					TextTruncate = Enum.TextTruncate.AtEnd,
				}, card)

				if description then
					create("TextLabel", {
						Size = UDim2.new(1, -(iconColumn + 12), 0, 14),
						Position = UDim2.fromOffset(iconColumn, 25),
						BackgroundTransparency = 1,
						Text = description,
						TextColor3 = THEME.textDim,
						TextSize = 11,
						Font = FONT,
						TextXAlignment = Enum.TextXAlignment.Left,
						TextTruncate = Enum.TextTruncate.AtEnd,
					}, card)
				end

				-- Glow rail on the left edge, only while enabled.
				local rail = create("Frame", {
					Size = UDim2.new(0, 3, 1, -12),
					Position = UDim2.fromOffset(0, 6),
					BackgroundColor3 = Color3.new(1, 1, 1),
					BackgroundTransparency = default and 0 or 1,
					BorderSizePixel = 0,
				}, card)
				round(rail, 2)
				liveGradient(rail, 90)

				local state = default
				local entry = { Flag = flag, Kind = "toggle", Card = card, Set = nil }

				local function set(value, silent)
					state = value == true
					Hub.Values[flag] = state

					retween(check, ANIM.pop, { Size = state and UDim2.fromOffset(10, 10) or UDim2.fromOffset(0, 0) })
					retween(boxStroke, ANIM.fast, {
						Color = state and colorA or THEME.outline,
						Transparency = state and 0 or 0.4,
					})
					retween(label, ANIM.fast, { TextColor3 = state and THEME.text or THEME.textOff })
					retween(rail, ANIM.fast, { BackgroundTransparency = state and 0 or 1 })

					if not silent and callback then
						local ok, err = pcall(callback, state)
						if not ok then
							Hub:Notify(tostring(flag), "error", tostring(err))
						end
					end
				end

				entry.Set = set
				Hub.Setters[flag] = set
				Hub.Defaults[flag] = default
				Hub.Values[flag] = default
				table.insert(Hub._entries, entry)

				card.Activated:Connect(function()
					set(not state)
					Hub:Notify(text, state and "on" or "off")
				end)

				table.insert(Hub.Searchables, card)
				return card
			end

			---Slider row: filled gradient track, draggable knob, click-anywhere track.
			function Components.Slider(parent, options)
				options = options or {}
				local text = options.Text or options.Name or "Slider"
				local minValue = options.Min or 0
				local maxValue = options.Max or 100
				local decimals = options.Decimals or 0
				local default = math.clamp(options.Default or minValue, minValue, maxValue)
				local flag = options.Flag or text
				local callback = options.Callback
				local suffix = options.Suffix or ""

				assert(maxValue > minValue, "Slider max must be greater than min for '" .. tostring(text) .. "'")

				local card = createCard(parent, flag, 46, false)
				local span = maxValue - minValue
				local startAlpha = (default - minValue) / span

				create("TextLabel", {
					Size = UDim2.new(1, -104, 0, 20),
					Position = UDim2.fromOffset(11, 5),
					BackgroundTransparency = 1,
					Text = text,
					TextColor3 = THEME.text,
					TextSize = TEXT_SIZE.label,
					Font = FONT,
					TextXAlignment = Enum.TextXAlignment.Left,
					TextTruncate = Enum.TextTruncate.AtEnd,
				}, card)

				local valueLabel = create("TextLabel", {
					Size = UDim2.fromOffset(86, 20),
					Position = UDim2.new(1, -97, 0, 5),
					BackgroundTransparency = 1,
					Text = formatNumber(default, decimals) .. suffix,
					TextColor3 = THEME.textOff,
					TextSize = TEXT_SIZE.value,
					Font = FONT_MEDIUM,
					TextXAlignment = Enum.TextXAlignment.Right,
				}, card)

				local track = create("Frame", {
					Size = UDim2.new(1, -22, 0, 5),
					Position = UDim2.fromOffset(11, 32),
					BackgroundColor3 = THEME.element,
					BorderSizePixel = 0,
				}, card)
				round(track, 999)

				local fill = create("Frame", {
					Size = UDim2.fromScale(startAlpha, 1),
					BackgroundColor3 = Color3.new(1, 1, 1),
					BorderSizePixel = 0,
				}, track)
				round(fill, 999)
				liveGradient(fill, 0)

				local knob = create("Frame", {
					AnchorPoint = Vector2.new(0.5, 0.5),
					Size = UDim2.fromOffset(13, 13),
					Position = UDim2.new(startAlpha, 0, 0.5, 0),
					BackgroundColor3 = Color3.new(1, 1, 1),
					BorderSizePixel = 0,
					ZIndex = 2,
				}, track)
				round(knob, 999)
				create("UIStroke", {
					Color = THEME.backgroundBottom,
					Thickness = 2,
					ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
				}, knob)
				local knobScale = create("UIScale", {}, knob)

				local hitbox = create("TextButton", {
					Size = UDim2.new(1, -14, 0, 24),
					Position = UDim2.fromOffset(7, 21),
					BackgroundTransparency = 1,
					Text = "",
					AutoButtonColor = false,
				}, card)

				local entry = { Flag = flag, Kind = "slider", Card = card, Set = nil }
				local dragging = false

				local function set(value, silent)
					local factor = 10 ^ decimals
					value = math.clamp(tonumber(value) or minValue, minValue, maxValue)
					value = math.floor(value * factor + 0.5) / factor
					local alpha = (value - minValue) / span

					retween(fill, ANIM.slide, { Size = UDim2.fromScale(alpha, 1) })
					retween(knob, ANIM.slide, { Position = UDim2.new(alpha, 0, 0.5, 0) })

					valueLabel.Text = formatNumber(value, decimals) .. suffix
					Hub.Values[flag] = value

					if not silent and callback then
						task.spawn(pcall, callback, value)
					end
				end

				entry.Set = set
				Hub.Setters[flag] = set
				Hub.Defaults[flag] = default
				Hub.Values[flag] = default
				table.insert(Hub._entries, entry)

				local function updateFromX(positionX)
					local width = track.AbsoluteSize.X
					if width <= 0 then
						return
					end
					local alpha = math.clamp((positionX - track.AbsolutePosition.X) / width, 0, 1)
					set(minValue + span * alpha)
				end

				hitbox.InputBegan:Connect(function(input)
					if not isPress(input) then
						return
					end
					dragging = true
					retween(knobScale, ANIM.pop, { Scale = 1.3 })
					retween(valueLabel, ANIM.fast, { TextColor3 = colorA })
					updateFromX(input.Position.X)
				end)

				connect(userInputService.InputChanged, function(input)
					if dragging and isMove(input) then
						updateFromX(input.Position.X)
					end
				end)

				connect(userInputService.InputEnded, function(input)
					if not dragging or not isPress(input) then
						return
					end
					dragging = false
					retween(knobScale, ANIM.pop, { Scale = 1 })
					retween(valueLabel, ANIM.fast, { TextColor3 = THEME.textOff })
				end)

				table.insert(Hub.Searchables, card)
				return card
			end

			---Cycle row: label plus a button that steps through the options.
			function Components.Cycle(parent, options)
				options = options or {}
				local text = options.Text or options.Name or "Option"
				local list = options.Options or { "Off", "On" }
				local flag = options.Flag or text
				local callback = options.Callback
				local default = options.Default or list[1]

				local card = createCard(parent, flag, 56, false)

				create("TextLabel", {
					Size = UDim2.new(1, -22, 0, 20),
					Position = UDim2.fromOffset(11, 5),
					BackgroundTransparency = 1,
					Text = text,
					TextColor3 = THEME.text,
					TextSize = TEXT_SIZE.label,
					Font = FONT,
					TextXAlignment = Enum.TextXAlignment.Left,
					TextTruncate = Enum.TextTruncate.AtEnd,
				}, card)

				local button = create("TextButton", {
					Size = UDim2.new(1, -22, 0, 24),
					Position = UDim2.fromOffset(11, 28),
					BackgroundColor3 = THEME.element,
					BorderSizePixel = 0,
					Text = default,
					TextColor3 = THEME.textOff,
					TextSize = 12,
					Font = FONT,
					AutoButtonColor = false,
				}, card)
				round(button, 5)
				local buttonStroke = create("UIStroke", {
					Color = THEME.outline,
					Transparency = 0.55,
					ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
				}, button)

				local index = math.max(1, table.find(list, default) or 1)
				local entry = { Flag = flag, Kind = "cycle", Card = card, Set = nil }

				local function set(value, silent)
					local found = table.find(list, value)
					if not found then
						return
					end
					index = found
					Hub.Values[flag] = list[index]
					button.Text = tostring(list[index])

					if not silent and callback then
						task.spawn(pcall, callback, list[index])
					end
				end

				entry.Set = set
				Hub.Setters[flag] = set
				Hub.Defaults[flag] = default
				Hub.Values[flag] = default
				table.insert(Hub._entries, entry)

				button.MouseEnter:Connect(function()
					retween(buttonStroke, ANIM.fast, { Color = colorA, Transparency = 0 })
					retween(button, ANIM.fast, { BackgroundColor3 = THEME.elementHover })
				end)
				button.MouseLeave:Connect(function()
					retween(buttonStroke, ANIM.fast, { Color = THEME.outline, Transparency = 0.55 })
					retween(button, ANIM.fast, { BackgroundColor3 = THEME.element })
				end)

				button.Activated:Connect(function()
					index = index % #list + 1
					Hub.Values[flag] = list[index]
					button.Text = tostring(list[index])
					button.TextTransparency = 1
					retween(button, ANIM.fast, { TextTransparency = 0 })
					if callback then
						task.spawn(pcall, callback, list[index])
					end
				end)

				table.insert(Hub.Searchables, card)
				return card
			end

			---Dropdown: collapsed cycle-shaped button that expands a native scroll list.
			---Constrained to four rows so a long option list cannot push the window
			---layout, and the list closes on pick, on outside click or on tab switch.
			function Components.Dropdown(parent, options)
				options = options or {}
				local text = options.Text or options.Name or "Dropdown"
				local list = options.Options or {}
				local flag = options.Flag or text
				local callback = options.Callback
				local default = options.Default or list[1]

				local card = createCard(parent, flag, 56, false)
				local openHeight = 56 + math.min(#list, 4) * 22 + 8

				create("TextLabel", {
					Size = UDim2.new(1, -22, 0, 20),
					Position = UDim2.fromOffset(11, 5),
					BackgroundTransparency = 1,
					Text = text,
					TextColor3 = THEME.text,
					TextSize = TEXT_SIZE.label,
					Font = FONT,
					TextXAlignment = Enum.TextXAlignment.Left,
					TextTruncate = Enum.TextTruncate.AtEnd,
				}, card)

				local button = create("TextButton", {
					Size = UDim2.new(1, -22, 0, 24),
					Position = UDim2.fromOffset(11, 28),
					BackgroundColor3 = THEME.element,
					BorderSizePixel = 0,
					Text = "  " .. tostring(default) .. "      v",
					TextColor3 = THEME.textOff,
					TextSize = 12,
					Font = FONT,
					AutoButtonColor = false,
					TextXAlignment = Enum.TextXAlignment.Left,
					ClipsDescendants = true,
				}, card)
				round(button, 5)
				local arrow = create("Frame", {
					AnchorPoint = Vector2.new(1, 0.5),
					Size = UDim2.fromOffset(6, 6),
					Position = UDim2.new(1, -11, 0.5, 0),
					BackgroundColor3 = THEME.textDim,
					BorderSizePixel = 0,
					Rotation = 0,
				}, button)

				local scroll = create("ScrollingFrame", {
					Size = UDim2.new(1, -22, 0, 0),
					Position = UDim2.fromOffset(11, 56),
					BackgroundColor3 = THEME.element,
					BackgroundTransparency = 1,
					BorderSizePixel = 0,
					Visible = false,
					CanvasSize = UDim2.new(),
					AutomaticCanvasSize = Enum.AutomaticSize.Y,
					ScrollBarThickness = 2,
					ScrollBarImageColor3 = THEME.outline,
					ZIndex = 3,
				}, card)
				round(scroll, 5)
				create("UIListLayout", { Padding = UDim.new(0, 1), SortOrder = Enum.SortOrder.LayoutOrder }, scroll)
				create("UIPadding", {
					PaddingTop = UDim.new(0, 3),
					PaddingBottom = UDim.new(0, 3),
				}, scroll)

				local optionButtons = {}
				local expanded = false

				local function collapse()
					expanded = false
					scroll.Visible = false
					tween(card, ANIM.fast, { Size = UDim2.new(1, 0, 0, 56) })
					retween(arrow, ANIM.fast, { Rotation = 0 })
				end

				for index, option in list do
					local row = create("TextButton", {
						Size = UDim2.new(1, 0, 0, 21),
						BackgroundColor3 = THEME.element,
						BackgroundTransparency = 1,
						BorderSizePixel = 0,
						Text = "  " .. tostring(option),
						TextColor3 = THEME.textOff,
						TextSize = 12,
						Font = FONT,
						TextXAlignment = Enum.TextXAlignment.Left,
						AutoButtonColor = false,
						LayoutOrder = index,
						ZIndex = 4,
					}, scroll)
					round(row, 4)

					row.MouseEnter:Connect(function()
						retween(row, ANIM.fast, { BackgroundTransparency = 0, BackgroundColor3 = THEME.elementHover })
						retween(row, ANIM.fast, { TextColor3 = THEME.text })
					end)
					row.MouseLeave:Connect(function()
						retween(row, ANIM.fast, { BackgroundTransparency = 1, BackgroundColor3 = THEME.element })
						retween(row, ANIM.fast, { TextColor3 = THEME.textOff })
					end)

					optionButtons[index] = row

					row.Activated:Connect(function()
						Hub.Values[flag] = option
						button.Text = "  " .. tostring(option)
						collapse()
						if callback then
							task.spawn(pcall, callback, option)
						end
					end)
				end

				local entry = { Flag = flag, Kind = "dropdown", Card = card, Set = nil }

				local function set(value, silent)
					if not table.find(list, value) then
						return
					end
					Hub.Values[flag] = value
					button.Text = "  " .. tostring(value)
					collapse()
					if not silent and callback then
						task.spawn(pcall, callback, value)
					end
				end

				entry.Set = set
				Hub.Setters[flag] = set
				Hub.Defaults[flag] = default
				Hub.Values[flag] = default
				table.insert(Hub._entries, entry)

				button.Activated:Connect(function()
					expanded = not expanded
					scroll.Visible = expanded
					tween(card, ANIM.fast, { Size = UDim2.new(1, 0, 0, expanded and openHeight or 56) })
					retween(arrow, ANIM.fast, { Rotation = expanded and 180 or 0 })
				end)

				table.insert(Hub.Searchables, card)
				return card
			end

			---Text input row. Enter commits, Escape reverts to the last committed value.
			function Components.Input(parent, options)
				options = options or {}
				local text = options.Text or options.Name or "Input"
				local flag = options.Flag or text
				local placeholder = options.Placeholder or "Type here"
				local default = options.Default or ""
				local callback = options.Callback

				local card = createCard(parent, flag, 52, false)

				create("TextLabel", {
					Size = UDim2.new(1, -22, 0, 18),
					Position = UDim2.fromOffset(11, 4),
					BackgroundTransparency = 1,
					Text = text,
					TextColor3 = THEME.text,
					TextSize = TEXT_SIZE.label,
					Font = FONT,
					TextXAlignment = Enum.TextXAlignment.Left,
				}, card)

				local field = create("TextBox", {
					Size = UDim2.new(1, -22, 0, 24),
					Position = UDim2.fromOffset(11, 24),
					BackgroundColor3 = THEME.element,
					BackgroundTransparency = 0,
					BorderSizePixel = 0,
					PlaceholderText = placeholder,
					PlaceholderColor3 = THEME.textDim,
					Text = tostring(default),
					TextColor3 = THEME.text,
					TextSize = 12,
					Font = FONT,
					TextXAlignment = Enum.TextXAlignment.Left,
					ClearTextOnFocus = false,
				}, card)
				round(field, 5)
				create("UIPadding", { PaddingLeft = UDim.new(0, 8), PaddingRight = UDim.new(0, 8) }, field)
				local stroke = create("UIStroke", {
					Color = THEME.outline,
					Transparency = 0.55,
					ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
				}, field)

				local committed = tostring(default)
				local entry = { Flag = flag, Kind = "input", Card = card, Set = nil }

				local function set(value, silent)
					committed = tostring(value or "")
					field.Text = committed
					Hub.Values[flag] = committed
					if not silent and callback then
						task.spawn(pcall, callback, committed)
					end
				end

				entry.Set = set
				Hub.Setters[flag] = set
				Hub.Defaults[flag] = default
				Hub.Values[flag] = default
				table.insert(Hub._entries, entry)

				field.Focused:Connect(function()
					retween(stroke, ANIM.fast, { Color = colorA, Transparency = 0 })
				end)
				field.FocusLost:Connect(function(enter)
					retween(stroke, ANIM.fast, { Color = THEME.outline, Transparency = 0.55 })
					if enter then
						set(field.Text)
					else
						field.Text = committed
					end
				end)

				table.insert(Hub.Searchables, card)
				return card
			end

			---Keybind row. Click the chip, press a key, Escape clears it.
			---`options.OnKey` gets the KeyCode on every press, so a module can own the
			---behaviour instead of the hub guessing what the key should do.
			function Components.Keybind(parent, options)
				options = options or {}
				local text = options.Text or options.Name or "Keybind"
				local flag = options.Flag or text
				local default = options.Default or ""
				local onKey = options.OnKey

				local card = createCard(parent, flag, 32, false)

				create("TextLabel", {
					Size = UDim2.new(1, -100, 1, 0),
					Position = UDim2.fromOffset(11, 0),
					BackgroundTransparency = 1,
					Text = text,
					TextColor3 = THEME.text,
					TextSize = TEXT_SIZE.label,
					Font = FONT,
					TextXAlignment = Enum.TextXAlignment.Left,
					TextTruncate = Enum.TextTruncate.AtEnd,
				}, card)

				-- 26 px tall: a keybind is clicked constantly to rebind, and the design
				-- audit flags pointer targets under 24 px.
				local chip = create("TextButton", {
					Size = UDim2.fromOffset(84, 26),
					Position = UDim2.new(1, -95, 0.5, -13),
					BackgroundColor3 = THEME.chip,
					BorderSizePixel = 0,
					Text = default ~= "" and tostring(default) or "None",
					TextColor3 = THEME.text,
					TextSize = 12,
					Font = FONT_MEDIUM,
					AutoButtonColor = false,
				}, card)
				round(chip, 5)
				local chipStroke = create("UIStroke", {
					Color = THEME.outline,
					Transparency = 0.35,
					ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
				}, chip)

				local listening = false
				local current = nil

				local function applyName(name, silent)
					current = keyCodeFromName(name)
					chip.Text = current and current.Name or "None"
					Hub.Values[flag] = current and name or ""
					Hub.Keybinds[flag] = current
					if not silent then
						Hub:_refreshHints()
					end
				end

				applyName(default, true)

				local entry = { Flag = flag, Kind = "keybind", Card = card, Set = applyName }
				Hub.Setters[flag] = applyName
				Hub.Defaults[flag] = default
				Hub.Values[flag] = default
				table.insert(Hub._entries, entry)

				chip.MouseEnter:Connect(function()
					retween(chipStroke, ANIM.fast, { Color = colorA, Transparency = 0 })
				end)
				chip.MouseLeave:Connect(function()
					if not listening then
						retween(chipStroke, ANIM.fast, { Color = THEME.outline, Transparency = 0.35 })
					end
				end)

				chip.Activated:Connect(function()
					if Hub._cancelListening then
						Hub._cancelListening()
					end
					listening = true
					chip.Text = "Press a key"
					retween(chipStroke, ANIM.fast, { Color = colorA, Transparency = 0 })

					Hub._cancelListening = function()
						listening = false
						Hub._cancelListening = nil
						Hub._listening = nil
						retween(chipStroke, ANIM.fast, { Color = THEME.outline, Transparency = 0.35 })
						chip.Text = current and tostring(current.Name) or "None"
					end

					Hub._listening = function(keyCode)
						listening = false
						Hub._cancelListening = nil
						-- Release the global slot: while _listening is set, every
						-- keypress in the game is routed here instead of the menu
						-- hotkey, so a session that never clears it silently kills
						-- RightShift until the hub is reloaded.
						Hub._listening = nil
						retween(chipStroke, ANIM.fast, { Color = THEME.outline, Transparency = 0.35 })
						applyName(keyCode == Enum.KeyCode.Escape and "" or keyCode.Name)
					end
				end)

				-- The hub routes a press here only when the chip owns it.
				entry.HandleKey = function(keyCode)
					if listening then
						Hub._listening(keyCode)
						return true
					end
					if current and keyCode == current and onKey then
						task.spawn(pcall, onKey, keyCode)
						return true
					end
					return false
				end

				table.insert(Hub.Searchables, card)
				return card
			end

			---Action button row.
			function Components.Button(parent, options)
				options = options or {}
				local text = options.Text or options.Name or "Button"
				local callback = options.Callback
				local danger = options.Danger == true

				local card = createCard(parent, text, 36, false)
				local button = create("TextButton", {
					Size = UDim2.new(1, -16, 0, 26),
					Position = UDim2.fromOffset(8, 5),
					BackgroundColor3 = THEME.element,
					BorderSizePixel = 0,
					Text = text,
					TextColor3 = danger and THEME.negative or THEME.textOff,
					TextSize = 12,
					Font = FONT_MEDIUM,
					AutoButtonColor = false,
				}, card)
				round(button, 5)
				local stroke = create("UIStroke", {
					Color = danger and THEME.negative or THEME.outline,
					Transparency = 0.55,
					ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
				}, button)

				button.MouseEnter:Connect(function()
					retween(stroke, ANIM.fast, { Color = danger and THEME.negative or colorA, Transparency = 0 })
					retween(button, ANIM.fast, { BackgroundColor3 = THEME.elementHover })
				end)
				button.MouseLeave:Connect(function()
					retween(stroke, ANIM.fast, { Color = danger and THEME.negative or THEME.outline, Transparency = 0.55 })
					retween(button, ANIM.fast, { BackgroundColor3 = THEME.element })
				end)
				button.MouseButton1Down:Connect(function()
					retween(button, ANIM.fast, { BackgroundColor3 = shade(THEME.elementHover, 0.12) })
				end)
				button.MouseButton1Up:Connect(function()
					retween(button, ANIM.fast, { BackgroundColor3 = THEME.elementHover })
				end)

				button.Activated:Connect(function()
					if callback then
						local ok, err = pcall(callback)
						if not ok then
							Hub:Notify(text, "error", tostring(err))
						end
					end
				end)

				table.insert(Hub.Searchables, card)
				return card
			end

			---Collapsible group: a header that shows or hides the rows added after it.
			function Components.Group(parent, options)
				options = options or {}
				local text = options.Text or "Options"
				local collapsed = options.Collapsed ~= false

				-- The header belongs to the parent, not to the group it opens: clear the
				-- open group first or the header adopts itself and hides on collapse.
				local parentGroup = Hub._currentGroup
				Hub._currentGroup = nil
				local group = { cards = {}, collapsed = collapsed }
				local card = createCard(parent, text, 32, false)
				Hub._currentGroup = group
				group.parent = parentGroup
				local button = create("TextButton", {
					Size = UDim2.new(1, -16, 0, 24),
					Position = UDim2.fromOffset(8, 4),
					BackgroundColor3 = THEME.element,
					BorderSizePixel = 0,
					Text = (collapsed and "+   " or "-   ") .. text,
					TextColor3 = THEME.textOff,
					TextSize = 12,
					Font = FONT_MEDIUM,
					AutoButtonColor = false,
					TextXAlignment = Enum.TextXAlignment.Left,
				}, card)
				round(button, 5)
				create("UIPadding", { PaddingLeft = UDim.new(0, 8) }, button)
				local stroke = create("UIStroke", {
					Color = THEME.outline,
					Transparency = 0.55,
					ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
				}, button)

				button.MouseEnter:Connect(function()
					retween(stroke, ANIM.fast, { Color = colorA, Transparency = 0 })
				end)
				button.MouseLeave:Connect(function()
					retween(stroke, ANIM.fast, { Color = THEME.outline, Transparency = 0.55 })
				end)

				button.Activated:Connect(function()
					group.collapsed = not group.collapsed
					button.Text = (group.collapsed and "+   " or "-   ") .. text
					for _, child in group.cards do
						child.Visible = not group.collapsed
					end
				end)

				Hub._currentGroup = group
				return group
			end

			---Close the group opened by Components.Group.
			function Components.EndGroup()
				Hub._currentGroup = nil
			end

			---Colour swatch row: cycles the palette and exposes the raw Color3.
			function Components.ColorPicker(parent, options)
				options = options or {}
				local text = options.Text or "Color"
				local flag = options.Flag or text
				local palette = options.Palette or {
					Color3.fromRGB(255, 255, 255),
					Color3.fromRGB(255, 92, 96),
					Color3.fromRGB(124, 222, 146),
					Color3.fromRGB(96, 156, 255),
					Color3.fromRGB(255, 212, 90),
					Color3.fromRGB(196, 122, 255),
				}
				local callback = options.Callback
				local index = math.max(1, table.find(palette, options.Default) or 1)

				local card = createCard(parent, flag, 40, true)

				create("TextLabel", {
					Size = UDim2.new(1, -70, 1, 0),
					Position = UDim2.fromOffset(11, 0),
					BackgroundTransparency = 1,
					Text = text,
					TextColor3 = THEME.text,
					TextSize = TEXT_SIZE.label,
					Font = FONT,
					TextXAlignment = Enum.TextXAlignment.Left,
				}, card)

				local swatch = create("Frame", {
					AnchorPoint = Vector2.new(1, 0.5),
					Size = UDim2.fromOffset(38, 18),
					Position = UDim2.new(1, -11, 0.5, 0),
					BackgroundColor3 = palette[index],
					BorderSizePixel = 0,
				}, card)
				round(swatch, 5)
				create("UIStroke", {
					Color = THEME.outline,
					Transparency = 0.3,
					ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
				}, swatch)

				local entry = { Flag = flag, Kind = "color", Card = card, Set = nil }

				local function set(value, silent)
					if typeof(value) == "Color3" then
						table.insert(palette, 1, value)
						index = 1
					else
						local found = table.find(palette, value)
						if not found then
							return
						end
						index = found
					end
					Hub.Values[flag] = palette[index]
					swatch.BackgroundColor3 = palette[index]
					if not silent and callback then
						task.spawn(pcall, callback, palette[index])
					end
				end

				entry.Set = set
				Hub.Setters[flag] = set
				Hub.Defaults[flag] = palette[index]
				Hub.Values[flag] = palette[index]
				table.insert(Hub._entries, entry)

				card.Activated:Connect(function()
					index = index % #palette + 1
					Hub.Values[flag] = palette[index]
					swatch.BackgroundColor3 = palette[index]
					if callback then
						task.spawn(pcall, callback, palette[index])
					end
				end)

				table.insert(Hub.Searchables, card)
				return card
			end

			---Dimmed descriptive paragraph.
			---Plain wrapped caption. The card grows with its text instead of being a
			---fixed 34 px: a three-line notice used to clip its last line, which the
			---design audit reports as text-overflow.
			function Components.Label(parent, text)
				local card = createCard(parent, tostring(text), 34, false)
				card.BackgroundTransparency = 1
				card.AutomaticSize = Enum.AutomaticSize.Y

				local label = create("TextLabel", {
					Size = UDim2.new(1, -18, 0, 0),
					Position = UDim2.fromOffset(9, 4),
					BackgroundTransparency = 1,
					Text = tostring(text),
					TextColor3 = THEME.textDim,
					TextSize = 12,
					Font = FONT,
					TextWrapped = true,
					TextXAlignment = Enum.TextXAlignment.Left,
					TextYAlignment = Enum.TextYAlignment.Top,
					AutomaticSize = Enum.AutomaticSize.Y,
				}, card)

				-- The card gets the label's wrapped height. TextBounds is computed by
				-- the engine from the label's own width, and a label that is still
				-- auto-sizing reports what it has so far; a zero height here used to
				-- collapse the whole card, taking the caption with it. One line of
				-- 12 px text is the floor.
				local bounds = label.TextBounds
				-- Rounded up: TextBounds carries fractional pixels from the font
				-- metrics, and a card 0.03px shorter than its caption reads as a clip
				-- to the design audit (and to a picky eye at 2x).
				local textHeight = math.ceil(math.max(bounds.Y, TEXT_SIZE.label))
				card.Size = UDim2.new(1, 0, 0, textHeight + 8)
				-- Explicit height: with AutomaticSize.Y *and* a fixed size, the
				-- engine keeps the fixed height, which is what the harness measures.
				label.AutomaticSize = Enum.AutomaticSize.None
				label.Size = UDim2.new(1, -18, 0, textHeight)

				return card
			end

			---A status row: dot + text, no card, no interaction. Used for the
			---executor/library readout where a card would look like a button.
			function Components.Status(parent, text, state)
				local colors = {
					on = THEME.positive,
					off = THEME.negative,
					warn = THEME.accentAlt,
					info = colorA,
				}
				local dotColor = colors[state or "info"] or colorA

				local row = create("Frame", {
					Name = tostring(text),
					Size = UDim2.new(1, 0, 0, 22),
					BackgroundTransparency = 1,
					LayoutOrder = parent and parent:GetAttribute("CardCount") or nil,
				}, parent)
				if parent then
					parent:SetAttribute("CardCount", (parent:GetAttribute("CardCount") or 0) + 1)
				end
				adoptIntoGroup(row)
				row:SetAttribute("SearchText", tostring(text))

				local dot = create("Frame", {
					Size = UDim2.fromOffset(6, 6),
					Position = UDim2.fromOffset(4, 8),
					BackgroundColor3 = dotColor,
					BorderSizePixel = 0,
				}, row)
				round(dot, 999)

				create("TextLabel", {
					Size = UDim2.new(1, -20, 1, 0),
					Position = UDim2.fromOffset(16, 0),
					BackgroundTransparency = 1,
					Text = tostring(text),
					TextColor3 = THEME.textOff,
					TextSize = TEXT_SIZE.label,
					Font = FONT,
					TextXAlignment = Enum.TextXAlignment.Left,
					TextTruncate = Enum.TextTruncate.AtEnd,
				}, row)

				table.insert(Hub.Searchables, row)
				return row
			end

			---Scrolling code block. `lines` is a list of strings; `highlight` is an
			---optional function(line, index) -> Color3 to tint a line (the script
			---viewer uses it for matches).
			function Components.CodeView(parent, options)
				options = options or {}
				local lines = options.Lines or {}
				local height = options.Height or 220

				local holder = create("Frame", {
					Name = options.Text or "Code",
					Size = UDim2.new(1, 0, 0, height),
					BackgroundColor3 = THEME.element,
					BackgroundTransparency = 0.25,
					BorderSizePixel = 0,
					ClipsDescendants = true,
					LayoutOrder = parent and parent:GetAttribute("CardCount") or nil,
				}, parent)
				if parent then
					parent:SetAttribute("CardCount", (parent:GetAttribute("CardCount") or 0) + 1)
				end
				round(holder, CONFIG.cardRadius)
				create("UIStroke", {
					Color = THEME.outline,
					Transparency = 0.7,
					ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
				}, holder)

				local scroll = create("ScrollingFrame", {
					Size = UDim2.new(1, -8, 1, -8),
					Position = UDim2.fromOffset(4, 4),
					BackgroundTransparency = 1,
					BorderSizePixel = 0,
					ScrollBarThickness = 3,
					ScrollBarImageColor3 = THEME.outline,
					ScrollBarImageTransparency = 0.4,
					CanvasSize = UDim2.new(0, 0, 0, 0),
					-- A decompiled line is routinely wider than the panel, and
					-- truncating source in a source viewer is the one thing a viewer
					-- must not do. AutomaticCanvasSize grows the canvas with the rows;
					-- the frame scrolls both ways so long lines stay reachable.
					AutomaticCanvasSize = Enum.AutomaticSize.XY,
					ScrollingDirection = Enum.ScrollingDirection.XY,
				}, holder)

				create("UIListLayout", {
					Padding = UDim.new(0, 0),
					SortOrder = Enum.SortOrder.LayoutOrder,
				}, scroll)
				create("UIPadding", { PaddingLeft = UDim.new(0, 8), PaddingTop = UDim.new(0, 6) }, scroll)

				local renderLine = function(index, text)
					local color = THEME.textOff
					if options.Highlight then
						local ok, tinted = pcall(options.Highlight, text, index)
						if ok and typeof(tinted) == "Color3" then
							color = tinted
						end
					end
					local row = create("TextLabel", {
						-- Width from the text, not from the panel: the row grows and the
						-- scroll frame lets it run off to the right. Truncating a line of
						-- source is the one thing a source viewer must not do.
						Size = UDim2.new(0, 0, 0, TEXT_SIZE.code + 4),
						AutomaticSize = Enum.AutomaticSize.X,
						BackgroundTransparency = 1,
						Text = ("%3d  %s"):format(index, text),
						TextColor3 = color,
						TextSize = TEXT_SIZE.code,
						Font = FONT_MONO,
						TextXAlignment = Enum.TextXAlignment.Left,
						TextTruncate = Enum.TextTruncate.None,
					}, scroll)
					return row
				end

				local rendered = 0
				local function append(chunk)
					for _, line in chunk do
						rendered += 1
						renderLine(rendered, line)
						if options.MaxLines and rendered >= options.MaxLines then
							return
						end
					end
				end

				append(lines)

				---Replace the whole body. Cheap enough for a few thousand lines and
				---it keeps the canvas in step with the content.
				local function setLines(nextLines, nextHighlight)
					for _, child in scroll:GetChildren() do
						if child:IsA("TextLabel") then
							child:Destroy()
						end
					end
					lines = nextLines or {}
					options.Highlight = nextHighlight or options.Highlight
					rendered = 0
					append(lines)
					holder:SetAttribute("LineCount", rendered)
				end

				---Append without rebuilding, for streaming logs.
				local function push(line)
					rendered += 1
					renderLine(rendered, line)
					holder:SetAttribute("LineCount", rendered)
				end

				holder:SetAttribute("LineCount", rendered)
				holder.setLines = setLines
				holder.push = push
				holder.scroll = scroll
				holder.SetLines = setLines
				holder.Push = push
				return holder
			end

			---Thin divider.
			function Components.Divider(parent)
				local holder = create("Frame", {
					Size = UDim2.new(1, 0, 0, 8),
					BackgroundTransparency = 1,
					LayoutOrder = #parent:GetChildren() + 1,
				}, parent)
				local line = create("Frame", {
					Size = UDim2.new(1, -12, 0, 1),
					Position = UDim2.fromOffset(6, 3),
					BackgroundColor3 = THEME.outline,
					BackgroundTransparency = 0.6,
					BorderSizePixel = 0,
				}, holder)
				-- Fade the divider in and out at its ends: keypoints, not three numbers.
				create("UIGradient", {
					Transparency = NumberSequence.new({
						NumberSequenceKeypoint.new(0, 1),
						NumberSequenceKeypoint.new(0.5, 0.2),
						NumberSequenceKeypoint.new(1, 1),
					}),
				}, line)
				return holder
			end

			-- ======================================================================
			-- Section surface
			-- ======================================================================
			-- Components.Section returns the box frame; this wraps it so callers write
			-- box:Toggle{...} instead of Components.Toggle(box, {...}). Every method is
			-- a thin forwarder: no state lives here, the box frame is still the parent
			-- and reaching `box.frame` gives the raw GUI object.
			local Section = {}
			Section.__index = Section

			local function sectionSurface(box, page)
				return setmetatable({ frame = box, page = page, columns = page and page.columns }, Section)
			end

			function Section:Toggle(options)
				return Components.Toggle(self.frame, options)
			end

			function Section:Slider(options)
				return Components.Slider(self.frame, options)
			end

			function Section:Cycle(options)
				return Components.Cycle(self.frame, options)
			end

			function Section:Dropdown(options)
				return Components.Dropdown(self.frame, options)
			end

			function Section:Input(options)
				return Components.Input(self.frame, options)
			end

			function Section:Keybind(options)
				return Components.Keybind(self.frame, options)
			end

			function Section:Button(options)
				return Components.Button(self.frame, options)
			end

			function Section:Color(options)
				return Components.ColorPicker(self.frame, options)
			end

			---Alias: the row is a colour picker, `Color` reads better on a chain.
			Section.ColorPicker = Section.Color

			function Section:Status(text, state)
				return Components.Status(self.frame, text, state)
			end

			function Section:Code(options)
				return Components.CodeView(self.frame, options)
			end

			function Section:Label(text)
				return Components.Label(self.frame, text)
			end

			function Section:Divider()
				return Components.Divider(self.frame)
			end

			---Nested group box inside this section.
			function Section:Section(text)
				return sectionSurface(Components.Section(self.frame, text), self.page)
			end

			---Collapsible group; the following rows join it until EndGroup().
			function Section:Group(options)
				return Components.Group(self.frame, options)
			end

			function Section:EndGroup()
				Components.EndGroup()
			end

			-- ======================================================================
			-- Page (tab body)
			-- ======================================================================
			local Page = {}
			Page.__index = Page

			---One scrolling column. Two columns by default so rows never stretch.
			function Page:Column(index, count)
				local total = count or 2
				local width = 1 / total
				-- One 6 px gutter between columns, 4 px reserved for the scrollbar, so
				-- both columns end up exactly the same width.
				local gutter = (index < total) and 3 or 0
				local column = create("ScrollingFrame", {
					Size = UDim2.new(width, -6 - gutter, 1, 0),
					Position = UDim2.new((index - 1) * width, (index - 1) * 6 + gutter, 0, 0),
					BackgroundTransparency = 1,
					BorderSizePixel = 0,
					ScrollBarThickness = 2,
					ScrollBarImageColor3 = THEME.outline,
					ScrollBarImageTransparency = 0.4,
					CanvasSize = UDim2.new(),
					AutomaticCanvasSize = Enum.AutomaticSize.Y,
					ScrollingDirection = Enum.ScrollingDirection.Y,
				}, self.frame)
				create("UIListLayout", {
					Padding = UDim.new(0, 5),
					SortOrder = Enum.SortOrder.LayoutOrder,
				}, column)
				create("UIPadding", {
					PaddingRight = UDim.new(0, 4),
					PaddingBottom = UDim.new(0, 6),
				}, column)
				return column
			end

			---Section box in a column (default: first column). Returns a section
			---surface: box:Toggle{...}, box:Slider{...}, box:Group{...}.
			function Page:Section(text, columnIndex)
				local target = self.columns[columnIndex or 1]
				return sectionSurface(Components.Section(target, text), self)
			end

			---Single-column scroll area that spans the full body.
			function Page:FullColumn()
				self.columns[1] = self:Column(1, 1)
				return self.columns[1]
			end

			-- ======================================================================
			-- Window
			-- ======================================================================
			local Window = {}
			Window.__index = Window

			---Switch the visible tab.
			function Window:SelectTab(name)
				if not self.pages[name] then
					return
				end
				for pageName, page in self.pages do
					local selected = pageName == name
					if selected and not page.frame.Visible then
						page.frame.Visible = true
						page.frame.GroupTransparency = 1
						tween(page.frame, ANIM.open, { GroupTransparency = 0 })
					elseif not selected then
						page.frame.Visible = false
					end
					retween(self.tabButtons[pageName], ANIM.fast, {
						TextColor3 = selected and THEME.text or THEME.textDim,
					})
					retween(self.tabUnderline[pageName], ANIM.fast, {
						BackgroundTransparency = selected and 0 or 1,
					})
				end
				self.selected = name
				tween(self.indicator, ANIM.medium, {
					Position = UDim2.new((self.tabIndexes[name] - 1) / #self.tabNames, 6, 0, 3),
				})
			end

			function Window:Tab(name)
				return self.pages[name]
			end

			---Hub-level convenience: the loader and game modules call Hub:Toggle()
			---rather than reaching into Hub._window.
			function Hub:Toggle()
				if Hub._window then
					Hub._window:Toggle()
				end
			end

			function Hub:Minimize()
				if Hub._window then
					Hub._window:ToggleMinimize()
				end
			end

			function Hub:SelectTab(name)
				if Hub._window then
					Hub._window:SelectTab(name)
				end
			end

			---Add a tab after the window exists (used by game modules).
			function Window:AddTab(name)
				if self.pages[name] then
					return self.pages[name]
				end
				table.insert(self.tabNames, name)
				self:_buildTab(name, #self.tabNames)
				self:_layoutTabs()
				self:SelectTab(name)
				return self.pages[name]
			end

			function Window:_layoutTabs()
				local count = #self.tabNames
				for index, name in self.tabNames do
					local button = self.tabButtons[name]
					button.Size = UDim2.fromScale(1 / count, 1)
					button.Position = UDim2.fromScale((index - 1) / count, 0)
					self.tabIndexes[name] = index
				end
				self.indicator.Size = UDim2.new(1 / count, -12, 1, -6)
				local selected = self.selected or self.tabNames[1]
				self.indicator.Position = UDim2.new((self.tabIndexes[selected] - 1) / count, 6, 0, 3)
			end

			function Window:_buildTab(name, index)
				local count = #self.tabNames
				local button = create("TextButton", {
					Size = UDim2.fromScale(1 / count, 1),
					Position = UDim2.fromScale((index - 1) / count, 0),
					BackgroundTransparency = 1,
					Text = name,
					TextColor3 = THEME.textDim,
					TextSize = TEXT_SIZE.tab,
					Font = FONT_MEDIUM,
					AutoButtonColor = false,
				}, self.tabBar)

				local underline = create("Frame", {
					AnchorPoint = Vector2.new(0.5, 1),
					Size = UDim2.new(0.42, 0, 0, 2),
					Position = UDim2.fromScale(0.5, 1),
					BackgroundColor3 = Color3.new(1, 1, 1),
					BackgroundTransparency = 1,
					BorderSizePixel = 0,
				}, button)
				round(underline, 999)
				liveGradient(underline, 0)

				local frame = create("CanvasGroup", {
					Size = UDim2.fromScale(1, 1),
					BackgroundTransparency = 1,
					Visible = false,
				}, self.content)

				button.MouseEnter:Connect(function()
					if self.selected ~= name then
						retween(button, ANIM.fast, { TextColor3 = THEME.textOff })
					end
				end)
				button.MouseLeave:Connect(function()
					if self.selected ~= name then
						retween(button, ANIM.fast, { TextColor3 = THEME.textDim })
					end
				end)
				button.Activated:Connect(function()
					self:SelectTab(name)
				end)

				self.tabButtons[name] = button
				self.tabUnderline[name] = underline
				self.tabIndexes[name] = index

				local page = setmetatable({ name = name, frame = frame, columns = {} }, Page)
				page.columns[1] = page:Column(1, 2)
				page.columns[2] = page:Column(2, 2)
				self.pages[name] = page
				return page
			end

			---Minimise or restore the window body.
			function Window:ToggleMinimize()
				self.minimized = not self.minimized
				self.resizeHandle.Visible = not self.minimized
				self.body.Visible = not self.minimized
				tween(self.frame, ANIM.medium, {
					Size = UDim2.fromOffset(self.width, self.minimized and CONFIG.titleHeight or self.height),
				})
			end

			---Restore the default size and centre the window.
			function Window:ResetPosition()
				self.width, self.height = CONFIG.width, CONFIG.height
				self.minimized = false
				self.body.Visible = true
				self.resizeHandle.Visible = true
				tween(self.frame, ANIM.medium, {
					Size = UDim2.fromOffset(self.width, self.height),
					Position = UDim2.new(0.5, -self.width / 2, 0.5, -self.height / 2),
				})
			end

			function Window:Toggle()
				self.frame.Visible = not self.frame.Visible
				if self.frame.Visible then
					local scale = self.frame:FindFirstChildOfClass("UIScale")
					if scale then
						scale.Scale = 0.94
						retween(scale, ANIM.pop, { Scale = 1 })
					end
					-- Re-clamp every open: a resolution change while hidden can strand
					-- the window off screen.
					task.defer(clampToViewport, self.frame)
				end
			end

			-- ======================================================================
			-- Build the window
			-- ======================================================================

			---Rebuild the whole interface. Called once by the loader and again by
			---Hub:Rebuild() when the tab list changes.
			local function buildWindow()
				-- Prefer the hidden GUI container when the executor provides one: some
				-- games' anticheat only skims PlayerGui.
				local guiParent = localPlayer and localPlayer:FindFirstChild("PlayerGui") or nil
				if typeof(gethui) == "function" then
					local ok, hidden = pcall(gethui)
					if ok and hidden then
						guiParent = hidden
					end
				end

				local screen = create("ScreenGui", {
					Name = "FatCatHub",
					ResetOnSpawn = false,
					IgnoreGuiInset = true,
					DisplayOrder = UIELEMENT,
					ZIndexBehavior = Enum.ZIndexBehavior.Sibling,
				}, guiParent)
				Hub._screen = screen

				-- Every global listener dies with the GUI.
				connect(screen.Destroying, function()
					for _, connection in Hub.Connections do
						pcall(function()
							connection:Disconnect()
						end)
					end
					table.clear(Hub.Connections)
					if _G.FatCatHub == Hub then
						_G.FatCatHub = nil
					end
				end)

				local window = setmetatable({
					pages = {},
					tabButtons = {},
					tabUnderline = {},
					tabIndexes = {},
					-- _initOptions, not CONFIG.tabs: a mounted project names its own
					-- first tab before the window is built, and CONFIG.tabs was
					-- captured when this chunk loaded.
					tabNames = table.clone((Hub._initOptions and Hub._initOptions.Tabs) or CONFIG.tabs),
					width = CONFIG.width,
					height = CONFIG.height,
					minimized = false,
					screen = screen,
				}, Window)
				Hub._window = window

				local frame = create("Frame", {
					Name = "Window",
					Size = UDim2.fromOffset(CONFIG.width, CONFIG.height),
					Position = UDim2.new(0.5, -CONFIG.width / 2, 0.5, -CONFIG.height / 2),
					BackgroundColor3 = Color3.new(1, 1, 1),
					BorderSizePixel = 0,
					ClipsDescendants = true,
				}, screen)
				window.frame = frame
				round(frame, CONFIG.cornerRadius)

				create("UIGradient", {
					Color = ColorSequence.new(THEME.backgroundTop, THEME.backgroundBottom),
					Rotation = 90,
				}, frame)

				local windowStroke = create("UIStroke", {
					Color = THEME.outline,
					Transparency = 0.35,
					Thickness = 1.5,
					ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
				}, frame)
				liveGradient(windowStroke, 45)

				-- Soft drop shadow: three offset frames, cheap enough to keep on a
				-- 60 fps UI and it stops the window floating flat over bright maps.
				-- The layers live inside one invisible host that mirrors the window
				-- frame: shadows parented straight to the screen used to stay behind
				-- when the window moved or hid, leaving a ghost rectangle "printed"
				-- on the map at the old position.
				local shadowHost = create("Frame", {
					Name = "Shadow",
					Size = frame.Size,
					Position = frame.Position,
					BackgroundTransparency = 1,
					BorderSizePixel = 0,
					ZIndex = -1,
				}, screen)
				window.shadow = shadowHost
				for _, layer in { { offset = 2, alpha = 0.86 }, { offset = 5, alpha = 0.92 }, { offset = 9, alpha = 0.96 } } do
					local shadow = create("Frame", {
						Size = UDim2.new(1, 0, 1, 0),
						Position = UDim2.fromOffset(layer.offset, layer.offset),
						BackgroundColor3 = Color3.new(0, 0, 0),
						BackgroundTransparency = layer.alpha,
						BorderSizePixel = 0,
					}, shadowHost)
					round(shadow, CONFIG.cornerRadius)
				end

				-- One mirror for every way the frame can move: drags, clamps, the
				-- minimise tween and ResetPosition all go through these properties.
				local function syncShadowHost()
					shadowHost.Size = frame.Size
					shadowHost.Position = frame.Position
					shadowHost.Visible = frame.Visible
				end
				connect(frame:GetPropertyChangedSignal("Size"), syncShadowHost)
				connect(frame:GetPropertyChangedSignal("Position"), syncShadowHost)
				connect(frame:GetPropertyChangedSignal("Visible"), syncShadowHost)
				syncShadowHost()

				local windowScale = create("UIScale", { Scale = 0.94 }, frame)
				retween(windowScale, ANIM.pop, { Scale = 1 })

				-- ---------------------------------------------------------------- title
				-- A label-less TextButton: the drag surface has to hit-test while
				-- staying completely invisible, and a plain Frame does not guarantee
				-- that once its background is fully transparent. No sheen, no gloss
				-- gradient, no hairline over the tabs either: every semi-transparent
				-- overlay up here used to leak a pale square past the rounded corner
				-- and read as a dirty line over the tab strip. The title bar is now
				-- transparent, period.
				local titleBar = create("TextButton", {
					Size = UDim2.new(1, 0, 0, CONFIG.titleHeight),
					BackgroundTransparency = 1,
					BorderSizePixel = 0,
					Text = "",
					AutoButtonColor = false,
				}, frame)

				-- Brand dot: green is the injection light. Green means the library
				-- is live, so it ships green and the breathe never fades it past a
				-- quarter transparent - a dot that washes out reads as "not injected".
				local brand = create("Frame", {
					Size = UDim2.fromOffset(9, 9),
					Position = UDim2.fromOffset(14, CONFIG.titleHeight / 2 - 4.5),
					BackgroundColor3 = THEME.positive,
					BorderSizePixel = 0,
				}, titleBar)
				round(brand, 999)
				tweenService:Create(
					brand,
					TweenInfo.new(2.2, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut, -1, true),
					{ BackgroundTransparency = 0.22 }
				):Play()
				window.brand = brand

				local titleLabel = create("TextLabel", {
					Size = UDim2.new(1, -220, 1, 0),
					Position = UDim2.fromOffset(30, 0),
					BackgroundTransparency = 1,
					Text = CONFIG.title,
					TextColor3 = THEME.text,
					TextSize = TEXT_SIZE.title,
					Font = FONT_BOLD,
					TextXAlignment = Enum.TextXAlignment.Left,
					TextTruncate = Enum.TextTruncate.AtEnd,
				}, titleBar)
				window.titleLabel = titleLabel

				-- Search field: magnifier on the left, clear button on the right, and
				-- it grows to the left on focus so the title bar buttons never move.
				local SEARCH_W, SEARCH_H, SEARCH_WIDE = 150, 26, 190
				local searchBox = create("TextBox", {
					Size = UDim2.fromOffset(SEARCH_W, SEARCH_H),
					Position = UDim2.new(1, -78 - SEARCH_W, 0.5, -SEARCH_H / 2),
					BackgroundColor3 = THEME.element,
					BackgroundTransparency = 0,
					BorderSizePixel = 0,
					PlaceholderText = CONFIG.searchPlaceholder,
					PlaceholderColor3 = THEME.textDim,
					Text = "",
					TextColor3 = THEME.text,
					TextSize = 12,
					Font = FONT,
					ClearTextOnFocus = false,
					TextXAlignment = Enum.TextXAlignment.Left,
				}, titleBar)
				round(searchBox, 7)
				create("UIPadding", { PaddingLeft = UDim.new(0, 25), PaddingRight = UDim.new(0, 24) }, searchBox)
				local searchStroke = create("UIStroke", {
					Color = THEME.outline,
					Transparency = 0.55,
					ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
				}, searchBox)
				window.searchBox = searchBox

				-- Magnifier: a stroked ring plus a rotated handle. Drawn, not a font
				-- glyph, because Gotham has no magnifier and a missing glyph renders
				-- as a blank box on some clients.
				local searchIcon = create("Frame", {
					Name = "Icon",
					Size = UDim2.fromOffset(9, 9),
					Position = UDim2.fromOffset(9, SEARCH_H / 2 - 6),
					BackgroundTransparency = 1,
					BorderSizePixel = 0,
				}, searchBox)
				local iconRing = create("UIStroke", {
					Color = THEME.textDim,
					Transparency = 0.15,
					Thickness = 1.4,
				}, searchIcon)
				round(searchIcon, 999)
				local iconHandle = create("Frame", {
					AnchorPoint = Vector2.new(0.5, 0.5),
					Size = UDim2.fromOffset(5, 1.4),
					Position = UDim2.fromOffset(12.5, SEARCH_H / 2 + 4),
					BackgroundColor3 = THEME.textDim,
					BorderSizePixel = 0,
					Rotation = 45,
				}, searchBox)
				round(iconHandle, 999)

				-- Clear button: pinned to the right edge of the field, which never
				-- moves, so it can live beside the box instead of riding the tween.
				local searchClear = create("TextButton", {
					Name = "ClearSearch",
					Size = UDim2.fromOffset(18, 18),
					Position = UDim2.new(1, -96, 0.5, -9),
					BackgroundColor3 = THEME.elementHover,
					BackgroundTransparency = 1,
					BorderSizePixel = 0,
					Text = "×",
					TextColor3 = THEME.textOff,
					TextSize = 13,
					Font = FONT_BOLD,
					AutoButtonColor = false,
					Visible = false,
				}, titleBar)
				round(searchClear, 999)
				searchClear.MouseEnter:Connect(function()
					retween(searchClear, ANIM.fast, { BackgroundTransparency = 0.2, TextColor3 = THEME.text })
				end)
				searchClear.MouseLeave:Connect(function()
					retween(searchClear, ANIM.fast, { BackgroundTransparency = 1, TextColor3 = THEME.textOff })
				end)
				searchClear.Activated:Connect(function()
					searchBox.Text = ""
					searchBox:CaptureFocus()
				end)
				searchBox:GetPropertyChangedSignal("Text"):Connect(function()
					searchClear.Visible = searchBox.Text ~= ""
				end)

				local searchFocused = false
				window.isSearchFocused = function()
					return searchFocused
				end
				searchBox.Focused:Connect(function()
					searchFocused = true
					retween(searchStroke, ANIM.fast, { Color = colorA, Transparency = 0 })
					iconRing.Color = colorA
					iconHandle.BackgroundColor3 = colorA
					retween(searchBox, ANIM.medium, {
						BackgroundColor3 = THEME.elementHover,
						Size = UDim2.fromOffset(SEARCH_WIDE, SEARCH_H),
						Position = UDim2.new(1, -78 - SEARCH_WIDE, 0.5, -SEARCH_H / 2),
					})
				end)
				searchBox.FocusLost:Connect(function()
					searchFocused = false
					retween(searchStroke, ANIM.fast, { Color = THEME.outline, Transparency = 0.55 })
					iconRing.Color = THEME.textDim
					iconHandle.BackgroundColor3 = THEME.textDim
					retween(searchBox, ANIM.medium, {
						BackgroundColor3 = THEME.element,
						Size = UDim2.fromOffset(SEARCH_W, SEARCH_H),
						Position = UDim2.new(1, -78 - SEARCH_W, 0.5, -SEARCH_H / 2),
					})
				end)

				---Title bar button.
				local function titleButton(text, offset, hoverColor)
					local button = create("TextButton", {
						-- 28 wide with a 2px gap between the two, so the pair fills the
						-- right edge of the bar instead of floating in it.
						Size = UDim2.fromOffset(28, 24),
						Position = UDim2.new(1, offset, 0.5, -12),
						BackgroundColor3 = THEME.element,
						BackgroundTransparency = 0.35,
						BorderSizePixel = 0,
						Text = text,
						TextColor3 = THEME.textOff,
						TextSize = 16,
						Font = FONT_BOLD,
						AutoButtonColor = false,
					}, titleBar)
					round(button, 6)

					button.MouseEnter:Connect(function()
						retween(button, ANIM.fast, { BackgroundColor3 = hoverColor, BackgroundTransparency = 0.05 })
						retween(button, ANIM.fast, { TextColor3 = THEME.text })
					end)
					button.MouseLeave:Connect(function()
						retween(button, ANIM.fast, { BackgroundColor3 = THEME.element, BackgroundTransparency = 0.35 })
						retween(button, ANIM.fast, { TextColor3 = THEME.textOff })
					end)
					return button
				end

				-- En dashes and a multiplication sign: a hyphen and the letter x look
				-- thin and off-centre next to each other at this size.
				local minimizeButton = titleButton("–", -62, THEME.accentAlt)
				local closeButton = titleButton("×", -32, THEME.negative)

				-- ------------------------------------------------------------ drag
				local dragStart, startPosition
				titleBar.InputBegan:Connect(function(input)
					if not isPress(input) then
						return
					end
					dragStart = input.Position
					startPosition = frame.Position
				end)
				connect(userInputService.InputChanged, function(input)
					if not dragStart or not isMove(input) then
						return
					end
					-- The shadow host mirrors frame.Position through a property
					-- signal, so the drag never touches it by hand: the old manual
					-- sync moved one layer of three, and with the wrong offset math,
					-- which is what left ghost rectangles on the map.
					local delta = input.Position - dragStart
					frame.Position = UDim2.new(
						startPosition.X.Scale,
						startPosition.X.Offset + delta.X,
						startPosition.Y.Scale,
						startPosition.Y.Offset + delta.Y
					)
				end)
				connect(userInputService.InputEnded, function(input)
					if not isPress(input) or not dragStart then
						return
					end
					dragStart = nil
					clampToViewport(frame)
				end)

				minimizeButton.Activated:Connect(function()
					window:ToggleMinimize()
				end)
				closeButton.Activated:Connect(function()
					tween(windowScale, ANIM.fast, { Scale = 0 }).Completed:Connect(function()
						screen:Destroy()
					end)
				end)

				-- ------------------------------------------------------------- tabs
				local tabBar = create("Frame", {
					Size = UDim2.new(1, 0, 0, CONFIG.tabHeight),
					Position = UDim2.fromOffset(0, CONFIG.titleHeight),
					BackgroundTransparency = 1,
				}, frame)
				window.tabBar = tabBar

				local indicator = create("Frame", {
					Size = UDim2.new(1 / #window.tabNames, -12, 1, -8),
					Position = UDim2.new(0, 6, 0, 4),
					BackgroundColor3 = Color3.new(1, 1, 1),
					BackgroundTransparency = 0.93,
					BorderSizePixel = 0,
				}, tabBar)
				round(indicator, 7)
				create("UIStroke", {
					Color = THEME.outline,
					Transparency = 0.85,
					ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
				}, indicator)
				window.indicator = indicator

				local body = create("CanvasGroup", {
					Name = "Body",
					Size = UDim2.new(1, 0, 1, -(CONFIG.titleHeight + CONFIG.tabHeight + CONFIG.footerHeight)),
					Position = UDim2.fromOffset(0, CONFIG.titleHeight + CONFIG.tabHeight),
					BackgroundTransparency = 1,
				}, frame)
				window.body = body

				local content = create("Frame", {
					Size = UDim2.new(1, -20, 1, -16),
					Position = UDim2.fromOffset(10, 6),
					BackgroundTransparency = 1,
				}, body)
				window.content = content

				-- ------------------------------------------------------------ resize
				local resizeHandle = create("TextButton", {
					AnchorPoint = Vector2.new(1, 1),
					Size = UDim2.fromOffset(20, 20),
					Position = UDim2.fromScale(1, 1),
					BackgroundTransparency = 1,
					Text = "",
					ZIndex = 12,
				}, frame)
				window.resizeHandle = resizeHandle

				-- No grip lines. The corner used to carry three semi-transparent
				-- dashes "to grab it by"; the menu reads cleaner with nothing there,
				-- and the invisible 20x20 button still resizes on drag.
				local resizing = false
				local resizeStart, startWidth, startHeight

				resizeHandle.InputBegan:Connect(function(input)
					if not isPress(input) then
						return
					end
					resizing = true
					resizeStart = input.Position
					startWidth, startHeight = window.width, window.height
				end)
				connect(userInputService.InputChanged, function(input)
					if not resizing or not isMove(input) then
						return
					end
					local delta = input.Position - resizeStart
					window.width = math.clamp(startWidth + delta.X, CONFIG.minWidth, CONFIG.maxWidth)
					window.height = math.clamp(startHeight + delta.Y, CONFIG.minHeight, CONFIG.maxHeight)
					frame.Size = UDim2.fromOffset(window.width, window.height)
				end)
				connect(userInputService.InputEnded, function(input)
					if not resizing or not isPress(input) then
						return
					end
					resizing = false
				end)

				-- ------------------------------------------------------------- search
				---Hide rows that do not match, then collapse empty boxes. Restoring is
				---the same walk with an empty query, so a collapsed group stays
				---collapsed instead of every row popping back.
				local function applySearch(query)
					-- Surrounding spaces never mean anything in a filter.
					local lowered = string.lower(string.match(query or "", "^%s*(.-)%s*$") or "")
					local matched = {}
					for _, card in Hub.Searchables do
						if card.Parent then
							local groupHidden = card:GetAttribute("GroupHidden")
							local haystack = string.lower(tostring(card:GetAttribute("SearchText") or card.Name))
							local hit = lowered == "" or string.find(haystack, lowered, 1, true) ~= nil
							-- A row inside a collapsed group only reappears when the
							-- group itself is open again.
							card.Visible = hit and not groupHidden
							matched[card] = true
						end
					end
					for _, page in window.pages do
						for _, column in page.columns do
							for _, child in column:GetChildren() do
								if child:IsA("Frame") and child:FindFirstChildOfClass("UIListLayout") then
									local any = lowered == ""
									if not any then
										for _, inner in child:GetChildren() do
											if matched[inner] and inner.Visible then
												any = true
												break
											end
										end
									end
									child.Visible = any
								end
							end
						end
					end
				end

				searchBox:GetPropertyChangedSignal("Text"):Connect(function()
					applySearch(searchBox.Text)
				end)
				window.applySearch = applySearch

				-- --------------------------------------------------------------- tabs
				for index, name in window.tabNames do
					window:_buildTab(name, index)
				end
				window:SelectTab(window.tabNames[1])

				-- ---------------------------------------------------------- keybind
				---Key hints row: lists every bound key, toggled with the hints key.
				local hints = create("Frame", {
					Name = "KeyHints",
					AnchorPoint = Vector2.new(0, 1),
					Position = UDim2.new(0, 10, 1, -6),
					Size = UDim2.new(1, -34, 0, 14),
					BackgroundTransparency = 1,
					ZIndex = 5,
				}, frame)
				create("TextLabel", {
					Size = UDim2.fromScale(1, 1),
					BackgroundTransparency = 1,
					Text = "",
					TextColor3 = THEME.textDim,
					TextSize = 11,
					Font = FONT,
					TextXAlignment = Enum.TextXAlignment.Left,
					TextTruncate = Enum.TextTruncate.AtEnd,
				}, hints)
				window.hints = hints

				Hub:_refreshHints()

				local hintsVisible = true
				Hub.SetHintsVisible = function(_, visible)
					hintsVisible = visible
					hints.Visible = visible
				end
				Hub.GetHintsVisible = function()
					return hintsVisible
				end

				connect(userInputService.InputBegan, function(input, gameProcessed)
					if input.UserInputType ~= Enum.UserInputType.Keyboard then
						return
					end

					-- Diagnostics first: whatever happens below, the last key the hub
					-- saw is visible from the console.
					Hub._lastKey = input.KeyCode
					Hub._lastKeyProcessed = gameProcessed == true
					Hub._inputHandler = (Hub._inputHandler or 0) + 1

					-- A keybind chip is waiting for the next key. This runs before the
					-- gameProcessed check on purpose: while typing a new key into a
					-- chip, the game is usually eating the keystroke.
					if Hub._listening then
						local listener = Hub._listening
						Hub._listening = nil
						listener(input.KeyCode)
						return
					end

					-- Escape inside the search field clears it and lets go of the
					-- keyboard. Before the gameProcessed check on purpose again: a
					-- focused TextBox eats every key, Escape included.
					if input.KeyCode == Enum.KeyCode.Escape and window.isSearchFocused and window.isSearchFocused() then
						window.searchBox.Text = ""
						window.searchBox:ReleaseFocus()
						return
					end

					if gameProcessed then
						-- Only for the keys we own: the user pressed the menu key and
						-- Roblox handed the event to the game (a chat box, a TextBox).
						local wanted = matchesKey(input.KeyCode, Hub.menuKey or CONFIG.menuKey)
							or (matchesKey(input.KeyCode, CONFIG.hintsKeys) and isAnyControlDown())
						if wanted and not Hub._processedWarned then
							Hub._processedWarned = true
							Hub:Notify(
								"Key taken by the game",
								"error",
								("Press %s with the chat closed"):format(input.KeyCode.Name)
							)
						end
						return
					end

					if matchesKey(input.KeyCode, CONFIG.hintsKeys) and isAnyControlDown() then
						Hub:SetHintsVisible(not Hub:GetHintsVisible())
						return
					end

					if matchesKey(input.KeyCode, Hub.menuKey or CONFIG.menuKey) then
						-- Go through Hub:Toggle() rather than the closed-over window: a
						-- rebuild replaces Hub._window, and the old frame would be dead.
						Hub:Toggle()
						return
					end

					-- Route the press to whichever keybind owns it.
					for _, entry in Hub._entries do
						if entry.HandleKey and entry.HandleKey(input.KeyCode) then
							return
						end
					end
				end)

				-- Keep the window inside the viewport when the game window resizes.
				if workspace.CurrentCamera then
					connect(workspace.CurrentCamera:GetPropertyChangedSignal("ViewportSize"), function()
						if frame.Visible then
							clampToViewport(frame)
						end
					end)
				end

				return window
			end

			---Human list of bound keys for the hint row.
			function Hub:_refreshHints()
				local parts = {}
				for _, entry in Hub._entries do
					if entry.Kind == "keybind" then
						local keyName = Hub.Values[entry.Flag]
						if keyName and keyName ~= "" then
							table.insert(parts, keyName .. " - " .. tostring(entry.Flag))
						end
					end
				end
				local hints = Hub._window and Hub._window.hints
				local label = hints and hints:FindFirstChildOfClass("TextLabel")
				if not label then
					return
				end
				if #parts == 0 then
					local key = Hub.menuKey or CONFIG.menuKey
					local name = type(key) == "table" and (key[1] or "RightShift") or tostring(key)
					label.Text = string.format("%s to toggle  |  ctrl+%s for hints", name, CONFIG.hintsKeys[1])
				else
					label.Text = table.concat(parts, "   |   ")
				end
			end

			-- Called by Components.Keybind through Hub.Values changes.
			local function refreshHintsSoon()
				task.defer(function()
					if Hub._window then
						Hub:_refreshHints()
					end
				end)
			end

			-- ======================================================================
			-- Public API
			-- ======================================================================

			---Build (or rebuild) the interface. Returns the hub table.
			function Hub:Init(options)
				options = options or {}
				if options.Title then
					CONFIG.title = options.Title
				end
				if options.Version then
					CONFIG.version = options.Version
				end
				if options.Tabs then
					CONFIG.tabs = options.Tabs
				end
				if options.MenuKey then
					Hub.menuKey = options.MenuKey
				end

				if Hub._screen and Hub._screen.Parent then
					Hub._screen:Destroy()
				end
				table.clear(Hub.Connections)
				table.clear(Hub.Searchables)
				table.clear(Hub._entries)

				buildWindow()

				-- Destroying the previous screen ran its Destroying handler, which
				-- nils _G.FatCatHub when it owns the identity. Put it back, or every
				-- game module that reads _G.FatCatHub after a rebuild sees nil and
				-- reports "the library is not loaded".
				_G.FatCatHub = Hub

				-- Builders run against the fresh window, in the order they were added,
				-- so a mounted module survives a rebuild.
				for _, builder in Hub._builders do
					local ok, builderError = pcall(builder, Hub, Hub._window)
					if not ok then
						warn("[Fat Cat] a mounted builder failed: " .. tostring(builderError))
					end
				end

				if Hub._window then
					local first = Hub._window.tabNames[1]
					if first and not Hub._window.selected then
						Hub._window:SelectTab(first)
					end
				end
				return Hub
			end

			---Build the window only once, on demand.
			function Hub:EnsureBuilt()
				if not Hub._window then
					Hub:Init(Hub._initOptions)
				end
				return Hub
			end

			---Destroy the GUI and every listener.
			function Hub:Destroy()
				if Hub._screen then
					Hub._screen:Destroy()
				end
				table.clear(Hub.Connections)
				if _G.FatCatHub == Hub then
					_G.FatCatHub = nil
				end
			end

			---Public "unload" alias used by loaders and game modules.
			function Hub:Unload()
				Hub:Destroy()
			end

			---Save every flag to disk. Called by the Config tab and by Auto Save.
			function Hub:Save(notify)
				local ok, result = writeJson(CONFIG.saveFile, Hub.Values)
				if notify then
					if ok then
						Hub:Notify("Settings saved", "success")
					else
						Hub:Notify("Save failed", "error", tostring(result))
					end
				end
				return ok, result
			end

			---Load flags from disk and apply them through their setters.
			function Hub:Load(notify)
				local data = readJson(CONFIG.saveFile)
				if not data then
					if notify then
						Hub:Notify("No settings found", "info", CONFIG.saveFile)
					end
					return false
				end
				for flag, value in data do
					local setter = Hub.Setters[flag]
					if setter then
						pcall(setter, value)
					end
				end
				refreshHintsSoon()
				if notify then
					Hub:Notify("Settings loaded", "success")
				end
				return true
			end

			---Reset every flag to its default.
			function Hub:Reset(notify)
				for flag, value in Hub.Defaults do
					local setter = Hub.Setters[flag]
					if setter then
						pcall(setter, value)
					end
				end
				refreshHintsSoon()
				if notify then
					Hub:Notify("Settings reset", "info")
				end
			end

			---Copy every flag to the clipboard as JSON.
			function Hub:Copy()
				if not setclipboard then
					Hub:Notify("Clipboard unavailable", "error")
					return false
				end
				setclipboard(httpService:JSONEncode(Hub.Values))
				Hub:Notify("Settings copied", "success")
				return true
			end

			---Register a builder that runs against the window once it exists.
			---Building the GUI immediately would make the library useless as a base:
			---anything added afterwards would need its own Hub:Init() call, which
			---throws the current window away.
			---
			---   Hub:Mount(function(hub, window)
			---       local page = window:Tab("Main")
			---       page:Section("Options"):Toggle({ Text = "Feature", Flag = "feature" })
			---   end)
			function Hub:Mount(builder)
				if type(builder) ~= "function" then
					return Hub
				end
				table.insert(Hub._builders, builder)
				Hub:EnsureBuilt()
				if Hub._window then
					local ok, builderError = pcall(builder, Hub, Hub._window)
					if not ok then
						warn("[Fat Cat] a mounted builder failed: " .. tostring(builderError))
					end
				end
				return Hub
			end

			---Forget every mounted builder and drop the window.
			function Hub:ClearBuilders()
				table.clear(Hub._builders)
				table.clear((Hub.Values))
				table.clear((Hub.Defaults))
				table.clear((Hub.Setters))
				table.clear((Hub.Keybinds))
				table.clear(Hub.Searchables)
				table.clear(Hub._entries)
				if Hub._window then
					Hub._window:AddTab(CONFIG.tabs[1])
				end
				return Hub
			end

			---Build the window and run the tabs in CONFIG.tabs, then every builder.
			---LazyBoot: a loader that wants to prepare first sets either
			---`_G.FatCatDeferBoot = true` (before running this chunk) or
			---`Hub.deferBoot = true`; the window is then only built by the first
			---Hub:Init()/Hub:Mount(). The global is checked here, at the point of use,
			---because a loader cannot reach the Hub table until this chunk has run.
			if not Hub.deferBoot and not _G.FatCatDeferBoot then
				Hub.Init(Hub._initOptions)
			else
				-- A loader asked to prepare first. The project's own bootstrapper then
				-- calls Hub.deferBoot = false before it mounts; the window is otherwise
				-- only built by the first Init()/Mount(). `Booted` is set by the
				-- generated bundle, so a bare shell download stays a shell and does not
				-- pretend a project is coming.
				Hub.pendingBoot = true
				Hub.bootWhenReady = not _G.FatCatProject
			end

			-- No `return` here on purpose: a return inside a do-block at the top level
			-- ends the whole chunk, so anything the loader appends after this file
			-- (a second module, a test spec) would never run. Loaders read
			-- _G.FatCatHub instead.
		end
		return true
	end
end

-- ---------------------------------------------------------------------
-- FatCatInit.lua -- the bootstrapper.
-- ---------------------------------------------------------------------
-- FatCatInit is a factory: it takes the module table and returns the
-- bootstrapper. Calling it with Modules is what makes the two halves
-- independent: the same file works from this bundle and from a
-- checkout that loads each module by hand.
local InitFactory = (function()
	-- Fat Cat Project | Core & Initialization/FatCatInit.lua
	--
	-- The bootstrapper. This file is the only one that knows the load order, and
	-- the only one that is allowed to decide that a failure is fatal.
	--
	--   local Init = FatCat.require("FatCatInit")
	--   local ok, status = Init.boot()
	--
	-- The contract, in four rules:
	--
	--   1. Core modules are fatal. If FatCatSignal, FatCatCore, FatCatEnv,
	--      FatCatConfig, FatCatDesign or FatCatMaterials cannot load, there is no
	--      product to show, so boot returns { ok = false, stage = ... }.
	--
	--   2. Feature modules are not fatal. A decompiler that throws on load costs
	--      its tab and nothing else: the error is captured, shown on that tab by
	--      FatCatMenu, and logged.
	--
	--   3. Every failure carries a stage. "It did not work" is useless; "FatCatMenu
	--      failed at mount" is a bug report.
	--
	--   4. A failure leaves a way out. When boot fails, an error card is drawn over
	--      the game and `getgenv().FatCatProjectUnload` is still installed, so the
	--      user can recover without restarting the client.
	--
	-- The module table is injected: the loader hands in `{ [name] = function }`
	-- so this file works both from the generated bundle and from a dev checkout
	-- that loads each file separately.

	return function(Modules)
		-- The executor environment. getgenv() exists on every executor, but not in
		-- a plain Luau VM (the test harness, a dev checkout), so it is guarded:
		-- without the guard this whole file fails at parse-adjacent time and no
		-- error card can explain it.
		local env = (typeof(getgenv) == "function" and getgenv()) or _G

		local Init = {}

		Init.VERSION = "2.1.0"
		Init.STAGE = nil

		-- Core modules: fatal when they fail.
		Init.CORE = { "FatCatSignal", "FatCatCore", "FatCatEnv", "FatCatConfig", "FatCatDesign", "FatCatMaterials" }

		-- Feature modules: one tab each, never fatal.
		Init.FEATURES = {
			"FatCatShell",
			"FatCatMath",
			"FatCatInspect",
			"FatCatCreate",
			"FatCatExtractor",
			"FatCatDecompiler",
			"FatCatStealer",
			"FatCatSpy",
			"FatCatProjectiles",
			"FatCatVMHook",
			"FatCatMemoryScanner",
			"FatCatEnvSpoofer",
			"FatCatUniversal",
			"FatCatConsole",
			"FatCatMenu",
		}

		local loaded = {}
		local failures = {}

		-- ==========================================================================
		-- Error reporting
		-- ==========================================================================

		local function tracebackOf(message)
			local ok, trace = pcall(function()
				return debug.traceback(tostring(message), 2)
			end)
			return ok and trace or tostring(message)
		end

		---Draw a card over the game explaining that boot failed. Wrapped in pcall
		---so a broken DataModel cannot turn an error report into a second error.
		local function showFailure(stage, message)
			local ok = pcall(function()
				local parent = game:GetService("CoreGui")
				local existing = parent:FindFirstChild("FatCatBootError")
				if existing then
					existing:Destroy()
				end

				local card = Instance.new("Frame")
				card.Name = "FatCatBootError"
				card.Size = UDim2.fromOffset(360, 132)
				card.Position = UDim2.new(0.5, -180, 0, 24)
				card.BackgroundColor3 = Color3.fromRGB(26, 26, 30)
				card.BorderSizePixel = 0
				card.ZIndex = 10
				card.Parent = parent

				local corner = Instance.new("UICorner")
				corner.CornerRadius = UDim.new(0, 8)
				corner.Parent = card

				local stroke = Instance.new("UIStroke")
				stroke.Color = Color3.fromRGB(232, 92, 96)
				stroke.Transparency = 0.35
				stroke.Parent = card

				local title = Instance.new("TextLabel")
				title.Text = ("[Fat Cat] no arrancó · %s"):format(tostring(stage))
				title.TextSize = 13
				title.Font = Enum.Font.GothamBold
				title.TextColor3 = Color3.fromRGB(232, 92, 96)
				title.BackgroundTransparency = 1
				title.TextXAlignment = Enum.TextXAlignment.Left
				title.Size = UDim2.new(1, -20, 0, 20)
				title.Position = UDim2.fromOffset(10, 8)
				title.Parent = card

				local body = Instance.new("TextLabel")
				-- First two lines: a full traceback in a 360 px card is unreadable
				-- and everything is in the executor console anyway.
				local firstLines = tostring(message):match("^[^\n]*\n?[^\n]*") or tostring(message)
				body.Text = firstLines
				body.TextSize = 11
				body.Font = Enum.Font.Gotham
				body.TextColor3 = Color3.fromRGB(198, 198, 204)
				body.TextWrapped = true
				body.TextYAlignment = Enum.TextYAlignment.Top
				body.TextXAlignment = Enum.TextXAlignment.Left
				body.BackgroundTransparency = 1
				body.Size = UDim2.new(1, -20, 0, 92)
				body.Position = UDim2.fromOffset(10, 30)
				body.Parent = card
				return card
			end)
			if not ok then
				warn(("[Fat Cat] boot failed at %s: %s"):format(tostring(stage), tostring(message)))
			end
		end
		Init.showFailure = showFailure

		---Remove the boot error card, if one is on screen.
		local function clearFailure()
			pcall(function()
				local existing = game:GetService("CoreGui"):FindFirstChild("FatCatBootError")
				if existing then
					existing:Destroy()
				end
			end)
		end

		local function fail(stage, message)
			Init.STAGE = stage
			local full = tracebackOf(message)
			failures[stage] = full
			warn(("[Fat Cat] boot failed at %s:\n%s"):format(tostring(stage), full))
			showFailure(stage, message)
			return { ok = false, stage = stage, error = tostring(message), traceback = full }
		end

		-- ==========================================================================
		-- Module loading
		-- ==========================================================================

		---Read a module that is not a factory (FatCatSignal is a table, FatCatCore
		---is a table). Returns the value or nil plus a reason.
		local function value(name)
			if type(Modules) ~= "table" then
				return nil, "the loader gave FatCatInit no module table"
			end
			local module = Modules[name]
			if module == nil then
				return nil, ("no module named '%s' in this build"):format(name)
			end
			return module
		end

		---The world every module is constructed with. `core` is added after
		---FatCatCore loads; until then the field is nil on purpose.
		local context = {
			signal = nil,
			core = nil,
			design = nil,
			materials = nil,
			math = nil,
			env = nil,
			modules = Modules,
			loaded = loaded,
		}

		---Load a factory module: source() then call it with the arguments this
		---specific module expects. The switch is explicit because the signatures
		---differ; a uniform context object would let a typo pass silently.
		local function factory(name)
			if type(Modules) ~= "table" then
				return nil, "the loader gave FatCatInit no module table"
			end
			local chunk = Modules[name]
			if chunk == nil then
				return nil, ("no module named '%s' in this build"):format(name)
			end
			if type(chunk) ~= "function" then
				-- A plain table (a module that needs no construction, or one the
				-- loader already built) is used as it is.
				return chunk
			end

			-- FatCatConfig and FatCatDesign are the two modules built with the
			-- signal bus, because both create signals during construction.
			-- FatCatEnv does not: it takes the same two arguments for symmetry but
			-- only reads the first, and passing the bus keeps every core module's
			-- signature identical.
			local args = { context.core, context.signal }
			if name == "FatCatDesign" then
				args = { context.core, context.signal }
			elseif name == "FatCatMaterials" then
				args = { context.core, context.design, context.signal }
			elseif name == "FatCatMath" then
				args = { context.core }
			elseif name == "FatCatInspect" or name == "FatCatDecompiler" or name == "FatCatExtractor"
				or name == "FatCatStealer" or name == "FatCatMemoryScanner" or name == "FatCatEnvSpoofer" then
				args = { context.core, context.materials }
			elseif name == "FatCatSpy" then
				args = { context.core, context.signal, context.materials }
			elseif name == "FatCatVMHook" then
				args = { context.core, context.signal, context.materials }
			elseif name == "FatCatProjectiles" then
				args = { context.core, context.math, context.materials }
			elseif name == "FatCatUniversal" then
				args = { context.core, context.design, context.signal, context.math }
			elseif name == "FatCatCreate" then
				args = { context.core, context.design, context.signal, context.materials }
			elseif name == "FatCatConsole" then
				args = { context.core, context.signal, context.materials }
			elseif name == "FatCatMenu" then
				args = { context.core, context.design, context.signal, context.materials }
			elseif name == "FatCatShell" then
				-- The shell is a chunk, not a factory: running it defines
				-- _G.FatCatHub and builds the window. It blocks at runtime
				-- (`if not Hub.deferBoot then Hub.Init(...) end`), so the loader
				-- has to raise this flag before the shell runs, not after.
				args = {}
				env.FatCatDeferBoot = true
			end

			local ok, result = pcall(chunk, table.unpack(args))
			if not ok then
				return nil, ("%s failed to construct: %s"):format(name, tostring(result))
			end
			if result == nil then
				result = true
			end
			return result
		end

		-- ==========================================================================
		-- Boot
		-- ==========================================================================

		---Boot the whole project. Returns { ok, stage, core } on success and
		---{ ok = false, stage, error, traceback } on failure.
		function Init.boot(options)
			options = options or {}

			-- 0. Refuse to run twice in the same environment. A second boot leaves
			--    two windows, two render loops and two sets of hooks on the same
			--    globals, which is how a menu ends up duplicating itself per reload.
			local previous = env.FatCatProject
			if previous ~= nil and type(previous.Destroy) == "function" and not options.force then
				local clean, reason = pcall(previous.Destroy, previous)
				if not clean then
					return fail("precheck", "the previous instance could not be torn down: " .. tostring(reason))
				end
			end

			-- 1. Signals: everything below can fire events, so this is first.
			Init.STAGE = "FatCatSignal"
			local Signal, signalWhy = value("FatCatSignal")
			if not Signal then
				return fail("FatCatSignal", signalWhy)
			end
			context.signal = Signal
			loaded.FatCatSignal = Signal

			-- 2. Core: the registry the other modules live in.
			Init.STAGE = "FatCatCore"
			local Core, coreWhy = value("FatCatCore")
			if type(Core) ~= "table" then
				return fail("FatCatCore", coreWhy or "FatCatCore did not return a table")
			end
			Core.env = env
			context.core = Core
			loaded.FatCatCore = Core

			-- Announce the global early, so a module that logs during load can
			-- already find the project and its logger.
			_G.FatCatProject = Core

			-- 3. The rest of the core modules, in dependency order.
			for _, name in { "FatCatEnv", "FatCatConfig", "FatCatDesign", "FatCatMaterials", "FatCatMath" } do
				Init.STAGE = name
				local module, why = factory(name)
				if module == nil then
					if name == "FatCatMath" then
						-- Math is used by two features, not by the core; a failure
						-- here costs the trajectory tools, not the menu.
						failures[name] = tostring(why)
						Core:Log("warn", why)
					else
						return fail(name, why)
					end
				else
					loaded[name] = module
					if name == "FatCatEnv" then
						context.env = module
						-- Detection is cheap and runs before any feature asks
						-- "can this executor do X".
						pcall(module.detect)
					elseif name == "FatCatConfig" then
						context.config = module
					elseif name == "FatCatDesign" then
						context.design = module
					elseif name == "FatCatMaterials" then
						context.materials = module
					elseif name == "FatCatMath" then
						context.math = module
					end
				end
			end

			-- 4. The window shell: it defines _G.FatCatHub and is what the menu
			--    mounts onto. Fatal, because without it there is nowhere to draw.
			Init.STAGE = "FatCatShell"
			local shell, shellWhy = factory("FatCatShell")
			if shell == nil then
				return fail("FatCatShell", shellWhy)
			end
			loaded.FatCatShell = shell or true

			-- 5. Register every module with Core, including the core ones that were
			--    constructed above. A caller that asks Core:Require("FatCatSignal")
			--    must get the table back, not "no module registered": the registry
			--    is the public entry point for every module, so it cannot be
			--    missing entries just because the bootstrapper built them itself.
			for name, module in loaded do
				Core.modules[name] = module
				Core:Register(name, function()
					return module
				end)
			end

			for _, name in Init.FEATURES do
				Core:Register(name, function()
					local module, why = factory(name)
					if module == nil then
						error(why, 0)
					end
					loaded[name] = module
					return module
				end)
			end

			Init.STAGE = "FatCatConsole"
			local console, consoleWhy = Core:TryRequire("FatCatConsole")
			if console then
				console.attach()
				context.console = console
			else
				failures.FatCatConsole = tostring(consoleWhy)
			end

			-- 6. The menu. This is the first step that draws anything, so every
			--    prior failure is visible in the log before the window exists.
			Init.STAGE = "FatCatMenu"
			local menu, menuWhy = Core:TryRequire("FatCatMenu")
			if not menu then
				return fail("FatCatMenu", menuWhy)
			end

			local built, buildWhy = menu.build()
			if not built then
				return fail("FatCatMenu.build", buildWhy)
			end

			-- 7. Unload hook and a final report.
			env.FatCatProjectUnload = function()
				local runtime = context.env
				if runtime and type(runtime.unload) == "function" then
					return runtime.unload()
				end
				return Core:Destroy()
			end
			env.FatCatProjectVersion = Init.VERSION

			clearFailure()
			Init.STAGE = "ready"
			Core:Log("info", ("%s listo · %s · %d módulo(s)")
				:format(Core.NAME, context.env and context.env.name or "?", #Core.loadOrder))

			if context.env and type(context.env.report) == "function" and env.FatCatVerbose then
				context.env.report()
			end

			local result = {
				ok = true,
				stage = "ready",
				core = Core,
				env = context.env,
				menu = menu,
				loaded = loaded,
				failures = failures,
				version = Init.VERSION,
				-- What the loader reads to print "ready - N modules".
				modules = #Core.loadOrder,
				executor = context.env and context.env.name or "unknown",
			}
			Init.booted = result
			return result
		end

		---Boot, but never throw: the loader calls this and only sees a table.
		function Init.safeBoot(options)
			local ok, result = pcall(Init.boot, options)
			if ok then
				return result
			end
			return fail(Init.STAGE or "boot", result)
		end

		---One-line status for the loader and for bug reports.
		---"Fat Cat 2.1.0 · 15 module(s) · 2 failed (FatCatSpy, FatCatStealer)"
		function Init.report()
			local core = _G.FatCatProject
			if not core then
				return "Fat Cat is not loaded"
			end
			local failed = {}
			for name in failures do
				table.insert(failed, name)
			end
			table.sort(failed)
			local text = ("%s %s · %d module(s)"):format(core.NAME, Init.VERSION, #core.loadOrder)
			if #failed > 0 then
				text ..= (" · %d failed (%s)"):format(#failed, table.concat(failed, ", "))
			end
			return text
		end

		---Tear down whatever boot built. Safe before boot (does nothing).
		function Init.shutdown()
			clearFailure()
			local core = _G.FatCatProject
			if core and type(core.Destroy) == "function" then
				return core:Destroy()
			end
			return 0
		end

		---Version of a module by name, or nil.
		function Init.versionOf(name)
			local module = loaded[name]
			if type(module) == "table" and type(module.VERSION) == "string" then
				return module.VERSION
			end
			return nil
		end

		return Init
	end
end)()
local Init = InitFactory(Modules)

-- Which modules this build actually contains. A loader that fetches a
-- subset can still give FatCatInit a smaller table and get a clear
-- 'no module named X' instead of a nil call.
local Available = {
	['FatCatSignal'] = true,
	['FatCatCore'] = true,
	['FatCatEnv'] = true,
	['FatCatConfig'] = true,
	['FatCatDesign'] = true,
	['FatCatMaterials'] = true,
	['FatCatMath'] = true,
	['FatCatInspect'] = true,
	['FatCatCreate'] = true,
	['FatCatExtractor'] = true,
	['FatCatDecompiler'] = true,
	['FatCatStealer'] = true,
	['FatCatSpy'] = true,
	['FatCatProjectiles'] = true,
	['FatCatVMHook'] = true,
	['FatCatMemoryScanner'] = true,
	['FatCatEnvSpoofer'] = true,
	['FatCatUniversal'] = true,
	['FatCatConsole'] = true,
	['FatCatMenu'] = true,
	['FatCatShell'] = true
}

do -- refuse to run with a hole in the build
	for name in Available do
		if Modules[name] == nil then
			print(('[Fat Cat] the bundle is missing %s; rebuild with tools/build_bundle.py'):format(name))
		end
	end
end

-- Which file each module came from, for bug reports and for the
-- 'where is this defined' question. Not read at runtime.
Init.files = {
	['FatCatSignal'] = 'src/project/FatCatSignal.lua',
	['FatCatCore'] = 'src/project/FatCatCore.lua',
	['FatCatEnv'] = 'src/project/FatCatEnv.lua',
	['FatCatConfig'] = 'src/project/FatCatConfig.lua',
	['FatCatDesign'] = 'src/project/FatCatDesign.lua',
	['FatCatMaterials'] = 'src/project/FatCatMaterials.lua',
	['FatCatMath'] = 'src/project/FatCatMath.lua',
	['FatCatInspect'] = 'src/project/FatCatInspect.lua',
	['FatCatCreate'] = 'src/project/FatCatCreate.lua',
	['FatCatExtractor'] = 'src/project/FatCatExtractor.lua',
	['FatCatDecompiler'] = 'src/project/FatCatDecompiler.lua',
	['FatCatStealer'] = 'src/project/FatCatStealer.lua',
	['FatCatSpy'] = 'src/project/FatCatSpy.lua',
	['FatCatProjectiles'] = 'src/project/FatCatProjectiles.lua',
	['FatCatVMHook'] = 'src/project/FatCatVMHook.lua',
	['FatCatMemoryScanner'] = 'src/project/FatCatMemoryScanner.lua',
	['FatCatEnvSpoofer'] = 'src/project/FatCatEnvSpoofer.lua',
	['FatCatUniversal'] = 'src/project/FatCatUniversal.lua',
	['FatCatConsole'] = 'src/project/FatCatConsole.lua',
	['FatCatMenu'] = 'src/project/FatCatMenu.lua',
	['FatCatShell'] = 'src/FatCatHub.lua'
}

-- Boot. Returning as a value (`return Init, Booted`) instead of running
-- the boot at the call site is what lets this file also be
-- concatenated into a test harness: a top-level `return` would end the
-- chunk and the assertions after it would never run. `pcall` because
-- Init.safeBoot never throws, but a broken DataModel must not take the
-- executor down with it either.
local Booted = Init.safeBoot()
Init.booted = Booted
return Init, Booted
